INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91159, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "套是几样东西合成的一份。", "primary_collocate": null, "pronunciation": "tào", "ipa": "tʰau˥˩", "syllable_count": 1, "sentences": [{"text": "她送我一套漂亮的茶具。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一套餐具。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们一套新课本。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书一共有五本。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一套工具。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我收藏了一套老邮票。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套积木有一百块。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这套画册送给了朋友。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套练习题很难。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有一套很贵的化妆品。", "target_word": "套", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "量词，用于配成一份的茶具、餐具、书、工具等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "套", "is_correct": true, "explanation": "套 tào：几样东西合成的一份，正确答案。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo（第三声）与 tào 声调不同，意思是索取、讨论。"}, {"text": "桃", "is_correct": false, "explanation": "桃 táo（第二声）与 tào 声调不同，意思是桃子。"}, {"text": "道", "is_correct": false, "explanation": "道 dào 声母 d 与 t 不同（不送气），意思是道路。"}, {"text": "烫", "is_correct": false, "explanation": "烫 tàng 韵母 ang 与 ao 不同，意思是加热或烫伤。"}], "explanations": {"套": "套 tào：几样东西合成的一份，正确答案。", "讨": "讨 tǎo（第三声）与 tào 声调不同，意思是索取、讨论。", "桃": "桃 táo（第二声）与 tào 声调不同，意思是桃子。", "道": "道 dào 声母 d 与 t 不同（不送气），意思是道路。", "烫": "烫 tàng 韵母 ang 与 ao 不同，意思是加热或烫伤。"}, "sentence_index": null, "correct_answer": "套"}, "level_3": {"options": [{"text": "套", "is_correct": true, "explanation": "套：成套的器具，与“茶具”搭配，表示一整套。"}, {"text": "支", "is_correct": false, "explanation": "体貌：“支”用于细长的棍状物，茶具不是这种形状。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”用于块状的东西，茶具不用“块”计量。"}, {"text": "座", "is_correct": false, "explanation": "体貌：“座”指大型、固定的东西，茶具不是这样的东西。"}], "explanations": {"套": "套：成套的器具，与“茶具”搭配，表示一整套。", "支": "体貌：“支”用于细长的棍状物，茶具不是这种形状。", "块": "搭配：“块”用于块状的东西，茶具不用“块”计量。", "座": "体貌：“座”指大型、固定的东西，茶具不是这样的东西。"}, "sentence_index": 0, "correct_answer": "套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃了一套苹果。", "explanation": "这里应该用〈个〉。苹果是单个的水果，不是成组的东西，不能说一套。"}, {"text": "我们学校来了一套新学生。", "explanation": "这里应该用〈批〉。学生成批地来，要用“批”计量，不能说一套。"}, {"text": "我们在河上修了一套桥。", "explanation": "这里应该用〈座〉。桥是大型的建筑，要用“座”计量，不能说一套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91159, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "套", "is_correct": true, "explanation": "套 tào：几样东西合成的一份，正确答案。"}, {"text": "掏", "is_correct": false, "explanation": "掏 tāo（第一声）与 tào 声调不同，意思是把手伸进去取东西。"}, {"text": "逃", "is_correct": false, "explanation": "逃 táo（第二声）与 tào 声调不同，意思是逃跑。"}, {"text": "透", "is_correct": false, "explanation": "透 tòu 韵母 ou 与 ao 不同，意思是穿过、通透。"}, {"text": "淘", "is_correct": false, "explanation": "淘 táo（第二声）与 tào 声调不同，意思是淘洗。"}], "explanations": {"套": "套 tào：几样东西合成的一份，正确答案。", "掏": "掏 tāo（第一声）与 tào 声调不同，意思是把手伸进去取东西。", "逃": "逃 táo（第二声）与 tào 声调不同，意思是逃跑。", "透": "透 tòu 韵母 ou 与 ao 不同，意思是穿过、通透。", "淘": "淘 táo（第二声）与 tào 声调不同，意思是淘洗。"}, "sentence_index": null, "correct_answer": "套"}, "level_3": {"options": [{"text": "套", "is_correct": true, "explanation": "套：配成一份的玩具，与“积木”搭配，表示一整套。"}, {"text": "根", "is_correct": false, "explanation": "体貌：“根”指细长的东西，积木不是细长的。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对器物中的一个，不用于积木。"}, {"text": "张", "is_correct": false, "explanation": "体貌：“张”指扁平的东西，积木不是扁平的。"}], "explanations": {"套": "套：配成一份的玩具，与“积木”搭配，表示一整套。", "根": "体貌：“根”指细长的东西，积木不是细长的。", "只": "搭配：“只”用于动物或成对器物中的一个，不用于积木。", "张": "体貌：“张”指扁平的东西，积木不是扁平的。"}, "sentence_index": 6, "correct_answer": "套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空中有一套明亮的星星。", "explanation": "这里应该用〈颗〉。星星是单个的天体，要用“颗”计量，不能说一套。"}, {"text": "院子里爬过一套蚂蚁。", "explanation": "这里应该用〈群〉。蚂蚁成群爬过，要用“群”计量，不能说一套。"}, {"text": "昨天下了一套大雨。", "explanation": "这里应该用〈场〉。下雨是一次性的事件，要用“场”计量，不能说一套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation