INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91160, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "套", "is_correct": true, "explanation": "套 tào：量词，用于成组的东西，正确答案。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo（第三声）与 tào 声调不同，意思是索取、讨论。"}, {"text": "逃", "is_correct": false, "explanation": "逃 táo（第二声）与 tào 声调不同，意思是逃跑。"}, {"text": "烫", "is_correct": false, "explanation": "烫 tàng 韵母 ang 与 ao 不同，意思是加热或烫伤。"}, {"text": "淘", "is_correct": false, "explanation": "淘 táo（第二声）与 tào 声调不同，意思是淘洗。"}], "explanations": {"套": "套 tào：量词，用于成组的东西，正确答案。", "讨": "讨 tǎo（第三声）与 tào 声调不同，意思是索取、讨论。", "逃": "逃 táo（第二声）与 tào 声调不同，意思是逃跑。", "烫": "烫 tàng 韵母 ang 与 ao 不同，意思是加热或烫伤。", "淘": "淘 táo（第二声）与 tào 声调不同，意思是淘洗。"}, "sentence_index": null, "correct_answer": "套"}, "level_3": {"options": [{"text": "套", "is_correct": true, "explanation": "套：成套的家具，与“沙发”搭配，表示一整套。"}, {"text": "扇", "is_correct": false, "explanation": "搭配：“扇”用于门、窗，不用于沙发。"}, {"text": "片", "is_correct": false, "explanation": "体貌：“片”指扁平薄片的东西，沙发不是这种形状。"}, {"text": "双", "is_correct": false, "explanation": "搭配：“双”用于成对的东西，如鞋袜，沙发不用“双”。"}], "explanations": {"套": "套：成套的家具，与“沙发”搭配，表示一整套。", "扇": "搭配：“扇”用于门、窗，不用于沙发。", "片": "体貌：“片”指扁平薄片的东西，沙发不是这种形状。", "双": "搭配：“双”用于成对的东西，如鞋袜，沙发不用“双”。"}, "sentence_index": 6, "correct_answer": "套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在国外爬了一套雪山。", "explanation": "这里应该用〈座〉。“套”用于成组的东西，山要用“座”计量。"}, {"text": "院子里有一套石头。", "explanation": "这里应该用〈堆〉。石头堆在一起，要用“堆”计量，不能说一套。"}, {"text": "我们农场有一套大牛。", "explanation": "这里应该用〈头〉。牛是单个的动物，要用“头”计量，不能说一套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =