INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一个套新衣服。", "corrected_sentence": "她买了一套新衣服。", "error_description": "错误：“套”前又加了量词“个”，一个数量短语只用一个量词。应为“一套新衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一套的新睡衣。", "corrected_sentence": "他买了一套新睡衣。", "error_description": "错误：“套”后多加了“的”。数量短语直接修饰名词，中间不加“的”，应为“一套新睡衣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
