INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91161, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和数是把几个数加起来得到的数。", "primary_collocate": null, "pronunciation": "hé shù", "ipa": "xɤ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "三加五的和数是八。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请算一下这两个数的和数。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十加二十的和数是三十。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要求出四个数的和数。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算错了和数，所以答案不对。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个加数都是正数时，和数比每一个加数都大。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写出了和数。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个数的和数是一百。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先把三个数加起来，再看和数是多少。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它们的和数等于二十五。", "target_word": "和数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和數", "label": "繁体"}], "register": "书面", "sense_fingerprint": "几个数加在一起得到的数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3f596a-ea6f-4092-8aea-7d56453cebea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和数", "is_correct": true, "explanation": "“和数”指几个数相加的结果，三加五的结果是八，符合句意。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差”是减法的结果，三加五是加法，不能说“三加五的差”。"}, {"text": "积", "is_correct": false, "explanation": "语义：“积”是乘法的结果，三加五不是乘法，句子说不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”指平面的大小，不能用来表示数的加法结果。"}], "explanations": {"和数": "“和数”指几个数相加的结果，三加五的结果是八，符合句意。", "差": "语义：“差”是减法的结果，三加五是加法，不能说“三加五的差”。", "积": "语义：“积”是乘法的结果，三加五不是乘法，句子说不通。", "面积": "搭配：“面积”指平面的大小，不能用来表示数的加法结果。"}, "sentence_index": 0, "correct_answer": "和数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三乘四的和数是十二。", "explanation": "这里应该用〈积〉。乘法的结果用“积”，“和数”只指加法的结果。"}, {"text": "十减三的和数是七。", "explanation": "这里应该用〈差〉。减法的结果用“差”，“和数”只指加法的结果。"}, {"text": "十二除以三的和数是四。", "explanation": "这里应该用〈商〉。除法的结果用“商”，“和数”只指加法的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和数", "is_correct": true, "explanation": "“和数”指几个数相加的结果，老师可以在黑板上写出这个结果，符合句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是坐的家具，不是可以在黑板上写出来的内容，句子说不通。"}, {"text": "影子", "is_correct": false, "explanation": "语义：“影子”是光线照出的暗影，老师不能在黑板上写出它。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是计时的器具，不是可以写出来的内容，句子说不通。"}], "explanations": {"和数": "“和数”指几个数相加的结果，老师可以在黑板上写出这个结果，符合句意。", "椅子": "语义：“椅子”是坐的家具，不是可以在黑板上写出来的内容，句子说不通。", "影子": "语义：“影子”是光线照出的暗影，老师不能在黑板上写出它。", "闹钟": "语义：“闹钟”是计时的器具，不是可以写出来的内容，句子说不通。"}, "sentence_index": 6, "correct_answer": "和数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "五乘五的和数是二十五。", "explanation": "这里应该用〈积〉。乘法的结果用“积”，“和数”只指加法的结果。"}, {"text": "这场比赛的和数是九十分钟。", "explanation": "这里应该用〈时长〉。“和数”只指几个数相加的结果，不能用来说比赛的长度。"}, {"text": "十八除以六的和数是三。", "explanation": "这里应该用〈商〉。除法的结果用“商”，“和数”只指加法的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "四加六和数是十。", "corrected_sentence": "四加六的和数是十。", "error_description": "助词错误：“和数”前的修饰语“四加六”后要加“的”，漏掉“的”就不自然。应说“四加六的和数是十”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他算出着八加七的和数。", "corrected_sentence": "他算出了八加七的和数。", "error_description": "“算出”表示动作已经完成，要用“了”，不能用“着”。正确说法是“他算出了八加七的和数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e18104fa-a358-4bc0-851f-9be12b2dee58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正面", "is_correct": true, "explanation": "“正面”指事物好的一边，与“负面”相对，是反义词。"}, {"text": "中心", "is_correct": false, "explanation": "“中心”指中间的位置，与“负面”没有反义关系。"}, {"text": "外观", "is_correct": false, "explanation": "“外观”指事物的外部形状，与“负面”没有反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "“声音”指声响，与“负面”没有反义关系。"}], "correct_answer": "正面", "explanations": {"正面": "“正面”指事物好的一边，与“负面”相对，是反义词。", "中心": "“中心”指中间的位置，与“负面”没有反义关系。", "外观": "“外观”指事物的外部形状，与“负面”没有反义关系。", "声音": "“声音”指声响，与“负面”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正面", "is_correct": true, "explanation": "“正面”指事物好的一边，与“负面”相对，是反义词。"}, {"text": "外观", "is_correct": false, "explanation": "“外观”指事物的外部形状，与“负面”没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”指时段或时刻，与“负面”没有反义关系。"}, {"text": "方向", "is_correct": false, "explanation": "“方向”指所朝的位置，与“负面”没有反义关系。"}], "correct_answer": "正面", "explanations": {"正面": "“正面”指事物好的一边，与“负面”相对，是反义词。", "外观": "“外观”指事物的外部形状，与“负面”没有反义关系。", "时间": "“时间”指时段或时刻，与“负面”没有反义关系。", "方向": "“方向”指所朝的位置，与“负面”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不好的那一边。", "primary_collocate": null, "pronunciation": "fù miàn", "ipa": "fu˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "每件事都有正面和负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看事情的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事也有它的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是只看到生活的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机有正面，也有负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络的负面，老师已经跟我们说过了。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢谈工作的负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要看到问题的正面和负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做的负面是花钱太多。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的一面他不说，只说负面。", "target_word": "负面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "负面影响", "label": "复合"}, {"form": "负面情绪", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情不好的一边，与好的一面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae0e34c9-59ed-46c9-8c20-e1198d73bf8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "负面", "is_correct": true, "explanation": "“负面”指事物不好的一边，与“正面”相对，可以和“正面”并列说事情的两面。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能与“正面”并列说事情的两面。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指声响，不能与“正面”并列说事情的两面。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”说时间长短，不能与“正面”并列描述事情。"}], "explanations": {"负面": "“负面”指事物不好的一边，与“正面”相对，可以和“正面”并列说事情的两面。", "颜色": "语义：“颜色”指色彩，不能与“正面”并列说事情的两面。", "声音": "语义：“声音”指声响，不能与“正面”并列说事情的两面。", "年龄": "搭配：“年龄”说时间长短，不能与“正面”并列描述事情。"}, "sentence_index": 0, "correct_answer": "负面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸的负面写着一行字。", "explanation": "这里应该用〈反面〉。“负面”指事情不好的一边，纸张的背面要用“反面”。"}, {"text": "这块木板的负面很光滑。", "explanation": "这里应该用〈底面〉。“负面”指事情不好的一边，木板的底部要用“底面”，不能说“负面”。"}, {"text": "这面墙的负面贴着一张地图。", "explanation": "这里应该用〈背面〉。墙的后面要用“背面”，“负面”指事情不好的一边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "负面", "is_correct": true, "explanation": "“负面”指工作不好的一面，可以谈论。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”是器官，不能作“谈”的对象。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“谈工作的尺寸”不搭，“尺寸”不指工作的内容。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：“鞋码”指鞋的大小，与谈论工作无关。"}], "explanations": {"负面": "“负面”指工作不好的一面，可以谈论。", "眼睛": "语义：“眼睛”是器官，不能作“谈”的对象。", "尺寸": "搭配：“谈工作的尺寸”不搭，“尺寸”不指工作的内容。", "鞋码": "语义：“鞋码”指鞋的大小，与谈论工作无关。"}, "sentence_index": 6, "correct_answer": "负面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节电池的负面接触不好。", "explanation": "这里应该用〈负极〉。“负面”指不好的一边，电池的负电极要用“负极”，不能说“负面”。"}, {"text": "她背着很重的心理负面，很少笑。", "explanation": "这里应该用〈负担〉。“负面”指不好的一边，心里的压力要用“负担”。"}, {"text": "这栋楼的负面有一扇小门。", "explanation": "这里应该用〈背面〉。楼房的后面要用“背面”，“负面”指不好的一边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈只看到这个办法负面。", "corrected_sentence": "妈妈只看到这个办法的负面。", "error_description": "缺少“的”：“负面”是名词，作“看到”的宾语，前面的“这个办法”修饰它时要加“的”。错误形式为“办法负面”，正确形式为“办法的负面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不想说这个计划的很负面。", "corrected_sentence": "他不想说这个计划的负面。", "error_description": "这里“负面”是名词，指不好的一边，不能受程度副词“很”修饰。错误形式为“的很负面”，正确形式为“的负面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0857a31d-f40c-40e6-b36d-e93891a4b408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "如是的意思是像这样。", "primary_collocate": null, "pronunciation": "rú shì", "ipa": "ɻu˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他的性格一向如是，从不改变。", "target_word": "如是", "complexity_tier": "T3", "furigana": "tā de xìng gé yí xiàng rú shì, cóng bù gǎi biàn.", "sentence_source": "generated"}, {"text": "情况如是，我们只好回家。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一切如是，不用担心。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "写文章如是，做研究也如是。", "target_word": "如是", "complexity_tier": "T3", "furigana": "xiě wén zhāng rú shì, zuò yán jiū yě rú shì.", "sentence_source": "generated"}, {"text": "做人如是，做事也如是。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多年来，他们的生活一直如是。", "target_word": "如是", "complexity_tier": "T3", "furigana": "duō nián lái, tā men de shēng huó yì zhí rú shì.", "sentence_source": "generated"}, {"text": "事实如是，请你相信我。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "结果如是，大家都很失望。", "target_word": "如是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的为人一向如是，你不必怀疑他。", "target_word": "如是", "complexity_tier": "T3", "furigana": "tā de wéi rén yí xiàng rú shì, nǐ bú bì huái yí tā.", "sentence_source": "generated"}, {"text": "他一生都如是，从没改变过。", "target_word": "如是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语代词，指像这样、就是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确答案：如是（rú shì），意思是像这样。"}, {"text": "如实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。"}, {"text": "入室", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入室”意思是进入房间。"}, {"text": "入市", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入市”意思是进入市场。"}], "explanations": {"如是": "正确答案：如是（rú shì），意思是像这样。", "如实": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。", "入室": "rù（第四声）与 rú（第二声）声调不同，“入室”意思是进入房间。", "入市": "rù（第四声）与 rú（第二声）声调不同，“入市”意思是进入市场。"}, "sentence_index": null, "correct_answer": "如是"}, "level_3": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确。“他的性格一向如是”指性格一直像这样。"}, {"text": "如何", "is_correct": false, "explanation": "语义：“如何”是疑问代词，句子要的是表示“像这样”的陈述，这里不能用疑问词。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：“一向”后面接的是陈述，不接“怎样”这样的疑问代词，句子不通。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，无法指代前面的情况，这里句子说不通。"}], "explanations": {"如是": "正确。“他的性格一向如是”指性格一直像这样。", "如何": "语义：“如何”是疑问代词，句子要的是表示“像这样”的陈述，这里不能用疑问词。", "怎样": "搭配：“一向”后面接的是陈述，不接“怎样”这样的疑问代词，句子不通。", "什么": "语义：“什么”是疑问代词，无法指代前面的情况，这里句子说不通。"}, "sentence_index": 0, "correct_answer": "如是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如是你不同意，那就算了吧。", "explanation": "错误：“如是”是代词，意思是“像这样”，不能当连词引出假设；这里应该用〈如果〉。"}, {"text": "如是下雨，我们就改到明天。", "explanation": "错误：“如是”不能表示假设条件；这里应该用〈如果〉。"}, {"text": "如是大家都同意，这事就定下来了。", "explanation": "错误：“如是”是代词，不是假设连词；这里应该用〈如果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确答案：如是（rú shì），意思是像这样。"}, {"text": "入世", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入世”意思是投身社会。"}, {"text": "如实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。"}, {"text": "入时", "is_correct": false, "explanation": "rù 与 rú 声调不同，shí 与 shì 声调也不同，“入时”意思是时髦。"}], "explanations": {"如是": "正确答案：如是（rú shì），意思是像这样。", "入世": "rù（第四声）与 rú（第二声）声调不同，“入世”意思是投身社会。", "如实": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。", "入时": "rù 与 rú 声调不同，shí 与 shì 声调也不同，“入时”意思是时髦。"}, "sentence_index": null, "correct_answer": "如是"}, "level_3": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确。“事实如是”指事实就是这样，后文要求对方相信。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能指代“事实”的情况，句子说不通。"}, {"text": "哪个", "is_correct": false, "explanation": "搭配：“事实”后面不接“哪个”，这样说不成句子。"}, {"text": "这些", "is_correct": false, "explanation": "配价：“这些”是复数指示词，不能直接作“事实”的谓语，句子不通。"}], "explanations": {"如是": "正确。“事实如是”指事实就是这样，后文要求对方相信。", "谁": "语义：“谁”指人，不能指代“事实”的情况，句子说不通。", "哪个": "搭配：“事实”后面不接“哪个”，这样说不成句子。", "这些": "配价：“这些”是复数指示词，不能直接作“事实”的谓语，句子不通。"}, "sentence_index": 6, "correct_answer": "如是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如是你不喜欢，我们就换一家。", "explanation": "错误：“如是”是代词，意思是“像这样”，不能当连词引出假设；这里应该用〈如果〉。"}, {"text": "如是他明天不来，我们就另想办法。", "explanation": "错误：“如是”不能表示假设条件；这里应该用〈如果〉。"}, {"text": "如是有人问起，你就说我不在。", "explanation": "错误：“如是”是代词，不是假设连词；这里应该用〈如果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的态度一向如是了，我们早习惯了。", "corrected_sentence": "他的态度一向如是，我们早习惯了。", "error_description": "“了”误用：“一向如是”描述的是一贯保持的状态，“如是”后面不加“了”。正确说法：他的态度一向如是，我们早习惯了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直很如是，我们早就习惯了。", "corrected_sentence": "他一直如是，我们早就习惯了。", "error_description": "程度副词误用：“如是”是代词，不能受“很”修饰，应去掉“很”。正确说法：他一直如是，我们早就习惯了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
