INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91166, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "这样；如此（文言用法）。", "primary_collocate": null, "pronunciation": "rú shì", "ipa": "ɻu˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "古人云：“学无止境”，人生亦如是。", "target_word": "如是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世事如是，不必强求。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "成败如是，何必多想。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爱情如是，友情亦如是。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天下之事，大都如是。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨日如是，今日如是，明日也如是。", "target_word": "如是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春去秋来，岁月如是。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "读书如是，做事亦如是。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她笑着说：“事已如是，不必再问。”", "target_word": "如是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生如是，苦乐相伴。", "target_word": "如是", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "文言", "sense_fingerprint": "文言用法，指这样、如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ef076da-1144-4cb2-9ae1-fa1a201e95f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91166, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确答案：如是（rú shì），文言用法，意思是这样、如此。"}, {"text": "如实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。"}, {"text": "入室", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入室”意思是进入房间。"}, {"text": "入市", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入市”意思是进入市场。"}], "explanations": {"如是": "正确答案：如是（rú shì），文言用法，意思是这样、如此。", "如实": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。", "入室": "rù（第四声）与 rú（第二声）声调不同，“入室”意思是进入房间。", "入市": "rù（第四声）与 rú（第二声）声调不同，“入市”意思是进入市场。"}, "sentence_index": null, "correct_answer": "如是"}, "level_3": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确。“人生亦如是”指人生也是这样。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能指代前面说的情况，句子说不通。"}, {"text": "哪个", "is_correct": false, "explanation": "搭配：“亦”后面不接“哪个”，这里句子不通。"}, {"text": "这些", "is_correct": false, "explanation": "配价：“这些”是复数指示词，不能作“人生”的谓语，句子不通。"}], "explanations": {"如是": "正确。“人生亦如是”指人生也是这样。", "谁": "语义：“谁”指人，不能指代前面说的情况，句子说不通。", "哪个": "搭配：“亦”后面不接“哪个”，这里句子不通。", "这些": "配价：“这些”是复数指示词，不能作“人生”的谓语，句子不通。"}, "sentence_index": 0, "correct_answer": "如是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如是你肯让步，事情就好办了。", "explanation": "错误：“如是”是代词，意思是“这样、如此”，不能当连词引出假设；这里应该用〈如果〉。"}, {"text": "如是明天不下雨，我们就去郊游。", "explanation": "错误：“如是”不能表示假设条件；这里应该用〈如果〉。"}, {"text": "如是他们不来，我们就散了吧。", "explanation": "错误：“如是”是代词，不是假设连词；这里应该用〈如果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91166, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确答案：如是（rú shì），文言用法，意思是这样、如此。"}, {"text": "入世", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，“入世”意思是投身社会。"}, {"text": "如实", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。"}, {"text": "入时", "is_correct": false, "explanation": "rù 与 rú 声调不同，shí 与 shì 声调也不同，“入时”意思是时髦。"}], "explanations": {"如是": "正确答案：如是（rú shì），文言用法，意思是这样、如此。", "入世": "rù（第四声）与 rú（第二声）声调不同，“入世”意思是投身社会。", "如实": "shí（第二声）与 shì（第四声）声调不同，“如实”意思是按照实际情况。", "入时": "rù 与 rú 声调不同，shí 与 shì 声调也不同，“入时”意思是时髦。"}, "sentence_index": null, "correct_answer": "如是"}, "level_3": {"options": [{"text": "如是", "is_correct": true, "explanation": "正确。“岁月如是”指岁月也是这样流转。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”是问地点的词，不能指代“岁月”的情况，句子说不通。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，无法表示“像这样”的陈述，句子说不通。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：“岁月”后面接的是陈述，不接“怎样”这样的疑问代词。"}], "explanations": {"如是": "正确。“岁月如是”指岁月也是这样流转。", "哪儿": "语义：“哪儿”是问地点的词，不能指代“岁月”的情况，句子说不通。", "什么": "语义：“什么”是疑问代词，无法表示“像这样”的陈述，句子说不通。", "怎样": "搭配：“岁月”后面接的是陈述，不接“怎样”这样的疑问代词。"}, "sentence_index": 6, "correct_answer": "如是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如是你还想继续，就不要再拖延了。", "explanation": "错误：“如是”是代词，意思是“这样、如此”，不能当连词引出假设；这里应该用〈如果〉。"}, {"text": "如是他不肯让步，我们就只能放弃。", "explanation": "错误：“如是”不能表示假设条件；这里应该用〈如果〉。"}, {"text": "如是能按时完成，大家都会高兴。", "explanation": "错误：“如是”是代词，不是假设连词；这里应该用〈如果〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古今之理，大抵很如是。", "corrected_sentence": "古今之理，大抵如是。", "error_description": "程度副词误用：“如是”是代词，不能受“很”修饰，应去掉“很”。正确说法：古今之理，大抵如是。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "读书、做事，都很如是。", "corrected_sentence": "读书、做事，都如是。", "error_description": "程度副词误用：「如是」是代词，不能受「很」修饰，应去掉「很」，正确的说法是「读书、做事，都如是」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bc7133-771e-4bc6-9cb7-5a1a5d89e40a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
