INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91167, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "固然是说这件事对，但后面还有另一件事要说。", "primary_collocate": null, "pronunciation": "gù rán", "ipa": "ku˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "学外语固然重要，但是也要多练习。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服固然好看，可是太贵了。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐飞机固然快，但是我更喜欢坐火车。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的想法固然不错，不过做起来很难。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在城里固然方便，但是空气没有乡下好。", "target_word": "固然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多睡觉固然对身体好，睡得太多也不行。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "努力固然很重要，方法也一样重要。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法固然简单，但是不一定有用。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛输了固然难过，但大家都尽力了。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱固然能买很多东西，却买不到健康。", "target_word": "固然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "先肯定一点，再用但是、可是补充另一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5a0525c-6c30-4575-ae39-cf48177bb3a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”要引出原因，前句只是承认“学外语重要”，没有原因分句，后面的“但是”转折也无处接续。"}, {"text": "固然", "is_correct": true, "explanation": "正确：先承认“学外语重要”这一事实，再用“但是”补充另一面。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结论，前面没有原因，整句无法成立。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”“也”配合，不能与“但是”搭配。"}], "explanations": {"因为": "语义：“因为”要引出原因，前句只是承认“学外语重要”，没有原因分句，后面的“但是”转折也无处接续。", "固然": "正确：先承认“学外语重要”这一事实，再用“但是”补充另一面。", "所以": "语义：“所以”引出结论，前面没有原因，整句无法成立。", "不但": "搭配：“不但”要与“而且”“也”配合，不能与“但是”搭配。"}, "sentence_index": 0, "correct_answer": "固然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他固然很努力，所以考上了大学。", "explanation": "这里不能用〈固然〉。固然承认前半句的事实后，后面必须接转折；这句接的是因果结论，前后语气矛盾，应直接说“他很努力，所以考上了大学”。"}, {"text": "这个方案固然不错，然后我们就开始做吧。", "explanation": "这里不能用〈固然〉。固然后面要接表示转折的分句，这里接的是先后顺序，不是转折。"}, {"text": "他没复习，固然考了高分。", "explanation": "这里不能用〈固然〉。固然只承认前面的事实，不能用来表示出乎意料的结果；应说“他没复习，却考了高分。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”配合，句中没有“才”，且“也一样重要”的并列语气与排他语气冲突。"}, {"text": "固然", "is_correct": true, "explanation": "正确：先承认“努力很重要”这一事实，再用“也一样重要”补充。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”表示充分条件，把“努力很重要”说成条件，与“很重要”这一既定判断冲突。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”只表示先后次序，无法表达让步关系，与“努力很重要”这一判断不能组合。"}], "explanations": {"只有": "搭配：“只有”要与“才”配合，句中没有“才”，且“也一样重要”的并列语气与排他语气冲突。", "固然": "正确：先承认“努力很重要”这一事实，再用“也一样重要”补充。", "只要": "语义：“只要”表示充分条件，把“努力很重要”说成条件，与“很重要”这一既定判断冲突。", "然后": "语义：“然后”只表示先后次序，无法表达让步关系，与“努力很重要”这一判断不能组合。"}, "sentence_index": 6, "correct_answer": "固然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆便宜，固然菜不太好吃。", "explanation": "这里不能用〈固然〉。固然必须用在被承认的前一分句里，后一分句再用转折词；应说“这家饭馆固然便宜，但是菜不太好吃。”"}, {"text": "这个办法固然简单，所以我们就用它。", "explanation": "这里不能用〈固然〉。固然承认事实后必须接转折，这里接的是结论；应去掉固然，说“这个办法很简单，所以我们就用它。”"}, {"text": "这台电脑固然很便宜，于是我们就买了。", "explanation": "这里不能用〈固然〉。固然承认事实后必须接转折，这里接的是结果；应去掉固然，说“这台电脑很便宜，于是我们就买了。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作固然辛苦，因此收入不错。", "corrected_sentence": "这份工作固然辛苦，但是收入不错。", "error_description": "错误：“固然”承认前半句后，后面要接“但是／可是”等转折词；“因此”表示结论，不能与“固然”搭配。正确：“这份工作固然辛苦，但是收入不错。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划固然好，但是固然需要更多时间。", "corrected_sentence": "这个计划固然好，但是需要更多时间。", "error_description": "错误：“固然”只用于被承认的分句（“固然好”），转折分句里不能再用“固然”。正确：“这个计划固然好，但是需要更多时间。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f85f8d3-68bc-455e-a086-f2cd8e6105d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
