INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对付是想办法去处理一个难事或一个人。", "primary_collocate": null, "pronunciation": "duì fu", "ipa": "tweɪ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "这个孩子很调皮，老师不知道怎么对付他。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气很怪，我真不会对付他。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题太难了，我一个人对付不了。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明总是不听话，只有奶奶能对付他。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多工作，你一个人怎么对付得了？", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们公司最难对付的客户。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对付过很多麻烦事，所以一点也不怕。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗又大又凶，我不知道怎么对付它。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对付这样的老板，你要先学会冷静。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的考试很难，我们得好好想办法对付。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对付了", "label": "体标"}, {"form": "对付过", "label": "体标"}, {"form": "对付不了", "label": "复合"}, {"form": "难对付", "label": "复合"}], "register": "口语", "sense_fingerprint": "想办法处理难缠的人或棘手的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”用于庆贺好事，不能用于对调皮孩子的应对。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指想办法应付难缠的人，与“不知道怎么”搭配，符合孩子调皮的语境。"}, {"text": "聘请", "is_correct": false, "explanation": "搭配：“聘请”用于请人担任职务或专业工作，不能用于一个孩子。"}, {"text": "发表", "is_correct": false, "explanation": "配价：“发表”的宾语是文章、言论等，不能直接带人作宾语。"}], "explanations": {"祝贺": "语义：“祝贺”用于庆贺好事，不能用于对调皮孩子的应对。", "对付": "“对付”指想办法应付难缠的人，与“不知道怎么”搭配，符合孩子调皮的语境。", "聘请": "搭配：“聘请”用于请人担任职务或专业工作，不能用于一个孩子。", "发表": "配价：“发表”的宾语是文章、言论等，不能直接带人作宾语。"}, "sentence_index": 0, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友伤心时，我会对付他。", "explanation": "这里应该用〈安慰〉。“对付”带有对抗、应对的意味，用于伤心的朋友会显得很奇怪。"}, {"text": "周末我去医院对付生病的朋友。", "explanation": "这里应该用〈看望〉。“对付”表示想办法处理难事或难缠的人，去医院探望病人要用“看望”。"}, {"text": "大家都对付他的好心肠，常常夸他。", "explanation": "这里应该用〈赞美〉。“对付”带有应对、处理的意味，不能用来表示称赞别人的好心肠；称赞要用“赞美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地得到或体验，不能用于麻烦事。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指想办法应付麻烦事，与“过很多麻烦事”的经历搭配，符合“一点也不怕”的语境。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象通常是人或帮助，不能用于麻烦事。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏美好的事物，与“麻烦事”的意思不合。"}], "explanations": {"享受": "语义：“享受”指愉快地得到或体验，不能用于麻烦事。", "对付": "“对付”指想办法应付麻烦事，与“过很多麻烦事”的经历搭配，符合“一点也不怕”的语境。", "感谢": "搭配：“感谢”的对象通常是人或帮助，不能用于麻烦事。", "欣赏": "语义：“欣赏”指赞赏美好的事物，与“麻烦事”的意思不合。"}, "sentence_index": 6, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家热烈对付新同学。", "explanation": "这里应该用〈欢迎〉。“对付”含有对抗、应付的意味，不能表示热烈欢迎新同学。"}, {"text": "老师对付了我的进步。", "explanation": "这里应该用〈表扬〉。“对付”指想办法处理难题，不能用来表示肯定和称赞。"}, {"text": "我们应该对付老师的辛勤付出。", "explanation": "这里应该用〈尊敬〉。“对付”指想办法处理难题或难缠的人，不能用来表示对老师辛勤付出的敬重；表示敬重要用“尊敬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把对付过不少难缠的客户。", "corrected_sentence": "他对付过不少难缠的客户。", "error_description": "错误：“对付”前多加了“把”。“把”字句要求“把”后有宾语，这里“把”后直接接动词，句子不通。正确说法是“他对付过不少难缠的客户”，不用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件麻烦事，我把对付过去了。", "corrected_sentence": "这件麻烦事，我把它对付过去了。", "error_description": "错误：“把”字句缺少宾语。“把”后应有宾语“它”，这里“把”后直接接动词，句子不通。正确说法是“这件麻烦事，我把它对付过去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
