INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "采取措施处理；应付。", "primary_collocate": null, "pronunciation": "duì fu", "ipa": "tweɪ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "这种虫子很多，我们得想办法对付它们。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大雨，村民们用沙袋对付洪水。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新办法对付越来越多的投诉。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷了，我穿两件毛衣对付严寒。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种病要用特别的药来对付。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察准备了很多办法对付小偷。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对付电脑病毒，最好每天更新软件。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田边挖沟，用来对付野猪。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长安排两个人专门对付对方的前锋。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府出了新规定对付空气污染。", "target_word": "对付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对付了", "label": "体标"}, {"form": "对付过", "label": "体标"}, {"form": "对付不了", "label": "复合"}, {"form": "难对付", "label": "复合"}], "register": "口语", "sense_fingerprint": "采取措施去处理或应付问题、灾害、病害等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱、赞赏美好的事物，与“虫子很多，要想办法”的处理语境相反。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指采取措施应对、处理，与“想办法”搭配，符合虫害的语境。"}, {"text": "戒除", "is_correct": false, "explanation": "搭配：“戒除”只用于习惯、毒瘾等，不能用来指虫子。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化、点缀，不是应对有害的虫子。"}], "explanations": {"欣赏": "语义：“欣赏”指喜爱、赞赏美好的事物，与“虫子很多，要想办法”的处理语境相反。", "对付": "“对付”指采取措施应对、处理，与“想办法”搭配，符合虫害的语境。", "戒除": "搭配：“戒除”只用于习惯、毒瘾等，不能用来指虫子。", "装饰": "语义：“装饰”指美化、点缀，不是应对有害的虫子。"}, "sentence_index": 0, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师应该平等地对付每一个学生。", "explanation": "这里应该用〈对待〉。“对付”带有应对、对抗的意味，用于难缠的人或事；平等、尊重地看待学生要用“对待”。"}, {"text": "他悉心对付父母，从不抱怨。", "explanation": "这里应该用〈照顾〉。“对付”带有应对、对抗的意味，不能用来形容悉心照料父母；照料家人要用“照顾”。"}, {"text": "老师悠闲地对付窗外的花香。", "explanation": "这里应该用〈欣赏〉。“对付”表示想办法处理难事或应对问题，不能用于悠闲地看待花香；欣赏美景要用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：“保护”用于守护有价值的事物，不能用来指病毒。"}, {"text": "对付", "is_correct": true, "explanation": "“对付”指采取措施应对病毒，与“最好每天更新软件”的防护语境吻合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展品，不能用于电脑病毒。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示迎接、接待，与“更新软件”的防护意思不合。"}], "explanations": {"保护": "语义：“保护”用于守护有价值的事物，不能用来指病毒。", "对付": "“对付”指采取措施应对病毒，与“最好每天更新软件”的防护语境吻合。", "参观": "搭配：“参观”的对象是场所或展品，不能用于电脑病毒。", "欢迎": "语义：“欢迎”表示迎接、接待，与“更新软件”的防护意思不合。"}, "sentence_index": 6, "correct_answer": "对付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用最好的饭菜对付远道而来的客人。", "explanation": "这里应该用〈招待〉。“对付”含有对抗、应付的意味，不能用来表示热情地款待客人。"}, {"text": "机场里大家热烈对付远方来的朋友。", "explanation": "这里应该用〈迎接〉。“对付”不表示热烈欢迎，迎接远方来的朋友要用“迎接”。"}, {"text": "我们应该对付老师的耐心教导。", "explanation": "这里应该用〈感谢〉。“对付”表示想办法应对难题，不能用来表示对老师耐心教导的感激；表示感谢要用“感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得把想办法对付这些蚊子。", "corrected_sentence": "我们得想办法对付这些蚊子。", "error_description": "错误：多加了“把”。“把”后面应接受事名词，这里直接接动词短语“想办法对付这些蚊子”，句子不通。正确说法是“我们得想办法对付这些蚊子”，不用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民们想办法了对付这些害虫。", "corrected_sentence": "农民们想办法对付这些害虫。", "error_description": "错误：“了”放在了动词“对付”之前。“了”只能跟在动词之后或放在句末，这里语序不通。正确说法是“农民们想办法对付这些害虫”，去掉“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "和钱、做生意有关的事。", "primary_collocate": null, "pronunciation": "cái jīng", "ipa": "tsʰaɪ˧˥ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "爸爸喜欢看财经新闻，想学做生意。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手机上看了今天的财经消息。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对财经没有兴趣，只想过简单的生活。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该网站每天刊登大量财经文章。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想买股票的人要多看财经报道。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友在一家财经公司上班。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经节目教我们怎样管钱。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本财经书讲了怎么做小生意。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都收听财经广播。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经新闻说，今天股票涨了。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "财经新闻", "label": "复合"}], "register": "中性", "sense_fingerprint": "与金钱和生意有关的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经新闻」指与钱和做生意有关的新闻，与「爸爸喜欢看」的语境相符。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：「拖鞋」是一种鞋，不是新闻的内容，与「新闻」冲突。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：「牙齿」是人身上的器官，不能作为新闻的题材。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「看……新闻」要求有内容的题材，「石头新闻」不能成立。"}], "explanations": {"财经": "「财经新闻」指与钱和做生意有关的新闻，与「爸爸喜欢看」的语境相符。", "拖鞋": "语义：「拖鞋」是一种鞋，不是新闻的内容，与「新闻」冲突。", "牙齿": "语义：「牙齿」是人身上的器官，不能作为新闻的题材。", "石头": "搭配：「看……新闻」要求有内容的题材，「石头新闻」不能成立。"}, "sentence_index": 0, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子是财经做的。", "explanation": "这里应该用〈木头〉。财经指和钱、做生意有关的事，不能作桌子的材料。"}, {"text": "他的朋友是一名财经。", "explanation": "这里应该用〈医生〉。财经指和钱、做生意有关的事，不指人，不能用「一名」来称呼人。"}, {"text": "我每天都弹财经。", "explanation": "这里应该用〈钢琴〉。财经指和钱、做生意有关的事，不能用「弹」作谓语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经节目」指与钱和做生意有关的节目，「教我们怎样管钱」与之相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是自然地理事物，不能作为节目的内容。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：「夜空」指天空，不能教人管钱，与「节目」冲突。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「节目」的内容要能教人管钱，「眼睛节目」不成立。"}], "explanations": {"财经": "「财经节目」指与钱和做生意有关的节目，「教我们怎样管钱」与之相符。", "河流": "语义：「河流」是自然地理事物，不能作为节目的内容。", "夜空": "语义：「夜空」指天空，不能教人管钱，与「节目」冲突。", "眼睛": "搭配：「节目」的内容要能教人管钱，「眼睛节目」不成立。"}, "sentence_index": 6, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的财经比我高。", "explanation": "这里应该用〈身高〉。财经指和钱、做生意有关的事，不能用来比较人的身高。"}, {"text": "这件衣服的财经很好看。", "explanation": "这里应该用〈颜色〉。财经指和钱、做生意有关的事，不能用来形容衣服好看。"}, {"text": "这家店的财经很快就要开了。", "explanation": "这里应该用〈分店〉。财经指和钱、做生意有关的事，不是可以开张的店，不能说店的财经要开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天在手机上看财经很新闻。", "corrected_sentence": "她每天在手机上看财经新闻。", "error_description": "错误：「财经很新闻」，正确：「财经新闻」。「很」是程度副词，不能插在修饰语「财经」和中心词「新闻」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一本财经了书。", "corrected_sentence": "他写了一本财经书。", "error_description": "错误：「财经了书」，正确：「财经书」。「了」表示完成，不能插在修饰语「财经」和中心词「书」之间，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
