INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "财政和经济的合称；泛指金融、经济方面的事务。", "primary_collocate": null, "pronunciation": "cái jīng", "ipa": "tsʰaɪ˧˥ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "他在报社工作，专写财经新闻。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上看财经节目。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教大学的财经课。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经杂志上说今年经济会变好。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前是一名财经记者。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次财经会议有很多国家参加。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对国家的财经政策很有研究。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的财经版今天写了新税法。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "财经专家说明年的经济不会太差。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学学了财经。", "target_word": "财经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "财经新闻", "label": "复合"}], "register": "书面", "sense_fingerprint": "财政与经济领域的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经新闻」指财政与经济方面的新闻，符合报社的写作题材。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：「拖鞋」是一种鞋，不是新闻的题材，与「新闻」冲突。"}, {"text": "牙齿", "is_correct": false, "explanation": "语义：「牙齿」是人身上的器官，不能作为新闻的领域。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「专写……新闻」要求有报道价值的题材，「石头新闻」不成立。"}], "explanations": {"财经": "「财经新闻」指财政与经济方面的新闻，符合报社的写作题材。", "拖鞋": "语义：「拖鞋」是一种鞋，不是新闻的题材，与「新闻」冲突。", "牙齿": "语义：「牙齿」是人身上的器官，不能作为新闻的领域。", "石头": "搭配：「专写……新闻」要求有报道价值的题材，「石头新闻」不成立。"}, "sentence_index": 0, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的财经很长。", "explanation": "这里应该用〈长度〉。财经是领域名称，不能用来说桥的长短，要说长度。"}, {"text": "他的财经比我高。", "explanation": "这里应该用〈身高〉。财经是领域名称，不能用来比较人的身高。"}, {"text": "这杯茶的财经很好。", "explanation": "这里应该用〈味道〉。财经是领域名称，不能用来评价茶的好坏，要说味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "财经", "is_correct": true, "explanation": "「财经政策」指财政与经济方面的政策，与「国家的」相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：「河流」是自然地理事物，不是政策的领域。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：「夜空」指天空，不能作为政策的领域。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「政策」要涉及社会经济领域，「眼睛政策」不成立。"}], "explanations": {"财经": "「财经政策」指财政与经济方面的政策，与「国家的」相符。", "河流": "语义：「河流」是自然地理事物，不是政策的领域。", "夜空": "语义：「夜空」指天空，不能作为政策的领域。", "眼睛": "搭配：「政策」要涉及社会经济领域，「眼睛政策」不成立。"}, "sentence_index": 6, "correct_answer": "财经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张床的财经很软。", "explanation": "这里应该用〈床垫〉。财经是领域名称，不能用来说床的软硬，要说床垫很软。"}, {"text": "这家餐厅的财经很快。", "explanation": "这里应该用〈上菜〉。财经是领域名称，不能用来说餐厅的快慢，要说上菜很快。"}, {"text": "这支笔的财经很贵。", "explanation": "这里应该用〈价格〉。财经是领域名称，不能用来说东西的贵贱，要说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天下班后都读财经很杂志。", "corrected_sentence": "他每天下班后都读财经杂志。", "error_description": "错误：「财经很杂志」，正确：「财经杂志」。「很」是程度副词，不能插在修饰语「财经」和中心词「杂志」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥在大学学了很财经，毕业后进了银行。", "corrected_sentence": "我哥哥在大学学了财经，毕业后进了银行。", "error_description": "错误：「很财经」，正确：「财经」。「很」是程度副词，不能修饰名词「财经」，应去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
