INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人对待自己的方式，以及由此得到的礼遇。", "primary_collocate": null, "pronunciation": "dài yù", "ipa": "tai˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "客人在这家店里受到了很好的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是外国人，却得到了和我们一样的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管老人小孩，大家都应该有平等的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公司被同事排挤，受到不公平的待遇，很难过。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们希望老师给他们同样的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我的待遇和别人不一样。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友来了，当然要享受特别的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王第一次来，没想到有这样的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在学校受到了不好的待遇，回家哭了。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对病人，医院应该给同样的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种待遇", "label": "量词"}, {"form": "平等待遇", "label": "复合"}, {"form": "特殊待遇", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人对待自己的方式及所得的礼遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91175, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：本题目标词，读作 dài yù，指对待的方式。"}, {"text": "带鱼", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。"}, {"text": "地域", "is_correct": false, "explanation": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。"}, {"text": "待业", "is_correct": false, "explanation": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}], "explanations": {"待遇": "待遇：本题目标词，读作 dài yù，指对待的方式。", "带鱼": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。", "地域": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。", "待业": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}, "sentence_index": null, "correct_answer": "待遇"}, "level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：对人的对待方式，与“受到很好的”搭配，符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“受到”不与“礼物”搭配，应说“收到礼物”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被人“受到”，与“客人在这家店里”的语境矛盾。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“很好的”与“伤害”矛盾，句子说的是好的对待。"}], "explanations": {"待遇": "待遇：对人的对待方式，与“受到很好的”搭配，符合句意。", "礼物": "搭配：“受到”不与“礼物”搭配，应说“收到礼物”。", "天气": "语义：天气不能被人“受到”，与“客人在这家店里”的语境矛盾。", "伤害": "语义：“很好的”与“伤害”矛盾，句子说的是好的对待。"}, "sentence_index": 0, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这份待遇装进了书包。", "explanation": "这里应该用〈东西〉。待遇是抽象的对待方式或好处，不能像物品一样装进书包。"}, {"text": "这份待遇的颜色很红。", "explanation": "这里应该用〈外观〉。待遇是抽象的对待方式，不能用来说颜色。"}, {"text": "这份待遇跑得很快。", "explanation": "这里应该用〈汽车〉。待遇是抽象的对待方式，不能像车或人一样跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：对人的对待方式，与“享受特别的”搭配，符合句意。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“享受”不能用于噪音，与“特别的”也不搭。"}, {"text": "病痛", "is_correct": false, "explanation": "语义：没有人会享受病痛，与“老朋友来了”的语境矛盾。"}, {"text": "欠账", "is_correct": false, "explanation": "搭配：“享受”不与“欠账”搭配。"}], "explanations": {"待遇": "待遇：对人的对待方式，与“享受特别的”搭配，符合句意。", "噪音": "语义：“享受”不能用于噪音，与“特别的”也不搭。", "病痛": "语义：没有人会享受病痛，与“老朋友来了”的语境矛盾。", "欠账": "搭配：“享受”不与“欠账”搭配。"}, "sentence_index": 6, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的待遇很深。", "explanation": "这里应该用〈水〉。待遇是抽象的对待方式，不能用来说河水的深浅。"}, {"text": "这首歌的待遇很快。", "explanation": "这里应该用〈节奏〉。待遇是抽象的对待方式，不能用来形容歌曲的快慢。"}, {"text": "这台电脑的待遇很大。", "explanation": "这里应该用〈内存〉。待遇是抽象的对待方式，不能用来说电脑的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在饭店受到了很好地待遇，很满意。", "corrected_sentence": "他在饭店受到了很好的待遇，很满意。", "error_description": "错误：修饰“待遇”应用“的”，写成“地”是副词的标志。应说“很好的待遇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老朋友来了，当然要享受一本特别的待遇。", "corrected_sentence": "老朋友来了，当然要享受一种特别的待遇。", "error_description": "错误：“待遇”的量词用了“本”（书的量词），应用“种”。应说“一种特别的待遇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
