INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作中所得的工资、福利等报酬。", "primary_collocate": null, "pronunciation": "dài yù", "ipa": "tai˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的待遇很好，大家都愿意去。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，因为新公司待遇更高。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的工资待遇这几年提高了不少。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问一下，这份工作的待遇怎么样？", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给员工的待遇包括吃住和奖金。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然待遇不高，但他很喜欢这份工作。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的待遇比以前好多了。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看中的是这家公司的待遇。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作三年后，他的待遇提高了一倍。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的待遇才能留住好员工。", "target_word": "待遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种待遇", "label": "量词"}, {"form": "福利待遇", "label": "复合"}, {"form": "工资待遇", "label": "复合"}], "register": "中性", "sense_fingerprint": "工作中的工资、福利等报酬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：本题目标词，读作 dài yù，指工资、福利等报酬。"}, {"text": "带鱼", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。"}, {"text": "地域", "is_correct": false, "explanation": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。"}, {"text": "待业", "is_correct": false, "explanation": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}], "explanations": {"待遇": "待遇：本题目标词，读作 dài yù，指工资、福利等报酬。", "带鱼": "yù（第四声）与 yú（第二声）声调不同，意思是带鱼（一种鱼）。", "地域": "dài（第四声）与 dì（第四声）韵母不同（ai 与 i），意思是地域（区域）。", "待业": "yù 与 yè 韵母不同，意思是待业（等待就业）。"}, "sentence_index": null, "correct_answer": "待遇"}, "level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：工作的报酬，与“这家公司的……很好”搭配，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说的是人的性格，不说公司的脾气。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是人的体型，不能说公司的身材。"}, {"text": "表情", "is_correct": false, "explanation": "语义：公司没有表情，“表情很好”与句子的主语矛盾。"}], "explanations": {"待遇": "待遇：工作的报酬，与“这家公司的……很好”搭配，符合句意。", "脾气": "搭配：“脾气”说的是人的性格，不说公司的脾气。", "身材": "体貌：身材是人的体型，不能说公司的身材。", "表情": "语义：公司没有表情，“表情很好”与句子的主语矛盾。"}, "sentence_index": 0, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的待遇很高。", "explanation": "这里应该用〈价格〉。待遇指对待方式或工资福利，衣服的价钱要说“价格”。"}, {"text": "这座山的待遇很高。", "explanation": "这里应该用〈海拔〉。待遇不能用来说山的高低，山的高度要说“海拔”。"}, {"text": "这个房间的待遇很新鲜。", "explanation": "这里应该用〈空气〉。待遇不能用来形容房间是否新鲜，房间的清新要说“空气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "待遇", "is_correct": true, "explanation": "待遇：工作的报酬，与“医生的……比以前好多了”搭配，符合句意。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：医生没有属于自己的“地铁”，“医生的地铁比以前好多了”说不通。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票不能用“比以前好多了”来形容医生。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“比以前好多了”不能用来形容年龄。"}], "explanations": {"待遇": "待遇：工作的报酬，与“医生的……比以前好多了”搭配，符合句意。", "地铁": "语义：医生没有属于自己的“地铁”，“医生的地铁比以前好多了”说不通。", "车票": "语义：车票不能用“比以前好多了”来形容医生。", "年龄": "语义：“比以前好多了”不能用来形容年龄。"}, "sentence_index": 6, "correct_answer": "待遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的待遇很硬。", "explanation": "这里应该用〈质地〉。待遇指工作所得的工资、福利，不能用来形容石头的软硬。"}, {"text": "这台电脑的待遇很大。", "explanation": "这里应该用〈内存〉。待遇不能用来形容电脑的容量，容量要说“内存”。"}, {"text": "这把椅子的待遇很红。", "explanation": "这里应该用〈颜色〉。待遇指工作所得的工资、福利，不能用来说椅子的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司待遇得很好，我想去。", "corrected_sentence": "这家公司待遇很好，我想去。", "error_description": "错误：名词“待遇”后面不能用“得”引出程度补语。应说“待遇很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作三年后，公司提高了他待遇。", "corrected_sentence": "工作三年后，公司提高了他的待遇。", "error_description": "错误：定语“他”与中心词“待遇”之间漏掉了“的”。正确：他的待遇。定语后要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富有", "is_correct": true, "explanation": "与“贫穷”相反，指家里有很多钱和财物。"}, {"text": "清楚", "is_correct": false, "explanation": "表示明白、不模糊，与“贫穷”没有反义关系。"}, {"text": "紧张", "is_correct": false, "explanation": "表示心情不安或时间不充裕，与“贫穷”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "表示温度适中、让人感到舒服，与“贫穷”没有反义关系。"}], "correct_answer": "富有", "explanations": {"富有": "与“贫穷”相反，指家里有很多钱和财物。", "清楚": "表示明白、不模糊，与“贫穷”没有反义关系。", "紧张": "表示心情不安或时间不充裕，与“贫穷”没有反义关系。", "温暖": "表示温度适中、让人感到舒服，与“贫穷”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富有", "is_correct": true, "explanation": "与“贫穷”相反，指家里有很多钱和财物。"}, {"text": "严肃", "is_correct": false, "explanation": "表示态度认真、不随便，与“贫穷”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "表示不怕困难和危险，与“贫穷”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "表示速度很快，与“贫穷”没有反义关系。"}], "correct_answer": "富有", "explanations": {"富有": "与“贫穷”相反，指家里有很多钱和财物。", "严肃": "表示态度认真、不随便，与“贫穷”没有反义关系。", "勇敢": "表示不怕困难和危险，与“贫穷”没有反义关系。", "迅速": "表示速度很快，与“贫穷”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "家里没有钱，东西很少。", "primary_collocate": null, "pronunciation": "pín qióng", "ipa": "pʰin˧˥ tɕʰjʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他家很贫穷，冬天没有厚衣服。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小时候家里很贫穷。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个贫穷的家，只有一张桌子。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个贫穷的农村家庭。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然贫穷，他们一家人过得很开心。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫穷的孩子也想上学。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小贫穷，连一双新鞋也没有。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时我家太贫穷了，常常吃不饱。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，她年轻时过着贫穷的生活。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家不富有，但也不贫穷。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "貧窮", "label": "繁体"}, {"form": "贫穷落后", "label": "复合"}], "register": "中性", "sense_fingerprint": "家庭没有钱，生活用品很少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫穷", "is_correct": true, "explanation": "家里缺钱、东西少，符合句中“冬天没有厚衣服”的情况。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”指身体状况好，不能说明家里缺钱、缺少厚衣服的情况，句意不通。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说明年龄，不能说明家里缺钱、东西很少的状况，句意不通。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不能用来形容家。"}], "explanations": {"贫穷": "家里缺钱、东西少，符合句中“冬天没有厚衣服”的情况。", "健康": "语义：“健康”指身体状况好，不能说明家里缺钱、缺少厚衣服的情况，句意不通。", "年轻": "语义：“年轻”说明年龄，不能说明家里缺钱、东西很少的状况，句意不通。", "聪明": "语义：“聪明”形容人的头脑，不能用来形容家。"}, "sentence_index": 0, "correct_answer": "贫穷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府规定了一条贫穷线，低于它的家庭可以申请补助。", "explanation": "这里应该用〈贫困〉。固定说法是“贫困线”，不说“贫穷线”。"}, {"text": "他穿着一身贫穷的衣服去参加婚礼。", "explanation": "这里应该用〈寒酸〉。贫穷指经济状况，形容衣着或样子要用“寒酸”。"}, {"text": "这首诗的内容很贫穷，没有新意。", "explanation": "这里应该用〈贫乏〉。贫穷指家里缺钱，内容、知识不足要用“贫乏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫穷", "is_correct": true, "explanation": "家里缺钱，符合句中“连一双新鞋也没有”的情况。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“幸福”与“连一双新鞋也没有”矛盾。"}, {"text": "繁荣", "is_correct": false, "explanation": "搭配：“繁荣”用于地区或国家的经济，不用来形容人。"}, {"text": "舒适", "is_correct": false, "explanation": "语义：“舒适”与“连一双新鞋也没有”矛盾。"}], "explanations": {"贫穷": "家里缺钱，符合句中“连一双新鞋也没有”的情况。", "幸福": "语义：“幸福”与“连一双新鞋也没有”矛盾。", "繁荣": "搭配：“繁荣”用于地区或国家的经济，不用来形容人。", "舒适": "语义：“舒适”与“连一双新鞋也没有”矛盾。"}, "sentence_index": 6, "correct_answer": "贫穷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块土地很贫穷，种不出庄稼。", "explanation": "这里应该用〈贫瘠〉。土地缺乏养分要用“贫瘠”，贫穷只用于人或家庭的经济状况。"}, {"text": "村里的物资很贫穷，大家都很着急。", "explanation": "这里应该用〈匮乏〉。物资缺少要用“匮乏”，不说“物资贫穷”。"}, {"text": "他的英语基础很贫穷。", "explanation": "这里应该用〈薄弱〉。贫穷指经济状况，基础、能力不好要用“薄弱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家很贫穷地，大家都很努力。", "corrected_sentence": "我们家很贫穷，大家都很努力。", "error_description": "形容词“贫穷”作谓语时后面不能加“地”，“地”用于修饰动词，应说“很贫穷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的人们因为干旱变很贫穷。", "corrected_sentence": "这里的人们因为干旱变得很贫穷。", "error_description": "“变”后面表示变化的程度时要加“得”，应说“变得很贫穷”，不能省略“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富裕", "is_correct": true, "explanation": "与“贫穷”相反，指经济充足、生活富足。"}, {"text": "明亮", "is_correct": false, "explanation": "表示光线充足、明显，与“贫穷”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "表示温度很低，与“贫穷”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "表示没有声音或很平和，与“贫穷”没有反义关系。"}], "correct_answer": "富裕", "explanations": {"富裕": "与“贫穷”相反，指经济充足、生活富足。", "明亮": "表示光线充足、明显，与“贫穷”没有反义关系。", "寒冷": "表示温度很低，与“贫穷”没有反义关系。", "安静": "表示没有声音或很平和，与“贫穷”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富裕", "is_correct": true, "explanation": "与“贫穷”相反，指经济充足、生活富足。"}, {"text": "温柔", "is_correct": false, "explanation": "表示性格和气、待人细心，与“贫穷”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "表示态度主动、友好，与“贫穷”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "表示速度很快，与“贫穷”没有反义关系。"}], "correct_answer": "富裕", "explanations": {"富裕": "与“贫穷”相反，指经济充足、生活富足。", "温柔": "表示性格和气、待人细心，与“贫穷”没有反义关系。", "热情": "表示态度主动、友好，与“贫穷”没有反义关系。", "迅速": "表示速度很快，与“贫穷”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "缺乏生活所需的财物，经济困难。", "primary_collocate": null, "pronunciation": "pín qióng", "ipa": "pʰin˧˥ tɕʰjʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个地区很贫穷，路也不好。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想帮助贫穷的国家。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子很贫穷，很多人看不起病。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家以前很贫穷，现在好多了。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个国家变得越来越贫穷。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人们贫穷了很多年。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太少，这里的人们很贫穷。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府帮助贫穷的农民盖了新房子。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫穷的地方，孩子们上学很难。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为干旱，这个村子变得很贫穷。", "target_word": "贫穷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "貧窮", "label": "繁体"}, {"form": "贫穷落后", "label": "复合"}], "register": "中性", "sense_fingerprint": "地区、国家或群体缺少生活所需的财物，经济困难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫穷", "is_correct": true, "explanation": "地区经济困难，符合句中“路也不好”的情况。"}, {"text": "亲切", "is_correct": false, "explanation": "搭配：“亲切”形容人的态度，不说地区亲切。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不能用来形容地区。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：地区不会“高兴”，句意不通。"}], "explanations": {"贫穷": "地区经济困难，符合句中“路也不好”的情况。", "亲切": "搭配：“亲切”形容人的态度，不说地区亲切。", "聪明": "语义：“聪明”形容人的头脑，不能用来形容地区。", "高兴": "语义：地区不会“高兴”，句意不通。"}, "sentence_index": 0, "correct_answer": "贫穷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山很贫穷，没有人住。", "explanation": "这里应该用〈荒凉〉。贫穷形容人或地区的经济状况，不形容自然景观。"}, {"text": "去年市场贫穷，工厂纷纷关门。", "explanation": "这里应该用〈萧条〉。贫穷指人或家庭缺钱，形容市场不景气要用“萧条”，不说“市场贫穷”。"}, {"text": "这个地区的教育很贫穷，孩子们上学很难。", "explanation": "这里应该用〈落后〉。贫穷指缺少钱财，教育、设施不足要用“落后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫穷", "is_correct": true, "explanation": "人们缺少收入，符合句中“工作太少”的情况。"}, {"text": "繁忙", "is_correct": false, "explanation": "语义：“繁忙”与“工作太少”矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面或气氛，与句中“工作太少”的语境不搭。"}, {"text": "繁荣", "is_correct": false, "explanation": "搭配：“繁荣”形容地区的经济，不用来形容人。"}], "explanations": {"贫穷": "人们缺少收入，符合句中“工作太少”的情况。", "繁忙": "语义：“繁忙”与“工作太少”矛盾。", "热闹": "语义：“热闹”形容场面或气氛，与句中“工作太少”的语境不搭。", "繁荣": "搭配：“繁荣”形容地区的经济，不用来形容人。"}, "sentence_index": 6, "correct_answer": "贫穷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为亏损，这家公司贫穷了。", "explanation": "这里应该用〈破产〉。“贫穷”只说人或家庭缺钱，公司经营失败要用“破产”。"}, {"text": "他的经验很贫穷，做事总是出错。", "explanation": "这里应该用〈欠缺〉。“贫穷”形容经济状况，经验、能力不足要用“欠缺”。"}, {"text": "这里的水源很贫穷。", "explanation": "这里应该用〈短缺〉。水源不足要用“短缺”，不说水源贫穷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区越来越很贫穷。", "corrected_sentence": "这个地区越来越贫穷。", "error_description": "“越来越”后面不能再加“很”，应说“越来越贫穷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区很贫穷得厉害。", "corrected_sentence": "这个地区贫穷得厉害。", "error_description": "“很”与表示程度的补语“得厉害”不能同时用，删去“很”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
