INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国际机场是能让飞机飞到别的国家去的大机场。", "primary_collocate": null, "pronunciation": "guó jì jī chǎng", "ipa": "kwɔ˧˥ tɕi˥˩ tɕi˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "北京有一个很大的国际机场。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐出租车去国际机场。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国际机场每天有很多飞机。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际机场里有很多外国人。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在国际机场等朋友。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从国际机场飞到国外要十个小时。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际机场离我家很远。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的城市要建一座新的国际机场。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机明天早上从国际机场起飞。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际机场里有商店和饭馆。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "能飞往外国的大型机场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际机场", "is_correct": true, "explanation": "“国际机场”是能飞往外国的大型机场，可以被“很大的”修饰。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：北京不靠海，“很大的海洋”与北京的地理位置矛盾。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“语言”一般用“一种”“一门”计量，不说“很大的语言”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只说高低，不能用“很大的”修饰。"}], "explanations": {"国际机场": "“国际机场”是能飞往外国的大型机场，可以被“很大的”修饰。", "海洋": "语义：北京不靠海，“很大的海洋”与北京的地理位置矛盾。", "语言": "搭配：“语言”一般用“一种”“一门”计量，不说“很大的语言”。", "体温": "搭配：“体温”只说高低，不能用“很大的”修饰。"}, "sentence_index": 0, "correct_answer": "国际机场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国际机场下午三点坐飞机，去纽约。", "explanation": "这里应该用〈旅客〉。坐飞机的是人，机场不能作为“坐”的主语。"}, {"text": "北京新建了一只国际机场，明年开放。", "explanation": "这里应该用〈座〉。量词“只”用于动物或成对的东西，大型机场要用“座”。"}, {"text": "我们的城市要建一条国际机场。", "explanation": "这里应该用〈座〉。量词“条”用于细长的东西，大型机场要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际机场", "is_correct": true, "explanation": "“国际机场”是地点，可以作“离”的主语，与“离我家很远”相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是地点，不能说离我家很远。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“离”要求一个地点作主语，“名字”不能作为地点。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是时间，不能说离我家很远。"}], "explanations": {"国际机场": "“国际机场”是地点，可以作“离”的主语，与“离我家很远”相符。", "心情": "语义：“心情”不是地点，不能说离我家很远。", "名字": "配价：“离”要求一个地点作主语，“名字”不能作为地点。", "春天": "语义：“春天”是时间，不能说离我家很远。"}, "sentence_index": 6, "correct_answer": "国际机场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校旁边新建了一颗国际机场。", "explanation": "这里应该用〈座〉。量词“颗”用于粒状的小东西，大型机场要用“座”。"}, {"text": "这根国际机场很大，大家都想去看。", "explanation": "这里应该用〈座〉。量词“根”用于细长的东西，大型机场要用“座”。"}, {"text": "北京有一枚国际机场，非常有名。", "explanation": "这里应该用〈座〉。量词“枚”用于硬币、奖章等小而扁的东西，大型机场要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只国际机场每年运送很多旅客。", "corrected_sentence": "这座国际机场每年运送很多旅客。", "error_description": "“机场”的量词应该用“座”，不能用“只”。“只”一般用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友国际机场来。", "corrected_sentence": "我朋友从国际机场来。", "error_description": "漏掉了介词“从”。“国际机场”是动作的起点，要用“从”引出，应说“从国际机场来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
