INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有国际航班起降、可供出入境的机场。", "primary_collocate": null, "pronunciation": "guó jì jī chǎng", "ipa": "kwɔ˧˥ tɕi˥˩ tɕi˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "出国要先到国际机场办手续。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际机场的海关查得很严。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国际机场办好了出境手续。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际机场有国际航班，也有出入境检查。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下飞机后，我们走出国际机场。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国客人从国际机场入境。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座国际机场有去东京的航班。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际机场的海关在二楼。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的护照在国际机场丢了。", "target_word": "国际机场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去国际机场前，别忘了带护照。", "target_word": "国际机场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "设有海关、可出入境的机场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际机场", "is_correct": true, "explanation": "“国际机场”设有海关，出国要在这里办手续，与语境相符。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园与办出国手续无关。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场不办出国手续。"}, {"text": "飞机", "is_correct": false, "explanation": "搭配：“到飞机办手续”说不通，办手续要到地点或机构，飞机上不办手续。"}], "explanations": {"国际机场": "“国际机场”设有海关，出国要在这里办手续，与语境相符。", "动物园": "语义：动物园与办出国手续无关。", "菜市场": "语义：菜市场不办出国手续。", "飞机": "搭配：“到飞机办手续”说不通，办手续要到地点或机构，飞机上不办手续。"}, "sentence_index": 0, "correct_answer": "国际机场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们市新建了一只国际机场，能直飞东京。", "explanation": "这里应该用〈座〉。量词“只”用于动物或成对的东西，大型机场要用“座”。"}, {"text": "这条国际机场有海关和出入境检查。", "explanation": "这里应该用〈座〉。量词“条”用于细长的东西，大型机场要用“座”。"}, {"text": "市中心有一颗国际机场，很多人都去参观。", "explanation": "这里应该用〈座〉。量词“颗”用于粒状的小东西，大型机场要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际机场", "is_correct": true, "explanation": "“国际机场”有国际航班，与“去东京的航班”相符。"}, {"text": "大学", "is_correct": false, "explanation": "搭配：“有……航班”一般用于交通站点，学校不说有航班。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场不是交通设施，不会有去东京的航班。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆不是交通设施，与“航班”无关。"}], "explanations": {"国际机场": "“国际机场”有国际航班，与“去东京的航班”相符。", "大学": "搭配：“有……航班”一般用于交通站点，学校不说有航班。", "农场": "语义：农场不是交通设施，不会有去东京的航班。", "博物馆": "语义：博物馆不是交通设施，与“航班”无关。"}, "sentence_index": 6, "correct_answer": "国际机场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根国际机场离市区很近，交通很方便。", "explanation": "这里应该用〈座〉。量词“根”用于细长的东西，大型机场要用“座”。"}, {"text": "我们学校附近有一枚国际机场。", "explanation": "这里应该用〈座〉。量词“枚”用于硬币、奖章等小而扁的东西，大型机场要用“座”。"}, {"text": "市里新修了一把国际机场，很多人都去参观。", "explanation": "这里应该用〈座〉。量词“把”用于有柄的东西，大型机场要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只国际机场设有海关和出入境检查。", "corrected_sentence": "这座国际机场设有海关和出入境检查。", "error_description": "“机场”的量词应该用“座”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们国际机场出境。", "corrected_sentence": "他们从国际机场出境。", "error_description": "漏掉了介词。“国际机场”是出境的地点，动词前要用介词引出，可用“从”或“在”，如“从国际机场出境”或“在国际机场出境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
