INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91183, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "从这里到那里，中间隔着多远。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "我家距学校只有两公里。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里距火车站不太远。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市距我家很近，走路五分钟。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市距海边有一百公里。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院距这儿大概三公里。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校距地铁站很近。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园距公司有多远？", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个村子距城里有二十公里。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场距市中心不太远。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行距这里只有两百米。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "距离", "label": "复合"}], "register": "书面", "sense_fingerprint": "介词，表示两地之间相隔的空间距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "距", "is_correct": true, "explanation": "距读作 jù（第四声），表示两地之间相隔的距离。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù 声调不同，意思是居住。"}, {"text": "局", "is_correct": false, "explanation": "jú（第二声）与 jù 声调不同，意思是局面、局部。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}], "explanations": {"距": "距读作 jù（第四声），表示两地之间相隔的距离。", "举": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "居": "jū（第一声）与 jù 声调不同，意思是居住。", "局": "jú（第二声）与 jù 声调不同，意思是局面、局部。", "去": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。", "记": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}, "sentence_index": null, "correct_answer": "距"}, "level_3": {"options": [{"text": "距", "is_correct": true, "explanation": "「距」表示两地之间相隔的距离，与后面的「只有两公里」搭配，句意通顺。"}, {"text": "从", "is_correct": false, "explanation": "语义：「从」引出动作的起点，句中没有动作，且「只有两公里」说的是距离，不是起点。"}, {"text": "向", "is_correct": false, "explanation": "配价：「向」后要接动作或方向性的成分，「我家向学校」之后接「只有两公里」，结构不成立。"}, {"text": "在", "is_correct": false, "explanation": "搭配：「在」引出处所，不能与「只有两公里」构成两地相隔距离的说法。"}], "explanations": {"距": "「距」表示两地之间相隔的距离，与后面的「只有两公里」搭配，句意通顺。", "从": "语义：「从」引出动作的起点，句中没有动作，且「只有两公里」说的是距离，不是起点。", "向": "配价：「向」后要接动作或方向性的成分，「我家向学校」之后接「只有两公里」，结构不成立。", "在": "搭配：「在」引出处所，不能与「只有两公里」构成两地相隔距离的说法。"}, "sentence_index": 0, "correct_answer": "距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两座城市的距很远。", "explanation": "这里应该用〈距离〉。「距」作名词只指公鸡腿后的爪，不表示两地之间的间隔；表示间隔要用「距离」。"}, {"text": "我家距星期五只有两公里。", "explanation": "这里误用了「距」的时间义（以某个时间点为基准），却配上了空间单位「两公里」。空间义的终点必须是地点，如「距学校两公里」。"}, {"text": "他距我借了一本书。", "explanation": "这里应该用〈向〉。「距」只表示两地相隔，不能引出动作的对象，借东西的对象要用「向」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91183, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "距", "is_correct": true, "explanation": "距读作 jù（第四声），表示两地之间相隔的距离。"}, {"text": "菊", "is_correct": false, "explanation": "jú（第二声）与 jù 声调不同，意思是菊花。"}, {"text": "趣", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是趣味。"}, {"text": "季", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是季节。"}, {"text": "拘", "is_correct": false, "explanation": "jū（第一声）与 jù 声调不同，意思是拘留、拘束。"}], "explanations": {"距": "距读作 jù（第四声），表示两地之间相隔的距离。", "菊": "jú（第二声）与 jù 声调不同，意思是菊花。", "趣": "qù 与 jù 声母不同（q 与 j），声调相同，意思是趣味。", "季": "jì 与 jù 韵母不同（i 与 ü），意思是季节。", "拘": "jū（第一声）与 jù 声调不同，意思是拘留、拘束。"}, "sentence_index": null, "correct_answer": "距"}, "level_3": {"options": [{"text": "距", "is_correct": true, "explanation": "「距」用来问两地之间相隔多远，与「有多远」搭配，句意通顺。"}, {"text": "对", "is_correct": false, "explanation": "搭配：「对」引出对象，与「有多远」不能构成两地相隔距离的问句。"}, {"text": "朝", "is_correct": false, "explanation": "配价：「朝」后要接动作的方向，这里没有动作，结构不成立。"}, {"text": "按", "is_correct": false, "explanation": "语义：「按」表示依据，与两地之间的距离无关，句意不通。"}], "explanations": {"距": "「距」用来问两地之间相隔多远，与「有多远」搭配，句意通顺。", "对": "搭配：「对」引出对象，与「有多远」不能构成两地相隔距离的问句。", "朝": "配价：「朝」后要接动作的方向，这里没有动作，结构不成立。", "按": "语义：「按」表示依据，与两地之间的距离无关，句意不通。"}, "sentence_index": 6, "correct_answer": "距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他距我大五岁。", "explanation": "这里应该用〈比〉。「距」只表示空间或时间上的间隔，不能用来比较年龄，比较年龄要说「比」。"}, {"text": "这次考试距我家两公里。", "explanation": "这里误用了「距」：它表示空间间隔时，主语应是地点或场所，如「考场距我家两公里」；「考试」是事件，不能作空间距离的主语。"}, {"text": "我每天距家走到学校。", "explanation": "这里应该用〈从〉。「距」只表示相隔多远，不能表示动作的起点，起点要用「从」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站的距我家不远，走路十分钟。", "corrected_sentence": "车站距我家不远，走路十分钟。", "error_description": "「距」是介词，前面不能加「的」，正确写作「车站距我家不远」；错误句在「距」前多加了「的」，把介词误当作名词的修饰成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店距了地铁站不远，走路就能到。", "corrected_sentence": "这家商店距地铁站不远，走路就能到。", "error_description": "「距」是介词，后面不能加「了」，正确写作「距地铁站」；错误句在「距」后加了「了」，把介词误当作动词使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
