INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91184, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "在空间或时间上相隔；离。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "距考试只有三天了。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距春节还有两个星期。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥距今已有八百年的历史。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在距下课还有十分钟。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距比赛开始还有一个小时。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距我毕业还有半年。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距上次见面已经三年了。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距出发的时间不多了。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距火车开还有二十分钟。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距这座桥不远的地方有一家商店。", "target_word": "距", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "距离", "label": "复合"}], "register": "书面", "sense_fingerprint": "介词，表示与某个时间点或地点相隔多久、多远", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91184, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "距", "is_correct": true, "explanation": "距读作 jù（第四声），表示在时间或空间上相隔。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù 声调不同，意思是居住。"}, {"text": "局", "is_correct": false, "explanation": "jú（第二声）与 jù 声调不同，意思是局面、局部。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。"}, {"text": "记", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}], "explanations": {"距": "距读作 jù（第四声），表示在时间或空间上相隔。", "举": "jǔ（第三声）与 jù（第四声）声调不同，意思是举起。", "居": "jū（第一声）与 jù 声调不同，意思是居住。", "局": "jú（第二声）与 jù 声调不同，意思是局面、局部。", "去": "qù 与 jù 声母不同（q 与 j），声调相同，意思是去。", "记": "jì 与 jù 韵母不同（i 与 ü），意思是记住。"}, "sentence_index": null, "correct_answer": "距"}, "level_3": {"options": [{"text": "距", "is_correct": true, "explanation": "「距」表示距离某个时间点还有多久，与「考试」「只有三天了」搭配，句意通顺。"}, {"text": "从", "is_correct": false, "explanation": "语义：「从」引出动作的起点，「考试」是事件，不能作起点，且句中没有动作。"}, {"text": "向", "is_correct": false, "explanation": "配价：「向」后要接动作或方向性的成分，「向考试」之后不能接「只有三天了」。"}, {"text": "在", "is_correct": false, "explanation": "搭配：「在」引出处所，不能与表示时间间隔的「只有三天了」搭配，句意不通。"}], "explanations": {"距": "「距」表示距离某个时间点还有多久，与「考试」「只有三天了」搭配，句意通顺。", "从": "语义：「从」引出动作的起点，「考试」是事件，不能作起点，且句中没有动作。", "向": "配价：「向」后要接动作或方向性的成分，「向考试」之后不能接「只有三天了」。", "在": "搭配：「在」引出处所，不能与表示时间间隔的「只有三天了」搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个教室的距只有三百米。", "explanation": "这里应该用〈距离〉。「距」作名词只指公鸡腿后的爪，表示两处之间的间隔要用「距离」。"}, {"text": "距考试还有三公里。", "explanation": "这里误用了「距」的时间义（离某个时间点还有多久），却配上了空间单位「公里」。时间义只能与时长搭配，如「距考试还有三天」。"}, {"text": "我距老师问了一个问题。", "explanation": "这里应该用〈向〉。「距」只表示时间或空间上的相隔，不能引出动作的对象，问问题的对象要用「向」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91184, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "距", "is_correct": true, "explanation": "距读作 jù（第四声），表示在时间或空间上相隔。"}, {"text": "菊", "is_correct": false, "explanation": "jú（第二声）与 jù 声调不同，意思是菊花。"}, {"text": "趣", "is_correct": false, "explanation": "qù 与 jù 声母不同（q 与 j），声调相同，意思是趣味。"}, {"text": "季", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），意思是季节。"}, {"text": "拘", "is_correct": false, "explanation": "jū（第一声）与 jù 声调不同，意思是拘留、拘束。"}], "explanations": {"距": "距读作 jù（第四声），表示在时间或空间上相隔。", "菊": "jú（第二声）与 jù 声调不同，意思是菊花。", "趣": "qù 与 jù 声母不同（q 与 j），声调相同，意思是趣味。", "季": "jì 与 jù 韵母不同（i 与 ü），意思是季节。", "拘": "jū（第一声）与 jù 声调不同，意思是拘留、拘束。"}, "sentence_index": null, "correct_answer": "距"}, "level_3": {"options": [{"text": "距", "is_correct": true, "explanation": "「距」表示距离上次见面已经过去多久，与「已经三年了」搭配，句意通顺。"}, {"text": "对", "is_correct": false, "explanation": "搭配：「对」引出对象，「对上次见面」不能表示时间间隔，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "配价：「朝」后要接动作的方向，「朝上次见面」之后不能接「已经三年了」。"}, {"text": "按", "is_correct": false, "explanation": "语义：「按」表示依据，与「上次见面」到现在的时间间隔无关，句意不通。"}], "explanations": {"距": "「距」表示距离上次见面已经过去多久，与「已经三年了」搭配，句意通顺。", "对": "搭配：「对」引出对象，「对上次见面」不能表示时间间隔，句意不通。", "朝": "配价：「朝」后要接动作的方向，「朝上次见面」之后不能接「已经三年了」。", "按": "语义：「按」表示依据，与「上次见面」到现在的时间间隔无关，句意不通。"}, "sentence_index": 6, "correct_answer": "距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我距他大两岁。", "explanation": "这里应该用〈比〉。「距」只表示空间或时间上的间隔，不能用来比较年龄，比较年龄要说「比」。"}, {"text": "放学距这座桥很远。", "explanation": "这里误用了「距」的空间义：「放学」是事件，不能作空间间隔的主语，此处应改用「离」等词表达。"}, {"text": "他距这座桥走了两公里。", "explanation": "这里应该用〈从〉。「距」只表示间隔，不能与「走」搭配来表示从某处出发走了多远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "距的开学还有三个星期。", "corrected_sentence": "距开学还有三个星期。", "error_description": "「距」是介词，后面直接接宾语，不能加「的」，正确写作「距开学还有三个星期」；错误句在「距」后多加了「的」，把介词误当作修饰成分使用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "距了比赛结束只剩五分钟。", "corrected_sentence": "距比赛结束只剩五分钟。", "error_description": "「距」是介词，后面不能直接加「了」，正确写作「距比赛结束」；错误句在「距」后加了「了」，误把介词当作动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
