INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "多半是说大概会这样，可能性很大。", "primary_collocate": null, "pronunciation": "duō bàn", "ipa": "twɔ˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "天这么黑，他多半不会来了。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没回信息，多半是睡着了。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看这天色，今天多半要下雨。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的灯关了，多半已经睡了。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，商店多半关门了。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没来，多半是生病了。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵得厉害，他多半会迟到。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听声音，外面多半有人在吵架。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得那么开心，多半考得不错。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一直关机，他多半在飞机上。", "target_word": "多半", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示根据情况推测，大概如此，可能性很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多半", "is_correct": true, "explanation": "正确：“多半”表示根据天色推测“他大概不会来了”，符合句意。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常发生，句中是对这一次情况的推测，二者不相符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去有过的经历，句中说的是现在对来与不来的判断。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示动作刚刚发生，与“不会来”这一推断不相容。"}], "explanations": {"多半": "正确：“多半”表示根据天色推测“他大概不会来了”，符合句意。", "常常": "语义：“常常”表示经常发生，句中是对这一次情况的推测，二者不相符。", "曾经": "体貌：“曾经”指过去有过的经历，句中说的是现在对来与不来的判断。", "刚": "语义：“刚”表示动作刚刚发生，与“不会来”这一推断不相容。"}, "sentence_index": 0, "correct_answer": "多半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "难道他多半不知道这件事吗？", "explanation": "“难道”引出的反问语气已经很确定，加上表示推测的“多半”自相矛盾。这里应直接说“难道他不知道这件事吗”。"}, {"text": "我刚才亲眼看见他走进教室，他多半已经进去了。", "explanation": "亲眼看见的事实已经确定，不能再用表示推测的“多半”，应直接说“他已经进去了”。"}, {"text": "你多半必须今天交作业。", "explanation": "这里是在向对方提出要求，不是推测，“多半”表示推测，不能这样用。应直接说“你必须今天交作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多半", "is_correct": true, "explanation": "正确：“多半”表示推测“他大概会迟到”，与路上堵车的语境相符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作或状态已经完成，而“会迟到”指尚未发生的推测。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能直接修饰“会迟到”这样的助动词短语。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人亲身去做，“迟到”不是可以亲自去做的动作。"}], "explanations": {"多半": "正确：“多半”表示推测“他大概会迟到”，与路上堵车的语境相符。", "已经": "体貌：“已经”表示动作或状态已经完成，而“会迟到”指尚未发生的推测。", "非常": "搭配：“非常”修饰形容词或心理动词，不能直接修饰“会迟到”这样的助动词短语。", "亲自": "语义：“亲自”强调本人亲身去做，“迟到”不是可以亲自去做的动作。"}, "sentence_index": 6, "correct_answer": "多半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他多半一定会来，我们先等他吧。", "explanation": "“一定”表示确定，与表示推测的“多半”自相矛盾；应去掉其中一个，写作“他一定会来”或“他多半会来”。"}, {"text": "请你多半帮我开门。", "explanation": "“多半”表示推测，不能用于请求或命令；这里应直接说“请你帮我开门”。"}, {"text": "根据公告，报名截止时间多半是周五。", "explanation": "公告中的时间是确定的信息，应直接说“报名截止时间是周五”。“多半”表示推测，与确定的公告内容相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚了，他很多半不在加班。", "corrected_sentence": "这么晚了，他多半不在加班。", "error_description": "错误：“很多半”。“多半”本身是副词，不能再被“很”修饰，应删去“很”。正确说法是“多半不在加班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试他很多半没及格。", "corrected_sentence": "这次考试他多半没及格。", "error_description": "错误：副词“很”修饰了“多半”。正确：“多半”本身是副词，不能再被“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
