INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91187, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里非常害怕。", "primary_collocate": null, "pronunciation": "kǒng jù", "ipa": "kʰʊŋ˨˩˦ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "黑夜里，她一个人走路，心里很恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到奇怪的声音，孩子感到非常恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见了蛇，她恐惧得说不出话来。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震的时候，大家都很恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他恐惧地看着那条大狗，一步也不敢动。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次坐飞机，我既兴奋又恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她恐惧的样子让我觉得很难过。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一想到明天的手术，他就变得很恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜醒来，房间里一点声音也没有，我很恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩恐惧极了，紧紧抱着妈妈。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐惧感", "label": "复合"}, {"form": "恐惧症", "label": "复合"}, {"form": "恐惧不安", "label": "复合"}], "register": "书面", "sense_fingerprint": "心里非常害怕的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大方", "is_correct": false, "explanation": "语义：“大方”形容不拘小节或慷慨，不能形容走夜路时的心情。"}, {"text": "恐惧", "is_correct": true, "explanation": "“恐惧”形容心里非常害怕，与“黑夜里一个人走路”的语境相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容心里的感受。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指想吃东西，与心里的感受无关。"}], "explanations": {"大方": "语义：“大方”形容不拘小节或慷慨，不能形容走夜路时的心情。", "恐惧": "“恐惧”形容心里非常害怕，与“黑夜里一个人走路”的语境相符。", "清脆": "搭配：“清脆”形容声音，不能用来形容心里的感受。", "饿": "语义：“饿”指想吃东西，与心里的感受无关。"}, "sentence_index": 0, "correct_answer": "恐惧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了满分，恐惧得跳了起来。", "explanation": "这里应该用〈兴奋〉。“恐惧”表示心里很怕，与得了满分后的喜悦心情正好相反；高兴激动的心情要用“兴奋”。"}, {"text": "妈妈恐惧地抱着刚出生的宝宝，满脸温柔。", "explanation": "这里应该用〈疼爱〉。“恐惧”表示害怕，与“满脸温柔”的神情正好相反；抱着宝宝时的爱护之情要用“疼爱”。"}, {"text": "孩子们恐惧假期的到来，每天都盼着快点放假。", "explanation": "这里应该用〈期待〉。“恐惧”表示心里很怕，与“盼着快点放假”的心情正好相反；盼望将要到来的好事要用“期待”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崎岖", "is_correct": false, "explanation": "搭配：“崎岖”形容山路等不平坦，不能用来形容人的样子。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能透光，不能用来形容样子。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道或言语，不能用来形容样子。"}, {"text": "恐惧", "is_correct": true, "explanation": "“恐惧”形容害怕的神情，与“她……的样子让我觉得很难过”相符。"}], "explanations": {"崎岖": "搭配：“崎岖”形容山路等不平坦，不能用来形容人的样子。", "透明": "搭配：“透明”形容物体能透光，不能用来形容样子。", "辛辣": "搭配：“辛辣”形容味道或言语，不能用来形容样子。", "恐惧": "“恐惧”形容害怕的神情，与“她……的样子让我觉得很难过”相符。"}, "sentence_index": 6, "correct_answer": "恐惧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们很恐惧小动物，每天都抱着小猫玩。", "explanation": "这里应该用〈喜爱〉。“恐惧”表示害怕，与每天抱着小猫玩的亲近状态正好相反；喜欢小动物要用“喜爱”。"}, {"text": "他总是勇敢地恐惧责任。", "explanation": "这里应该用〈承担〉。“恐惧”表示害怕，与“勇敢”的态度正好相反；主动担起责任要用“承担”。"}, {"text": "我很恐惧他的身体。", "explanation": "这里应该用〈担心〉。“恐惧”表示害怕的感受，不能用来表示为别人的身体担心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨来的时候，孩子恐惧很了。", "corrected_sentence": "暴雨来的时候，孩子恐惧极了。", "error_description": "错误：程度补语“极了”误换成了“很了”。“很”不能用作补语，“恐惧”后面要带“极了”，正确说法是“暴雨来的时候，孩子恐惧极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看见那条大蛇，他恐惧动弹不了。", "corrected_sentence": "看见那条大蛇，他恐惧得动弹不了。", "error_description": "错误：“恐惧”与后面的补语之间漏了“得”。“恐惧得＋动弹不了”表示程度，缺少“得”则句子不成立，正确说法是“他恐惧得动弹不了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "害怕；惊慌。", "primary_collocate": null, "pronunciation": "kǒng jù", "ipa": "kʰʊŋ˨˩˦ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "火灾发生时，大家恐惧得到处乱跑。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到敲门声，神情十分恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在大风里摇晃，乘客们都很恐惧。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她恐惧地叫了一声，转身就跑。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说山里有狼，他恐惧得一夜没睡。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到车冲过来，路上的人一下子恐惧起来。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对大火，他一点也不恐惧，冷静地救人。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲的鬼故事让孩子们恐惧极了。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子突然晃了起来，她恐惧得叫不出声。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的炮声越来越近，城里的人都恐惧了。", "target_word": "恐惧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐惧感", "label": "复合"}, {"form": "恐惧症", "label": "复合"}, {"form": "恐惧不安", "label": "复合"}], "register": "书面", "sense_fingerprint": "因遇到危险而害怕、惊慌失措", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音、不吵闹，与“到处乱跑”的慌乱情景相反。"}, {"text": "恐惧", "is_correct": true, "explanation": "“恐惧”指因危险而惊慌害怕，与“火灾发生时”的情景吻合。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人风趣，不能描述“得到处乱跑”的状态。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述身材，与惊慌乱跑的状态不合。"}], "explanations": {"安静": "语义：“安静”指没有声音、不吵闹，与“到处乱跑”的慌乱情景相反。", "恐惧": "“恐惧”指因危险而惊慌害怕，与“火灾发生时”的情景吻合。", "幽默": "搭配：“幽默”形容人风趣，不能描述“得到处乱跑”的状态。", "胖": "体貌：“胖”描述身材，与惊慌乱跑的状态不合。"}, "sentence_index": 0, "correct_answer": "恐惧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要勇敢恐惧挑战。", "explanation": "这里应该用〈面对〉。“恐惧”表示害怕，与“勇敢”的态度正好相反；勇敢地迎接挑战要用“面对”。"}, {"text": "他看到父亲回来，恐惧地拍手欢呼。", "explanation": "这里应该用〈高兴〉。“恐惧”表示害怕，与“拍手欢呼”的喜悦正好相反；父亲回来而欢喜要用“高兴”。"}, {"text": "我们热烈恐惧你的到来。", "explanation": "这里应该用〈期盼〉。“恐惧”表示害怕，与“热烈”的心情正好相反；盼望客人到来要用“期盼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”指想吃东西，与“面对大火”的情景无关。"}, {"text": "恐惧", "is_correct": true, "explanation": "“恐惧”指害怕、惊慌，“一点也不恐惧”与“冷静地救人”形成对照。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能透光，不能描述人的心理状态。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”指钱财多或内容丰富，与“冷静地救人”的意思不相干。"}], "explanations": {"饥饿": "语义：“饥饿”指想吃东西，与“面对大火”的情景无关。", "恐惧": "“恐惧”指害怕、惊慌，“一点也不恐惧”与“冷静地救人”形成对照。", "透明": "搭配：“透明”形容物体能透光，不能描述人的心理状态。", "富有": "语义：“富有”指钱财多或内容丰富，与“冷静地救人”的意思不相干。"}, "sentence_index": 6, "correct_answer": "恐惧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看到孩子们的进步，老师感到很恐惧。", "explanation": "这里应该用〈欣慰〉。“恐惧”表示害怕，与看到学生进步时的心情正好相反；对学生的进步满心喜悦要用“欣慰”。"}, {"text": "孩子们很恐惧假期的到来，个个跳着喊放假。", "explanation": "这里应该用〈向往〉。“恐惧”表示害怕，与“跳着喊放假”的兴奋状态正好相反；对假期充满憧憬要用“向往”。"}, {"text": "我们要认真恐惧这件事。", "explanation": "这里应该用〈考虑〉。“恐惧”表示害怕，与“认真”思考一件事的意思不合；认真地想要用“考虑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人群一下子恐惧出来。", "corrected_sentence": "人群一下子恐惧起来。", "error_description": "错误：趋向补语“起来”误换成了“出来”。表示状态开始出现的“恐惧起来”要用“起来”，“恐惧出来”不成立，正确说法是“人群一下子恐惧起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他恐惧说不出一句话。", "corrected_sentence": "他恐惧得说不出一句话。", "error_description": "错误：“恐惧”与后面的补语之间漏了“得”。程度补语要用“得”连接，正确说法是“他恐惧得说不出一句话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
