INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走在别人后面，别人去哪里，你也去哪里。", "primary_collocate": null, "pronunciation": "gēn suí", "ipa": "kən˥ swei˧˥", "syllable_count": 2, "sentences": [{"text": "孩子跟随父母搬到了另一个城市。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去哪里，小狗就跟随到哪里。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟随丈夫去了国外工作。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫总是跟随着我，我去哪它去哪。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢跟随哥哥，哥哥去哪他去哪。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子出门总是跟随奶奶。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟随朋友去了他的老家过年。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟跟随着鸟妈妈飞到了南方。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书总是跟随经理出差。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们跟随老师参观了一座老工厂。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟随着", "label": "持续体"}, {"form": "跟随了", "label": "完成体"}, {"form": "跟随过", "label": "经历体"}, {"form": "跟隨", "label": "繁体"}], "register": "中性", "sense_fingerprint": "跟随：别人去哪里，自己也去哪里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟随", "is_correct": true, "explanation": "「跟随」表示孩子随父母一起搬家，与「搬到了另一个城市」的句意一致。"}, {"text": "追赶", "is_correct": false, "explanation": "语义：「追赶」是快速赶上，与孩子和父母同时搬家的句意不符。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：「驱赶」是赶走，与句中孩子随父母同行搬家的意思矛盾。"}, {"text": "出发", "is_correct": false, "explanation": "配价：「出发」是不及物动词，不能带「父母」作宾语，「出发父母」不成立。"}], "explanations": {"跟随": "「跟随」表示孩子随父母一起搬家，与「搬到了另一个城市」的句意一致。", "追赶": "语义：「追赶」是快速赶上，与孩子和父母同时搬家的句意不符。", "驱赶": "语义：「驱赶」是赶走，与句中孩子随父母同行搬家的意思矛盾。", "出发": "配价：「出发」是不及物动词，不能带「父母」作宾语，「出发父母」不成立。"}, "sentence_index": 0, "correct_answer": "跟随"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫总是跟随着我，却一直躺在床上不动。", "explanation": "「跟随」要求随人移动，躺在床上不动与这个词的用法矛盾。"}, {"text": "学生们跟随书本去了图书馆。", "explanation": "书本不能自己移动，不能成为被跟随的对象。"}, {"text": "桌子跟随我去了学校。", "explanation": "「桌子」不能主动跟在别人后面走，作为跟随的主语不符合该词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟随", "is_correct": true, "explanation": "「跟随」表示跟着朋友一起去他的老家，与「去了他的老家过年」的句意一致。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：「抛弃」是丢下不管，与一同前往对方老家的意思相反，句意矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：「躲避」是避开，与句中同去对方老家的意思矛盾。"}, {"text": "站立", "is_correct": false, "explanation": "配价：「站立」是不及物动词，不能带「朋友」作宾语，「站立朋友」不成立。"}], "explanations": {"跟随": "「跟随」表示跟着朋友一起去他的老家，与「去了他的老家过年」的句意一致。", "抛弃": "语义：「抛弃」是丢下不管，与一同前往对方老家的意思相反，句意矛盾。", "躲避": "语义：「躲避」是避开，与句中同去对方老家的意思矛盾。", "站立": "配价：「站立」是不及物动词，不能带「朋友」作宾语，「站立朋友」不成立。"}, "sentence_index": 6, "correct_answer": "跟随"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们跟随了一场比赛。", "explanation": "这里应该用〈参加〉。「跟随」指跟着人或东西走，不能表示参加某项活动。"}, {"text": "学生们跟随了一整天的电视剧。", "explanation": "「跟随」指跟着人或东西走，电视剧不是可以被跟随的对象，这种用法不符合该词。"}, {"text": "学生们跟随了一场考试，结果都很好。", "explanation": "「考试」不是可以被跟随的对象，「跟随」不能用于这种非人的事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天跟随了老师去参观工厂。", "corrected_sentence": "我们明天跟随老师去参观工厂。", "error_description": "「了」表示动作已经完成，不能与将来的「明天」同用；正确写作「明天跟随老师去参观工厂」，错误句在「跟随」后多加了「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她跟随了着丈夫去了国外。", "corrected_sentence": "她跟随着丈夫去了国外。", "error_description": "「跟随」后只能带一个动态助词「着」，「了」与「着」不能叠用；正确写作「跟随着丈夫」，错误句在「着」前多加了「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
