INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "紧接在后面走；追随。", "primary_collocate": null, "pronunciation": "gēn suí", "ipa": "kən˥ swei˧˥", "syllable_count": 2, "sentences": [{"text": "小狗一直跟随着主人走在路上。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们跟随导游走进了老城。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子紧紧跟随妈妈，不敢走远。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家跟随我，不要走散了。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一辆小车跟随在大车后面慢慢开。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子跟随鸭妈妈，排成一队过河。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟随队伍一步一步往山上走。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在前面走，学生们跟随在后。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者一路跟随着那位歌手。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们跟随着前面的人慢慢走出车站。", "target_word": "跟随", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟随着", "label": "持续体"}, {"form": "跟随了", "label": "完成体"}, {"form": "跟随过", "label": "经历体"}, {"form": "跟隨", "label": "繁体"}], "register": "中性", "sense_fingerprint": "跟随：紧紧走在别人后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟随", "is_correct": true, "explanation": "「跟随」表示紧接在后面走，与「一直跟随着主人走在路上」的句意一致。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：「躲避」是避开，与「跟随」的紧随意思相反，句意矛盾。"}, {"text": "停留", "is_correct": false, "explanation": "语义：「停留」是停住不动，与句中「一直……走在路上」的动作冲突。"}, {"text": "站立", "is_correct": false, "explanation": "配价：「站立」是不及物动词，不能带「主人」作宾语，「站立着主人」不成立。"}], "explanations": {"跟随": "「跟随」表示紧接在后面走，与「一直跟随着主人走在路上」的句意一致。", "躲避": "语义：「躲避」是避开，与「跟随」的紧随意思相反，句意矛盾。", "停留": "语义：「停留」是停住不动，与句中「一直……走在路上」的动作冲突。", "站立": "配价：「站立」是不及物动词，不能带「主人」作宾语，「站立着主人」不成立。"}, "sentence_index": 0, "correct_answer": "跟随"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈跟随孩子在客厅里看电视。", "explanation": "这里误用了「跟随」的移动义，把它当作「陪伴」来用。「跟随」只表示紧跟着移动，静坐在客厅里不能用，此处应说「陪」。"}, {"text": "他跟随大家，走在了最前面。", "explanation": "这里应该用〈带领〉。「跟随」是紧跟在别人后面走，与「走在最前面」矛盾，领头应说「带领」。"}, {"text": "学生们跟随书本走进了教室。", "explanation": "「跟随」的对象必须是能行走的人或动物，书本不会走，不能被跟随。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟随", "is_correct": true, "explanation": "「跟随」表示紧跟着队伍走，与「一步一步往山上走」的句意一致。"}, {"text": "阻拦", "is_correct": false, "explanation": "语义：「阻拦」是拦住，与队伍「往山上走」的行进方向相反，句意矛盾。"}, {"text": "攀登", "is_correct": false, "explanation": "配价：「攀登」的宾语应是山峰或高处，不能接「队伍」作宾语。"}, {"text": "倒退", "is_correct": false, "explanation": "配价：「倒退」是不及物动词，不能带「队伍」作宾语，「倒退队伍」不成立。"}], "explanations": {"跟随": "「跟随」表示紧跟着队伍走，与「一步一步往山上走」的句意一致。", "阻拦": "语义：「阻拦」是拦住，与队伍「往山上走」的行进方向相反，句意矛盾。", "攀登": "配价：「攀登」的宾语应是山峰或高处，不能接「队伍」作宾语。", "倒退": "配价：「倒退」是不及物动词，不能带「队伍」作宾语，「倒退队伍」不成立。"}, "sentence_index": 6, "correct_answer": "跟随"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他跟随了所有同学，结果考了第一名。", "explanation": "这里应该用〈超过〉。「跟随」是走在别人后面，与「考了第一名」所需的超越义矛盾，应说「超过」。"}, {"text": "前面的人跟随着我们慢慢走出车站。", "explanation": "「跟随」的一方应走在被跟随者的后面，而此处让走在前面的人去跟随「我们」，行进方向与该词的含义相反。"}, {"text": "我们跟随着前面的人，却往相反的方向走去。", "explanation": "「跟随」要求朝同一方向走，句中说往相反方向走，与该词的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跟随了着队伍慢慢往山下走。", "corrected_sentence": "他跟随着队伍慢慢往山下走。", "error_description": "「跟随」后只能带一个动态助词「着」，「了」与「着」不能叠用；正确写作「跟随着队伍」，错误句在「着」前多加了「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天跟随了老师去车站。", "corrected_sentence": "我们明天跟随老师去车站。", "error_description": "「了」表示动作已经完成，不能与将来的「明天」同用；正确写作「明天跟随老师去车站」，错误句在「跟随」后多加了「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有用", "is_correct": true, "explanation": "有用指能派上用场，与“用不着的多余”意思相反，是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "与“多余”没有反义关系，聪明指智力高，与该义项无关。"}, {"text": "热闹", "is_correct": false, "explanation": "与“多余”没有反义关系，热闹指场面喧闹，与该义项无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“多余”没有反义关系，清楚指明白、不模糊，与该义项无关。"}], "correct_answer": "有用", "explanations": {"有用": "有用指能派上用场，与“用不着的多余”意思相反，是反义词。", "聪明": "与“多余”没有反义关系，聪明指智力高，与该义项无关。", "热闹": "与“多余”没有反义关系，热闹指场面喧闹，与该义项无关。", "清楚": "与“多余”没有反义关系，清楚指明白、不模糊，与该义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有用", "is_correct": true, "explanation": "有用指能派上用场，与“多余”（用不着）的义项意思相反，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "与“多余”没有反义关系，明亮指光线充足，与该义项无关。"}, {"text": "吵闹", "is_correct": false, "explanation": "与“多余”没有反义关系，吵闹指声音杂乱，与该义项无关。"}, {"text": "结实", "is_correct": false, "explanation": "与“多余”没有反义关系，结实指坚固、有力，与该义项无关。"}], "correct_answer": "有用", "explanations": {"有用": "有用指能派上用场，与“多余”（用不着）的义项意思相反，是反义词。", "明亮": "与“多余”没有反义关系，明亮指光线充足，与该义项无关。", "吵闹": "与“多余”没有反义关系，吵闹指声音杂乱，与该义项无关。", "结实": "与“多余”没有反义关系，结实指坚固、有力，与该义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多余是多出来、用不着的。", "primary_collocate": null, "pronunciation": "duō yú", "ipa": "twɔ˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "桌子上有一张多余的票。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多余的东西可以送给别人。", "target_word": "多余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我多余的书都给了弟弟。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子在这里很多余。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服太多，有几件是多余的。", "target_word": "多余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别带多余的行李。", "target_word": "多余", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他觉得自己在这里很多余。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭时多余的米怎么办？", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把多余的纸拿走。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子多余了，不用了。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多出来而用不着的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多余", "is_correct": true, "explanation": "多余指多出来、用不着，符合“桌子上有一张多余的票”的语境。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴形容人的心情，票不能高兴，搭配不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖形容人或动物的体态，不能用来形容票。"}, {"text": "精辟", "is_correct": false, "explanation": "语义：精辟形容言论或文章深刻透彻，不能用来形容票。"}], "explanations": {"多余": "多余指多出来、用不着，符合“桌子上有一张多余的票”的语境。", "高兴": "语义：高兴形容人的心情，票不能高兴，搭配不通。", "胖": "体貌：胖形容人或动物的体态，不能用来形容票。", "精辟": "语义：精辟形容言论或文章深刻透彻，不能用来形容票。"}, "sentence_index": 0, "correct_answer": "多余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司给他发了多余的奖金，大家都很羡慕。", "explanation": "这里应该用〈额外〉。多余表示用不着，奖金等增加的好处要用额外。"}, {"text": "他家的生活很多余，从不愁钱。", "explanation": "这里应该用〈富裕〉。多余表示用不着，形容家境宽裕要用富裕。"}, {"text": "十除以三，多余一。", "explanation": "这里应该用〈余〉。表示除法剩下的数要用“余”，“多余”表示用不着，不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多余", "is_correct": true, "explanation": "多余指多出来、用不着，此处指人觉得自己不被需要，符合语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜形容味道，不能用来形容人的处境或感觉。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：矮小形容人或物的体型，与“在这里的感觉”无关。"}, {"text": "绿", "is_correct": false, "explanation": "语义：绿是颜色，不能用来形容人的处境或感觉。"}], "explanations": {"多余": "多余指多出来、用不着，此处指人觉得自己不被需要，符合语境。", "甜": "语义：甜形容味道，不能用来形容人的处境或感觉。", "矮小": "体貌：矮小形容人或物的体型，与“在这里的感觉”无关。", "绿": "语义：绿是颜色，不能用来形容人的处境或感觉。"}, "sentence_index": 6, "correct_answer": "多余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的身高多余我五厘米。", "explanation": "这里应该用〈多〉或〈高〉。多余表示多出来、用不着，不用于比较身高，应说“比我高五厘米”。"}, {"text": "这点力气绰绰多余，够搬了。", "explanation": "这里应该用〈有余〉。“绰绰有余”是固定说法，“多余”不能与“绰绰”搭配。"}, {"text": "这次比赛他多余我三分。", "explanation": "这里应该用〈领先〉。多余表示用不着，比分的差距要说“领先”或“多三分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张票现在多余着。", "corrected_sentence": "这张票现在多余了。", "error_description": "“着”误用：“多余”是形容词，表示用不着，不能用“着”表示持续；表示状态变化应用“了”。正确说法是“现在多余了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上放着一把多余椅子。", "corrected_sentence": "桌上放着一把多余的椅子。", "error_description": "助词“的”遗漏：“多余”修饰名词时一般要加“的”，“多余椅子”不自然。正确说法是“多余的椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "必要", "is_correct": true, "explanation": "必要指需要、不可缺少，与“不必要的多余”意思相反，是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "与“多余”没有反义关系，聪明指智力高，与该义项无关。"}, {"text": "热闹", "is_correct": false, "explanation": "与“多余”没有反义关系，热闹指场面喧闹，与该义项无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“多余”没有反义关系，清楚指明白、不模糊，与该义项无关。"}], "correct_answer": "必要", "explanations": {"必要": "必要指需要、不可缺少，与“不必要的多余”意思相反，是反义词。", "聪明": "与“多余”没有反义关系，聪明指智力高，与该义项无关。", "热闹": "与“多余”没有反义关系，热闹指场面喧闹，与该义项无关。", "清楚": "与“多余”没有反义关系，清楚指明白、不模糊，与该义项无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "必要", "is_correct": true, "explanation": "必要指需要、不可缺少，与“没说一句多余的话”中的“多余”意思相反，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "与“多余”没有反义关系，明亮指光线充足，与该义项无关。"}, {"text": "吵闹", "is_correct": false, "explanation": "与“多余”没有反义关系，吵闹指声音杂乱，与该义项无关。"}, {"text": "结实", "is_correct": false, "explanation": "与“多余”没有反义关系，结实指坚固、有力，与该义项无关。"}], "correct_answer": "必要", "explanations": {"必要": "必要指需要、不可缺少，与“没说一句多余的话”中的“多余”意思相反，是反义词。", "明亮": "与“多余”没有反义关系，明亮指光线充足，与该义项无关。", "吵闹": "与“多余”没有反义关系，吵闹指声音杂乱，与该义项无关。", "结实": "与“多余”没有反义关系，结实指坚固、有力，与该义项无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "超过需要的；不必要的。", "primary_collocate": null, "pronunciation": "duō yú", "ipa": "twɔ˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "这句话是多余的。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一步是多余的，可以不做。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得我的提醒很多余。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要做多余的事。", "target_word": "多余", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字多了一笔，是多余的。", "target_word": "多余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些客气话都是多余的。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的解释很多余。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图片很多余，可以删掉。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的担心是多余的。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没说一句多余的话。", "target_word": "多余", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不必要的，没有必要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多余", "is_correct": true, "explanation": "多余指超过需要、不必要，符合“这句话是多余的”的语境。"}, {"text": "透明", "is_correct": false, "explanation": "语义：透明用于物体、液体等，不能用来形容句子。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖形容人或动物的体态，不能用来形容句子。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴形容人的心情，句子没有心情，搭配不通。"}], "explanations": {"多余": "多余指超过需要、不必要，符合“这句话是多余的”的语境。", "透明": "语义：透明用于物体、液体等，不能用来形容句子。", "胖": "体貌：胖形容人或动物的体态，不能用来形容句子。", "高兴": "语义：高兴形容人的心情，句子没有心情，搭配不通。"}, "sentence_index": 0, "correct_answer": "多余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司给他发了多余的奖金，大家都很羡慕。", "explanation": "这里应该用〈额外〉。多余含“不必要”的意思，奖金等增加的好处要用额外。"}, {"text": "他家的日子很多余，不用省钱。", "explanation": "这里应该用〈富裕〉。多余表示超过需要、用不着，形容家境宽裕要用富裕。"}, {"text": "他比我多余两岁。", "explanation": "这里应该用〈大〉。多余表示超过需要、用不着，不用于比较年龄，应说“比我大两岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多余", "is_correct": true, "explanation": "多余指超过需要、不必要，符合“这里的解释很多余”的语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜形容味道，不能用来形容解释。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：矮小形容人或物的体型，与解释无关。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：冷清形容场所或气氛，解释不能说冷清。"}], "explanations": {"多余": "多余指超过需要、不必要，符合“这里的解释很多余”的语境。", "甜": "语义：甜形容味道，不能用来形容解释。", "矮小": "体貌：矮小形容人或物的体型，与解释无关。", "冷清": "语义：冷清形容场所或气氛，解释不能说冷清。"}, "sentence_index": 6, "correct_answer": "多余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "七除以三，多余一。", "explanation": "这里应该用〈余〉。表示除法剩下的数要用“余”，“多余”表示超过需要、用不着，不能用于此。"}, {"text": "这笔钱绰绰多余，够我们花一年了。", "explanation": "这里应该用〈有余〉。“绰绰有余”是固定说法，“多余”不能与“绰绰”搭配。"}, {"text": "这个班的学生多余二十人。", "explanation": "这里应该用〈多于〉。多余表示超过需要、不必要，比较数量要用“多于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧报纸现在多余着。", "corrected_sentence": "这些旧报纸现在多余了。", "error_description": "“着”误用：“多余”是形容词，表示不必要，不能用“着”表示持续；表示状态变化应用“了”。正确说法是“现在多余了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他留下了一件多余衣服。", "corrected_sentence": "他留下了一件多余的衣服。", "error_description": "助词“的”遗漏：“多余”修饰名词时一般要加“的”，“多余衣服”不自然。正确说法是“多余的衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
