INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91193, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情形是事情现在是什么样子。", "primary_collocate": null, "pronunciation": "qíng xíng", "ipa": "tɕʰiŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "医生问我病人现在的情形。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说那里的情形吧。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到家里的情形，我吓了一跳。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知道比赛的情形，我很着急。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把当时的情形说给大家听。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，路上的情形很不好。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我考试的情形怎么样。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我回国后，朋友们常问我国外的情形。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的情形和去年一样，没有变化。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲起了小时候家里的情形。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种情形", "label": "量词（种）"}], "register": "中性", "sense_fingerprint": "事情当前的样子、状况，常问或说某处、某人的情形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91193, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确答案。情形指事情现在是什么样子。"}, {"text": "清醒", "is_correct": false, "explanation": "qīng（第一声）与 qíng（第二声）、xǐng（第三声）与 xíng（第二声）声调不同，意思是头脑清楚。"}, {"text": "轻型", "is_correct": false, "explanation": "qīng（第一声）与 qíng（第二声）声调不同，意思是轻便的类型。"}, {"text": "庆幸", "is_correct": false, "explanation": "qìng（第四声）与 qíng（第二声）、xìng（第四声）与 xíng（第二声）声调不同，意思是为好事感到高兴。"}], "explanations": {"情形": "正确答案。情形指事情现在是什么样子。", "清醒": "qīng（第一声）与 qíng（第二声）、xǐng（第三声）与 xíng（第二声）声调不同，意思是头脑清楚。", "轻型": "qīng（第一声）与 qíng（第二声）声调不同，意思是轻便的类型。", "庆幸": "qìng（第四声）与 qíng（第二声）、xìng（第四声）与 xíng（第二声）声调不同，意思是为好事感到高兴。"}, "sentence_index": null, "correct_answer": "情形"}, "level_3": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确：“情形”指事情现在的样子，可以用来问病人的情况。"}, {"text": "天气", "is_correct": false, "explanation": "语义：医生问的是病人的状况，不会问天气。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是物品，不是病人的状况，医生不会问“病人现在的钥匙”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不用于人的状况，“病人现在的价格”搭配不当。"}], "explanations": {"情形": "正确：“情形”指事情现在的样子，可以用来问病人的情况。", "天气": "语义：医生问的是病人的状况，不会问天气。", "钥匙": "语义：钥匙是物品，不是病人的状况，医生不会问“病人现在的钥匙”。", "价格": "搭配：“价格”不用于人的状况，“病人现在的价格”搭配不当。"}, "sentence_index": 0, "correct_answer": "情形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的情形一下子变得很温柔，冲我笑了笑。", "explanation": "这里应该用〈表情〉。“情形”指事情的状况，不指人的面部神情；“变得很温柔”“笑了笑”只能用于表情。"}, {"text": "今天的情形阳光明媚，很适合去郊游。", "explanation": "这里应该用〈天气〉。“情形”指事情的状况，不指天气；“阳光明媚”描述的是天气。"}, {"text": "他的情形很高，坐在最后一排也能看清黑板。", "explanation": "这里应该用〈个子〉。“情形”不指人的身高；“很高”描述的是个子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确：“考试的情形”指考试的具体状况，可以问“怎么样”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：考试没有年龄，不能问“考试的年龄怎么样”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：考试不具有颜色，“考试的颜色怎么样”不成立。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”只用于人，不能说“考试的容貌”。"}], "explanations": {"情形": "正确：“考试的情形”指考试的具体状况，可以问“怎么样”。", "年龄": "语义：考试没有年龄，不能问“考试的年龄怎么样”。", "颜色": "语义：考试不具有颜色，“考试的颜色怎么样”不成立。", "容貌": "体貌：“容貌”只用于人，不能说“考试的容貌”。"}, "sentence_index": 6, "correct_answer": "情形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对家乡的情形很深。", "explanation": "这里应该用〈感情〉。“情形”不能用来表示对家乡的情感。"}, {"text": "她对工作很有情形，每天都很早到。", "explanation": "这里应该用〈热情〉。“有情形”不是说人对工作的态度。"}, {"text": "他对她的情形一往情深，每天都给她写信。", "explanation": "这里应该用〈爱情〉。“情形”指事情的状况，不能表示恋人之间的感情；“一往情深”说的是爱情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条情形我从没遇到过。", "corrected_sentence": "这种情形我从没遇到过。", "error_description": "量词错误：“情形”不是长条形事物，不能用“条”，应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些情形们都很复杂，需要慢慢处理。", "corrected_sentence": "这些情形都很复杂，需要慢慢处理。", "error_description": "词尾错误：“情形”后面不能加“们”，表示多数时直接用“这些”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
