INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物表现出来的样子；情况。", "primary_collocate": null, "pronunciation": "qíng xíng", "ipa": "tɕʰiŋ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种情形下，我们只能等。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在什么情形下你会生气？", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我第一次见到这样的情形。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情形不太好，我们得想想办法。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样的情形，每年都会出现一次。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他现在的情形，一周后就能出院。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到这种情形，你应该马上打电话。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的情形不同，选择也不一样。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司现在的情形，大家都很清楚。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在有些情形下，说真话很难。", "target_word": "情形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种情形", "label": "量词（种）"}, {"form": "这种情形", "label": "指示搭配"}], "register": "中性", "sense_fingerprint": "事物表现出的样子，即情况、局面（这种情形、在……情形下）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确答案。情形指事物表现出来的样子或情况。"}, {"text": "清醒", "is_correct": false, "explanation": "qīng（第一声）与 qíng（第二声）、xǐng（第三声）与 xíng（第二声）声调不同，意思是头脑清楚。"}, {"text": "轻型", "is_correct": false, "explanation": "qīng（第一声）与 qíng（第二声）声调不同，意思是轻便的类型。"}, {"text": "庆幸", "is_correct": false, "explanation": "qìng（第四声）与 qíng（第二声）、xìng（第四声）与 xíng（第二声）声调不同，意思是为好事感到高兴。"}], "explanations": {"情形": "正确答案。情形指事物表现出来的样子或情况。", "清醒": "qīng（第一声）与 qíng（第二声）、xǐng（第三声）与 xíng（第二声）声调不同，意思是头脑清楚。", "轻型": "qīng（第一声）与 qíng（第二声）声调不同，意思是轻便的类型。", "庆幸": "qìng（第四声）与 qíng（第二声）、xìng（第四声）与 xíng（第二声）声调不同，意思是为好事感到高兴。"}, "sentence_index": null, "correct_answer": "情形"}, "level_3": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确：“这种情形下”指在这种状况下，常用“情形”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色下”不能表示条件。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字下”没有意义，不表示条件。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“……下”表示条件，房间不能作条件，应说“房间里”。"}], "explanations": {"情形": "正确：“这种情形下”指在这种状况下，常用“情形”。", "颜色": "语义：“颜色下”不能表示条件。", "名字": "语义：“名字下”没有意义，不表示条件。", "房间": "搭配：“……下”表示条件，房间不能作条件，应说“房间里”。"}, "sentence_index": 0, "correct_answer": "情形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听这话，情形立刻变得很和气，笑着点了头。", "explanation": "这里应该用〈表情〉。“情形”不指人的面部神情；“变得很和气”“笑着点头”描述的是表情。"}, {"text": "他的情形很外向，喜欢认识新朋友。", "explanation": "这里应该用〈性格〉。“情形”指事情的状况，不指人的性格；“很外向”描述的是性格。"}, {"text": "这个人的情形很高大，站在门口挡住了光。", "explanation": "这里应该用〈身材〉。“情形”不指人的身材；“很高大”描述的是身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情形", "is_correct": true, "explanation": "正确：“遇到这种情形”指遇到这种状况，应当马上打电话。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是需要马上打电话处理的状况。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“遇到”后接事件或状况，“钥匙”是物，应说“找到钥匙”。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体不是需要马上打电话处理的状况。"}], "explanations": {"情形": "正确：“遇到这种情形”指遇到这种状况，应当马上打电话。", "天空": "语义：天空不是需要马上打电话处理的状况。", "钥匙": "搭配：“遇到”后接事件或状况，“钥匙”是物，应说“找到钥匙”。", "字体": "语义：字体不是需要马上打电话处理的状况。"}, "sentence_index": 6, "correct_answer": "情形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这桌菜的情形很香，大家都想吃。", "explanation": "这里应该用〈味道〉。“情形”指事情的状况，不指食物的香味；“很香”描述的是味道。"}, {"text": "她对工作很有情形，每天都很早到。", "explanation": "这里应该用〈热情〉。“有情形”不是说人对工作的态度。"}, {"text": "她和他的情形很专一，几十年都没变过心。", "explanation": "这里应该用〈爱情〉。“情形”不能表示恋人之间的感情；“很专一”“没变过心”说的是爱情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位情形下，大家都很冷静。", "corrected_sentence": "这种情形下，大家都很冷静。", "error_description": "量词错误：“情形”不是人，不能用“位”，应该用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些情形们我都见过。", "corrected_sentence": "这些情形我都见过。", "error_description": "词尾错误：“情形”后面不能加“们”，表示多数时直接用“这些”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
