INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91195, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从这个地方搬到别的地方住。", "primary_collocate": null, "pronunciation": "qiān", "ipa": "tɕʰiɛn˥", "syllable_count": 1, "sentences": [{"text": "他们一家下个月迁到北京。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷年轻时迁到了南方。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人迁走了，房子空着。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生全家迁往上海。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想迁到离学校近的地方住。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从农村迁出来，住进了城里。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李家三年前迁到了这个小城。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说邻居要迁到国外去。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子上学，我们打算迁到城里。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家这几年迁过三次。", "target_word": "迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迁了", "label": "体标"}, {"form": "迁过", "label": "体标"}, {"form": "遷", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或家庭从原来住的地方搬到别处居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91195, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迁", "is_correct": true, "explanation": "迁（qiān，第一声）指人或家庭从原来住的地方搬到别处居住，就是本句的意思。"}, {"text": "钱", "is_correct": false, "explanation": "钱（qián，第二声）与迁（qiān，第一声）声调不同，意思是货币，与搬家无关。"}, {"text": "前", "is_correct": false, "explanation": "前（qián，第二声）与迁（qiān，第一声）声调不同，意思是前面。"}, {"text": "浅", "is_correct": false, "explanation": "浅（qiǎn，第三声）与迁（qiān，第一声）声调不同，意思是不深。"}, {"text": "墙", "is_correct": false, "explanation": "墙（qiáng）与迁（qiān）韵尾不同（ng 与 n），声调也不同，意思是墙壁。"}, {"text": "先", "is_correct": false, "explanation": "先（xiān）与迁（qiān）声母不同（x 与 q），意思是先后的先。"}, {"text": "枪", "is_correct": false, "explanation": "枪（qiāng）与迁（qiān）韵尾不同（ng 与 n），声调相同，意思是武器。"}], "explanations": {"迁": "迁（qiān，第一声）指人或家庭从原来住的地方搬到别处居住，就是本句的意思。", "钱": "钱（qián，第二声）与迁（qiān，第一声）声调不同，意思是货币，与搬家无关。", "前": "前（qián，第二声）与迁（qiān，第一声）声调不同，意思是前面。", "浅": "浅（qiǎn，第三声）与迁（qiān，第一声）声调不同，意思是不深。", "墙": "墙（qiáng）与迁（qiān）韵尾不同（ng 与 n），声调也不同，意思是墙壁。", "先": "先（xiān）与迁（qiān）声母不同（x 与 q），意思是先后的先。", "枪": "枪（qiāng）与迁（qiān）韵尾不同（ng 与 n），声调相同，意思是武器。"}, "sentence_index": null, "correct_answer": "迁"}, "level_3": {"options": [{"text": "迁", "is_correct": true, "explanation": "迁：「迁到北京」指从原来的地方搬到别处住，与“他们一家搬去北京住”的意思相符。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄物品，不能说一家人被寄到北京去住。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要被送的对象和去处，“他们一家”不能作为被送的对象，句子不成立。"}, {"text": "运", "is_correct": false, "explanation": "搭配：“运”的常见搭配是货物或设备，不能说一家人被运到北京。"}], "explanations": {"迁": "迁：「迁到北京」指从原来的地方搬到别处住，与“他们一家搬去北京住”的意思相符。", "寄": "语义：“寄”指邮寄物品，不能说一家人被寄到北京去住。", "送": "配价：“送”需要被送的对象和去处，“他们一家”不能作为被送的对象，句子不成立。", "运": "搭配：“运”的常见搭配是货物或设备，不能说一家人被运到北京。"}, "sentence_index": 0, "correct_answer": "迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这张桌子迁到窗边。", "explanation": "这里应该用〈搬〉。迁用于人或家庭搬到别处住，移动桌子等物品要用搬。"}, {"text": "公司迁走了三位老员工。", "explanation": "这里应该用〈调〉。迁指人或家庭整体搬到别处居住，调动员工的岗位要用调。"}, {"text": "周末我们迁到公园去玩。", "explanation": "这里应该用〈去〉。迁指长期搬到别处住，短时间外出玩要用去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91195, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迁", "is_correct": true, "explanation": "迁（qiān，第一声）指人或家庭从原来住的地方搬到别处居住，就是本句的意思。"}, {"text": "欠", "is_correct": false, "explanation": "欠（qiàn，第四声）与迁（qiān，第一声）声调不同，意思是欠债。"}, {"text": "腔", "is_correct": false, "explanation": "腔（qiāng）与迁（qiān）韵尾不同（ng 与 n），声调相同，意思是腔调。"}, {"text": "强", "is_correct": false, "explanation": "强（qiáng）与迁（qiān）韵尾不同（ng 与 n），声调也不同，意思是强大。"}, {"text": "鲜", "is_correct": false, "explanation": "鲜（xiān）与迁（qiān）声母不同（x 与 q），意思是新鲜。"}], "explanations": {"迁": "迁（qiān，第一声）指人或家庭从原来住的地方搬到别处居住，就是本句的意思。", "欠": "欠（qiàn，第四声）与迁（qiān，第一声）声调不同，意思是欠债。", "腔": "腔（qiāng）与迁（qiān）韵尾不同（ng 与 n），声调相同，意思是腔调。", "强": "强（qiáng）与迁（qiān）韵尾不同（ng 与 n），声调也不同，意思是强大。", "鲜": "鲜（xiān）与迁（qiān）声母不同（x 与 q），意思是新鲜。"}, "sentence_index": null, "correct_answer": "迁"}, "level_3": {"options": [{"text": "迁", "is_correct": true, "explanation": "迁：「迁到了这个小城」指举家搬到小城居住，与句意相符。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”是拍打或拍摄，不能说一家人拍到小城。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”是丢弃，不能说一家人扔到小城。"}, {"text": "发", "is_correct": false, "explanation": "搭配：“发”多接物品或文件，不能说一家人发到小城。"}], "explanations": {"迁": "迁：「迁到了这个小城」指举家搬到小城居住，与句意相符。", "拍": "搭配：“拍”是拍打或拍摄，不能说一家人拍到小城。", "扔": "搭配：“扔”是丢弃，不能说一家人扔到小城。", "发": "搭配：“发”多接物品或文件，不能说一家人发到小城。"}, "sentence_index": 6, "correct_answer": "迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把这份礼物迁到朋友家。", "explanation": "这里应该用〈送〉。迁用于人或家庭搬到别处住，送礼物要用送。"}, {"text": "我们把这笔钱迁到了朋友的账户上。", "explanation": "这里应该用〈转〉。迁指人或家庭搬到别处住，转账款项要说「转」。"}, {"text": "他一生气就迁到楼上去了。", "explanation": "这里应该用〈上〉。迁指长期搬到别处住，一生气去楼上只是短暂移动，要用上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们三年前迁了到上海。", "corrected_sentence": "他们三年前迁到了上海。", "error_description": "“了”应放在补语“到”之后，说“迁到了上海”；“迁了到上海”中“了”的位置错误，是常见的语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家这几年过迁两次。", "corrected_sentence": "我们家这几年迁过两次。", "error_description": "“过”是动态助词，要紧跟动词，应说“迁过两次”，不能说“过迁两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
