INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天车是挂在高处、能搬很重东西的机器。", "primary_collocate": null, "pronunciation": "tiān chē", "ipa": "tʰjɛn˥ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "天车是工厂里挂在高处的机器。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在工厂里第一次看到天车。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台天车能搬很重的东西。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在车间里操作天车。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车沿着高高的铁轨慢慢移动。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车把一箱箱货物吊到了卡车上。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抬头看着车间顶上的天车。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车的声音很大，工人要戴耳罩。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们参观工厂，还让我们看了天车。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天车一动，下面的人都走开了。", "target_word": "天车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "天车：挂在高处能搬重物的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天车", "is_correct": true, "explanation": "天车：挂在高处、能搬运重物的机器，与“工厂里挂在高处”相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是挂在高处的机器。"}, {"text": "锅", "is_correct": false, "explanation": "语义：锅是炊具，不是挂在高处的机器。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“挂在高处”说的是固定悬挂的设备，不说汽车挂在高处。"}], "explanations": {"天车": "天车：挂在高处、能搬运重物的机器，与“工厂里挂在高处”相符。", "椅子": "语义：椅子是家具，不是挂在高处的机器。", "锅": "语义：锅是炊具，不是挂在高处的机器。", "汽车": "搭配：“挂在高处”说的是固定悬挂的设备，不说汽车挂在高处。"}, "sentence_index": 0, "correct_answer": "天车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车间里新买了一本天车。", "explanation": "这里应该用〈台〉。天车是机器，“本”用于书册，不能用于天车。"}, {"text": "我爷爷每天骑着天车去菜市场买菜。", "explanation": "这里应该用〈三轮车〉。天车是挂在高处、沿轨道吊运重物的机器，不能骑着去菜市场。"}, {"text": "仓库里的天车把货箱叉到了货架上。", "explanation": "这里应该用〈叉车〉。天车悬挂在高处、沿轨道吊运，不能像叉车那样用货叉从地面叉起货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天车", "is_correct": true, "explanation": "天车：车间顶上悬挂的起重机，与“车间顶上的”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是放在地面的家具，不会悬在车间顶上。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是供人坐的家具，不会悬在车间顶上。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不会悬挂在车间顶上。"}], "explanations": {"天车": "天车：车间顶上悬挂的起重机，与“车间顶上的”相符。", "桌子": "语义：桌子是放在地面的家具，不会悬在车间顶上。", "沙发": "语义：沙发是供人坐的家具，不会悬在车间顶上。", "蛋糕": "语义：蛋糕是食物，不会悬挂在车间顶上。"}, "sentence_index": 6, "correct_answer": "天车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厂房的天车把成品送到了三楼。", "explanation": "这里应该用〈货梯〉。天车只能在车间高处沿轨道横向吊运，不能把货物送上楼层。"}, {"text": "滑雪场的天车载着游客往上走。", "explanation": "这里应该用〈缆车〉。天车是工厂里吊运货物的起重机，不载人，也不在滑雪场运行。"}, {"text": "酒店的天车把行李送到了十楼。", "explanation": "这里应该用〈电梯〉。天车只吊运货物，不能用来运送行李上楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂里有一只天车在工作。", "corrected_sentence": "工厂里有一台天车在工作。", "error_description": "“一只天车”错误，应为“一台天车”。天车是机器，量词用“台”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸以前开了过天车，所以很熟练。", "corrected_sentence": "我爸爸以前开过天车，所以很熟练。", "error_description": "“开了过天车”错误，应为“开过天车”。“了”和“过”不能同时用在同一个动词后，表示有过经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
