INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91199, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "援助是别人有难，你去帮他。", "primary_collocate": null, "pronunciation": "yuán zhù", "ipa": "yɛn˧˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "地震以后，很多人来援助灾区。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家失火了，我们立即前去援助。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家援助了这个受灾的地区。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡发了大水，政府很快派人去援助。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，大家一起援助受灾的人。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校援助了几个没钱上学的孩子。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直援助山区的小学。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家遇到困难时，我们一定去援助。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们赶到灾区，援助受伤的人。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪封了路，村民们互相援助。", "target_word": "援助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "援助了", "label": "体标"}, {"form": "援助过", "label": "体标"}, {"form": "经济援助", "label": "复合"}], "register": "书面", "sense_fingerprint": "他人遇到困难时前去帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助（yuán zhù）：有难时前去帮助别人。"}, {"text": "圆珠", "is_correct": false, "explanation": "声调：圆珠（yuánzhū）与援助（yuán zhù）第二个音节声调不同（第一声与第四声），意思是圆珠（笔）。"}, {"text": "原主", "is_correct": false, "explanation": "声调：原主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同（第三声与第四声），意思是原来的主人。"}, {"text": "园主", "is_correct": false, "explanation": "声调：园主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同，意思是园子的主人。"}, {"text": "元素", "is_correct": false, "explanation": "声母：元素（yuánsù）与援助（yuán zhù）第二个音节声母不同（s 与 zh），意思是元素。"}], "explanations": {"援助": "援助（yuán zhù）：有难时前去帮助别人。", "圆珠": "声调：圆珠（yuánzhū）与援助（yuán zhù）第二个音节声调不同（第一声与第四声），意思是圆珠（笔）。", "原主": "声调：原主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同（第三声与第四声），意思是原来的主人。", "园主": "声调：园主（yuánzhǔ）与援助（yuán zhù）第二个音节声调不同，意思是园子的主人。", "元素": "声母：元素（yuánsù）与援助（yuán zhù）第二个音节声母不同（s 与 zh），意思是元素。"}, "sentence_index": null, "correct_answer": "援助"}, "level_3": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助：前去帮助灾区，与“地震以后”的语境相合。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”是毁坏，与地震后前来帮忙的语境相反。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”要求人作宾语，不能说欢迎灾区。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑物，不能说拆除灾区，与救援的语境无关。"}], "explanations": {"援助": "援助：前去帮助灾区，与“地震以后”的语境相合。", "破坏": "语义：“破坏”是毁坏，与地震后前来帮忙的语境相反。", "欢迎": "搭配：“欢迎”要求人作宾语，不能说欢迎灾区。", "拆除": "搭配：“拆除”的对象是建筑物，不能说拆除灾区，与救援的语境无关。"}, "sentence_index": 0, "correct_answer": "援助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直援助我的梦想。", "explanation": "这里应该用〈支持〉。援助指向有困难的人或地区提供实际帮助，不用于梦想这类抽象事物。"}, {"text": "他援助了一家赚钱的公司。", "explanation": "这里应该用〈投资〉。援助是给有困难一方的帮助，已经赚钱的公司不需要援助，出资做生意要说投资。"}, {"text": "那家公司援助了这场比赛。", "explanation": "这里应该用〈赞助〉。援助的对象是有困难的人或地区，对比赛等活动出资要说赞助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91199, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助（yuán zhù）：有难时前去帮助别人。"}, {"text": "原剧", "is_correct": false, "explanation": "声母：原剧（yuánjù）与援助（yuán zhù）第二个音节声母不同（j 与 zh），意思是原创的戏剧。"}, {"text": "圆周", "is_correct": false, "explanation": "韵母：圆周（yuánzhōu）与援助（yuán zhù）第二个音节韵母和声调不同（ou 与 u），意思是圆的一周。"}, {"text": "园路", "is_correct": false, "explanation": "声母：园路（yuánlù）与援助（yuán zhù）第二个音节声母不同（l 与 zh），意思是园中的小路。"}], "explanations": {"援助": "援助（yuán zhù）：有难时前去帮助别人。", "原剧": "声母：原剧（yuánjù）与援助（yuán zhù）第二个音节声母不同（j 与 zh），意思是原创的戏剧。", "圆周": "韵母：圆周（yuánzhōu）与援助（yuán zhù）第二个音节韵母和声调不同（ou 与 u），意思是圆的一周。", "园路": "声母：园路（yuánlù）与援助（yuán zhù）第二个音节声母不同（l 与 zh），意思是园中的小路。"}, "sentence_index": null, "correct_answer": "援助"}, "level_3": {"options": [{"text": "援助", "is_correct": true, "explanation": "援助：长期帮助山区，与“一直”搭配自然。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能直接带处所宾语，要说“毕业于”。"}, {"text": "修改", "is_correct": false, "explanation": "搭配：“修改”的对象是文章、计划等，不能说修改学校。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，后面不能直接带宾语。"}], "explanations": {"援助": "援助：长期帮助山区，与“一直”搭配自然。", "毕业": "配价：“毕业”是不及物动词，不能直接带处所宾语，要说“毕业于”。", "修改": "搭配：“修改”的对象是文章、计划等，不能说修改学校。", "诞生": "配价：“诞生”是不及物动词，后面不能直接带宾语。"}, "sentence_index": 6, "correct_answer": "援助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈援助我整理了房间。", "explanation": "这里应该用〈帮助〉。援助指向有困难的人或地区提供实际支持，整理房间这类日常小事用帮助。"}, {"text": "爷爷援助我买了一台电脑。", "explanation": "这里应该用〈资助〉。援助多用于对群体或地区的帮扶，个人出钱供人买东西要说资助。"}, {"text": "他们援助了那位刚获奖的歌手。", "explanation": "这里应该用〈祝贺〉。援助是给有困难一方的帮助，刚获奖的歌手不需要援助，应说祝贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多志愿者连夜赶去灾区被援助三名伤员。", "corrected_sentence": "很多志愿者连夜赶去灾区援助三名伤员。", "error_description": "错误：主语“志愿者”是去援助别人的一方，不能用“被援助”。应去掉“被”，说“赶去灾区援助三名伤员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不援助过山区的学校。", "corrected_sentence": "他从来没援助过山区的学校。", "error_description": "错误：从来不……过。正确：从来没……过。表示过去从未有过的经历要用“没”，“不”用于习惯或意愿。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
