INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "奉是用手恭敬地把东西送给别人。", "primary_collocate": null, "pronunciation": "fèng", "ipa": "fɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他双手把茶奉给老人。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员双手把热茶奉到桌前。", "target_word": "奉", "complexity_tier": "T3", "furigana": "fú wù yuán shuāng shǒu bǎ rè chá fèng dào zhuō qián", "sentence_source": "generated"}, {"text": "学生恭敬地把书奉给老师。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把水果奉到客人面前。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子双手把自己画的画奉给老师。", "target_word": "奉", "complexity_tier": "T3", "furigana": "hái zi shuāng shǒu bǎ zì jǐ huà de huà fèng gěi lǎo shī", "sentence_source": "generated"}, {"text": "他弯着腰，把礼物奉给奶奶。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我双手把名片奉给他，请他多关照。", "target_word": "奉", "complexity_tier": "T3", "furigana": "wǒ shuāng shǒu bǎ míng piàn fèng gěi tā qǐng tā duō guān zhào", "sentence_source": "generated"}, {"text": "小王把酒奉给了客人。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把新做好的菜奉到了桌上。", "target_word": "奉", "complexity_tier": "T3", "furigana": "chú shī bǎ xīn zuò hǎo de cài fèng dào le zhuō shàng", "sentence_source": "generated"}, {"text": "他恭敬地把一碗饭奉给老人。", "target_word": "奉", "complexity_tier": "T3", "furigana": "tā gōng jìng de bǎ yì wǎn fàn fèng gěi lǎo rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉了", "label": "体标"}, {"form": "奉过", "label": "体标"}, {"form": "奉上", "label": "复合"}], "register": "书面", "sense_fingerprint": "奉：双手恭敬地把东西递给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉（fèng）：双手恭敬地把东西递给别人"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是风"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 fèng 的韵母不同（ang／eng），意思是放置"}, {"text": "份", "is_correct": false, "explanation": "fèn 与 fèng 的韵尾不同（n／ng），意思是一份"}, {"text": "缝", "is_correct": false, "explanation": "féng（第二声）与 fèng（第四声）声调不同，意思是缝补"}], "explanations": {"奉": "正确。奉（fèng）：双手恭敬地把东西递给别人", "风": "fēng（第一声）与 fèng（第四声）声调不同，意思是风", "放": "fàng 与 fèng 的韵母不同（ang／eng），意思是放置", "份": "fèn 与 fèng 的韵尾不同（n／ng），意思是一份", "缝": "féng（第二声）与 fèng（第四声）声调不同，意思是缝补"}, "sentence_index": null, "correct_answer": "奉"}, "level_3": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉与“双手”“恭敬”的递送语境相合"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”含随手丢弃之意，与“双手”恭敬递送的语境相反"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”含用力撞击之意，与“双手”恭敬奉上的语境不合"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的受事是饮用的东西，不能用“喝给老人”表示递送"}], "explanations": {"奉": "正确。奉与“双手”“恭敬”的递送语境相合", "扔": "语义：“扔”含随手丢弃之意，与“双手”恭敬递送的语境相反", "砸": "语义：“砸”含用力撞击之意，与“双手”恭敬奉上的语境不合", "喝": "配价：“喝”的受事是饮用的东西，不能用“喝给老人”表示递送"}, "sentence_index": 0, "correct_answer": "奉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把箱子奉到了仓库。", "explanation": "这里应该用〈搬〉。奉带有恭敬递送的意味，不用于搬运箱子等货物"}, {"text": "他把垃圾奉进了垃圾桶。", "explanation": "这里应该用〈扔〉。奉含恭敬之意，不能用于随手丢弃的东西"}, {"text": "他用脚把球奉给了队友。", "explanation": "这里应该用〈踢〉。奉指双手恭敬地递送，不能用于用脚传球"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91201, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉（fèng）：双手恭敬地把东西递给别人"}, {"text": "逢", "is_correct": false, "explanation": "féng（第二声）与 fèng（第四声）声调不同，意思是遇到"}, {"text": "丰", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是丰富"}, {"text": "讽", "is_correct": false, "explanation": "fěng（第三声）与 fèng（第四声）声调不同，意思是讽刺"}, {"text": "封", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是封闭"}], "explanations": {"奉": "正确。奉（fèng）：双手恭敬地把东西递给别人", "逢": "féng（第二声）与 fèng（第四声）声调不同，意思是遇到", "丰": "fēng（第一声）与 fèng（第四声）声调不同，意思是丰富", "讽": "fěng（第三声）与 fèng（第四声）声调不同，意思是讽刺", "封": "fēng（第一声）与 fèng（第四声）声调不同，意思是封闭"}, "sentence_index": null, "correct_answer": "奉"}, "level_3": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉与“双手”“请他多关照”的恭敬语气相合"}, {"text": "甩", "is_correct": false, "explanation": "语义：“甩”带有随手扔出之意，与“双手”和“请他多关照”的恭敬语气不合"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多用于较重的大件物品，名片太轻，不说“搬给他”"}, {"text": "赔", "is_correct": false, "explanation": "配价：“赔”带的是赔偿的钱或损失，不能表示把名片递给别人"}], "explanations": {"奉": "正确。奉与“双手”“请他多关照”的恭敬语气相合", "甩": "语义：“甩”带有随手扔出之意，与“双手”和“请他多关照”的恭敬语气不合", "搬": "搭配：“搬”多用于较重的大件物品，名片太轻，不说“搬给他”", "赔": "配价：“赔”带的是赔偿的钱或损失，不能表示把名片递给别人"}, "sentence_index": 6, "correct_answer": "奉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把信奉进了邮箱。", "explanation": "这里应该用〈投〉。奉指恭敬地把东西递给人，不能用于把信放进邮箱"}, {"text": "他随手把书奉到桌上。", "explanation": "这里应该用〈放〉。奉带有恭敬的意味，与“随手”的随意动作相矛盾"}, {"text": "他把饭奉给了猫。", "explanation": "这里应该用〈喂〉。奉指恭敬地献上，不能用于给动物喂食，应说“喂”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员双手把菜奉在客人。", "corrected_sentence": "服务员双手把菜奉给客人。", "error_description": "“奉”的接受者要用“给”引出，不能用“在”。应说“奉给客人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他恭敬地把一杯茶给奉客人。", "corrected_sentence": "他恭敬地把一杯茶奉给客人。", "error_description": "“奉”与“给”的顺序颠倒了，应说“奉给”，“给奉”不成话。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
