INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91202, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "恭敬地把心意、成果等献上或给予别人。", "primary_collocate": null, "pronunciation": "fèng", "ipa": "fɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他把自己的真心奉给了她。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿把全部积蓄奉给父母。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把最好的祝福奉给大家。", "target_word": "奉", "complexity_tier": "T3", "furigana": "tā bǎ zuì hǎo de zhù fú fèng gěi dà jiā", "sentence_source": "generated"}, {"text": "我们把这份敬意奉给老师。", "target_word": "奉", "complexity_tier": "T3", "furigana": "wǒ men bǎ zhè fèn jìng yì fèng gěi lǎo shī", "sentence_source": "generated"}, {"text": "请允许我把这份心意奉给您。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一片爱心奉给了孤儿们。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把温暖的笑脸奉给每一位客人。", "target_word": "奉", "complexity_tier": "T3", "furigana": "tā bǎ wēn nuǎn de xiào liǎn fèng gěi měi yí wèi kè rén", "sentence_source": "generated"}, {"text": "书店把新年好书奉给读者。", "target_word": "奉", "complexity_tier": "T3", "furigana": "shū diàn bǎ xīn nián hǎo shū fèng gěi dú zhě", "sentence_source": "generated"}, {"text": "他把荣誉奉给了家乡的人民。", "target_word": "奉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把最真诚的感谢奉给您。", "target_word": "奉", "complexity_tier": "T3", "furigana": "wǒ men bǎ zuì zhēn chéng de gǎn xiè fèng gěi nín", "sentence_source": "generated"}], "morphological_forms": [{"form": "奉了", "label": "体标"}, {"form": "奉过", "label": "体标"}, {"form": "奉上", "label": "复合"}], "register": "书面", "sense_fingerprint": "奉：恭敬地献上或给予心意、成果等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉（fèng）：恭敬地献上或给予心意"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是风"}, {"text": "放", "is_correct": false, "explanation": "fàng 与 fèng 的韵母不同（ang／eng），意思是放置"}, {"text": "份", "is_correct": false, "explanation": "fèn 与 fèng 的韵尾不同（n／ng），意思是一份"}, {"text": "逢", "is_correct": false, "explanation": "féng（第二声）与 fèng（第四声）声调不同，意思是遇到"}], "explanations": {"奉": "正确。奉（fèng）：恭敬地献上或给予心意", "风": "fēng（第一声）与 fèng（第四声）声调不同，意思是风", "放": "fàng 与 fèng 的韵母不同（ang／eng），意思是放置", "份": "fèn 与 fèng 的韵尾不同（n／ng），意思是一份", "逢": "féng（第二声）与 fèng（第四声）声调不同，意思是遇到"}, "sentence_index": null, "correct_answer": "奉"}, "level_3": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉表示恭敬地献上真心，与“真心”的语境相合"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不表示把东西授予他人，不能说“把真心放给了她”"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”含随手丢弃之意，与珍视的“真心”不合"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”含用力掷地之意，与“真心”的情感语境不合"}], "explanations": {"奉": "正确。奉表示恭敬地献上真心，与“真心”的语境相合", "放": "搭配：“放”不表示把东西授予他人，不能说“把真心放给了她”", "扔": "语义：“扔”含随手丢弃之意，与珍视的“真心”不合", "摔": "语义：“摔”含用力掷地之意，与“真心”的情感语境不合"}, "sentence_index": 0, "correct_answer": "奉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这条新闻奉到了网上。", "explanation": "这里应该用〈发〉。奉表示恭敬地献给某人，不能用于把新闻发布到网上"}, {"text": "他把钱奉进了口袋。", "explanation": "这里应该用〈收〉。奉有恭敬献上之意，不能用于把钱装进自己的口袋"}, {"text": "他把损失奉给了朋友。", "explanation": "这里应该用〈推〉。奉表示恭敬地献上，不能用来说把损失转嫁给别人，转嫁损失应说“推给”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91202, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉（fèng）：恭敬地献上或给予心意"}, {"text": "丰", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是丰富"}, {"text": "讽", "is_correct": false, "explanation": "fěng（第三声）与 fèng（第四声）声调不同，意思是讽刺"}, {"text": "封", "is_correct": false, "explanation": "fēng（第一声）与 fèng（第四声）声调不同，意思是封闭"}, {"text": "缝", "is_correct": false, "explanation": "féng（第二声）与 fèng（第四声）声调不同，意思是缝补"}], "explanations": {"奉": "正确。奉（fèng）：恭敬地献上或给予心意", "丰": "fēng（第一声）与 fèng（第四声）声调不同，意思是丰富", "讽": "fěng（第三声）与 fèng（第四声）声调不同，意思是讽刺", "封": "fēng（第一声）与 fèng（第四声）声调不同，意思是封闭", "缝": "féng（第二声）与 fèng（第四声）声调不同，意思是缝补"}, "sentence_index": null, "correct_answer": "奉"}, "level_3": {"options": [{"text": "奉", "is_correct": true, "explanation": "正确。奉表示恭敬地献上，与“温暖的笑脸”和“每一位客人”相合"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”多用于挂在某处，不说“把笑脸挂给客人”"}, {"text": "甩", "is_correct": false, "explanation": "语义：“甩”含随意抛出之意，与“温暖的笑脸”不合"}, {"text": "收", "is_correct": false, "explanation": "配价：“收”表示接收或收取，不能带“笑脸”作受事而表示赠予"}], "explanations": {"奉": "正确。奉表示恭敬地献上，与“温暖的笑脸”和“每一位客人”相合", "挂": "搭配：“挂”多用于挂在某处，不说“把笑脸挂给客人”", "甩": "语义：“甩”含随意抛出之意，与“温暖的笑脸”不合", "收": "配价：“收”表示接收或收取，不能带“笑脸”作受事而表示赠予"}, "sentence_index": 6, "correct_answer": "奉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把积木奉到了地上。", "explanation": "这里应该用〈扔〉。奉带有恭敬之意，不能用于随手扔在地上"}, {"text": "他把脏水奉到了门外。", "explanation": "这里应该用〈泼〉。奉带有恭敬献上的色彩，不能用于把脏水泼出去"}, {"text": "我们把垃圾奉进了桶里。", "explanation": "这里应该用〈丢〉。奉含恭敬之意，不能用于把垃圾丢进桶里"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =