INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌手是会唱歌，站在台上给大家唱的人。", "primary_collocate": null, "pronunciation": "gē shǒu", "ipa": "kɤ˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是一位很有名的歌手。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个歌手站在台上唱歌。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的歌手来我们城市了。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手的声音很好听。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的歌手微笑着向观众挥手。", "target_word": "歌手", "complexity_tier": "T3", "furigana": "wǔ tái shàng de gē shǒu wēi xiào zhe xiàng guān zhòng huī shǒu", "sentence_source": "generated"}, {"text": "台上的歌手唱了一首老歌。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手一上台，大家就鼓掌了。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出结束后，歌手走下舞台。", "target_word": "歌手", "complexity_tier": "T3", "furigana": "yǎn chū jié shù hòu gē shǒu zǒu xià wǔ tái", "sentence_source": "generated"}, {"text": "这个歌手唱歌的时候总是笑着。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上有三个歌手要唱歌。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "女歌手", "label": "复合"}, {"form": "男歌手", "label": "复合"}], "register": "中性", "sense_fingerprint": "会唱歌、在台上唱给大家听的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91203, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手 gē shǒu：会唱歌、站在台上给大家唱的人，与所听到的读音一致。"}, {"text": "高手", "is_correct": false, "explanation": "高手 gāo shǒu：第一音节韵母不同（gāo 与 gē），意思是技术高明的人。"}, {"text": "车手", "is_correct": false, "explanation": "车手 chē shǒu：第一音节声母不同（chē 与 gē），意思是赛车或骑车比赛的选手。"}, {"text": "得手", "is_correct": false, "explanation": "得手 dé shǒu：第一音节声母不同（dé 与 gē），意思是成功地到手。"}, {"text": "国手", "is_correct": false, "explanation": "国手 guó shǒu：第一音节韵母不同（guó 与 gē），意思是技艺在全国一流的高手。"}], "explanations": {"歌手": "歌手 gē shǒu：会唱歌、站在台上给大家唱的人，与所听到的读音一致。", "高手": "高手 gāo shǒu：第一音节韵母不同（gāo 与 gē），意思是技术高明的人。", "车手": "车手 chē shǒu：第一音节声母不同（chē 与 gē），意思是赛车或骑车比赛的选手。", "得手": "得手 dé shǒu：第一音节声母不同（dé 与 gē），意思是成功地到手。", "国手": "国手 guó shǒu：第一音节韵母不同（guó 与 gē），意思是技艺在全国一流的高手。"}, "sentence_index": null, "correct_answer": "歌手"}, "level_3": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手是会唱歌的人，可以说“一位很有名的歌手”。"}, {"text": "火", "is_correct": false, "explanation": "语义：火是燃烧时发出光和热的东西，不指人，不能说“他是一位很有名的火”。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位椅子”。"}, {"text": "作品", "is_correct": false, "explanation": "语义：作品是创作出的成果，不指人，“他是……作品”不合逻辑。"}], "explanations": {"歌手": "歌手是会唱歌的人，可以说“一位很有名的歌手”。", "火": "语义：火是燃烧时发出光和热的东西，不指人，不能说“他是一位很有名的火”。", "椅子": "搭配：量词“位”只用于人，不能说“一位椅子”。", "作品": "语义：作品是创作出的成果，不指人，“他是……作品”不合逻辑。"}, "sentence_index": 0, "correct_answer": "歌手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的歌手很押韵，念起来很顺口。", "explanation": "这里应该用〈歌词〉。押韵、读起来顺口的是歌词，歌手指唱歌的人，不能用来形容押韵。"}, {"text": "他写了一首很好听的歌手。", "explanation": "这里应该用〈歌曲〉。“写”的对象是歌曲等作品，歌手指唱歌的人，不是作品。"}, {"text": "那场歌手很精彩，观众都站起来了。", "explanation": "这里应该用〈演出〉。“场”和“精彩”说的是演出，歌手指人，不能说“一场歌手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手是站在台上唱歌的人，能“一上台”，大家就会鼓掌。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不会上台，也不会让大家鼓掌。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理事物，不能“上台”表演。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“上台”指人登上舞台，不说“桌子一上台”。"}], "explanations": {"歌手": "歌手是站在台上唱歌的人，能“一上台”，大家就会鼓掌。", "月亮": "语义：月亮是天体，不会上台，也不会让大家鼓掌。", "河流": "语义：河流是地理事物，不能“上台”表演。", "桌子": "搭配：“上台”指人登上舞台，不说“桌子一上台”。"}, "sentence_index": 6, "correct_answer": "歌手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会上有三台歌手要唱歌。", "explanation": "这里应该用〈位〉或〈个〉。“台”用于机器、设备，不用于指人的歌手。"}, {"text": "晚会上有三张歌手要唱歌。", "explanation": "这里应该用〈位〉或〈个〉。“张”用于纸、桌子等平面的东西，不用于指人的歌手。"}, {"text": "晚会上有三辆歌手要唱歌。", "explanation": "这里应该用〈位〉或〈个〉。“辆”用于车，不用于指人的歌手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一只很会唱歌的歌手。", "corrected_sentence": "我认识一位很会唱歌的歌手。", "error_description": "量词用错：“歌手”指人，应该用“位”或“个”，不能用“只”（“只”多用于动物或小件物品）。正确说法是“一位很会唱歌的歌手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位很有名歌手今天来了。", "corrected_sentence": "那位很有名的歌手今天来了。", "error_description": "定语用错：“很有名”修饰“歌手”时中间要加“的”，应说“很有名的歌手”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
