INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以唱歌为职业的人。", "primary_collocate": null, "pronunciation": "gē shǒu", "ipa": "kɤ˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是一名职业歌手。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做歌手已经十年了。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手靠唱歌赚钱。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从公司辞职，成了歌手。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手的工作常常很累。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是歌手，妈妈是老师。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的歌手每天都练习唱歌。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手每年都开音乐会。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当歌手，所以去上音乐学校。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司在找新歌手。", "target_word": "歌手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女歌手", "label": "复合"}, {"form": "男歌手", "label": "复合"}], "register": "中性", "sense_fingerprint": "靠唱歌工作、赚钱的职业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91204, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手 gē shǒu：以唱歌为职业的人，与所听到的读音一致。"}, {"text": "高手", "is_correct": false, "explanation": "高手 gāo shǒu：第一音节韵母不同（gāo 与 gē），意思是技术高明的人。"}, {"text": "车手", "is_correct": false, "explanation": "车手 chē shǒu：第一音节声母不同（chē 与 gē），意思是赛车或骑车比赛的选手。"}, {"text": "得手", "is_correct": false, "explanation": "得手 dé shǒu：第一音节声母不同（dé 与 gē），意思是成功地到手。"}, {"text": "国手", "is_correct": false, "explanation": "国手 guó shǒu：第一音节韵母不同（guó 与 gē），意思是技艺在全国一流的高手。"}], "explanations": {"歌手": "歌手 gē shǒu：以唱歌为职业的人，与所听到的读音一致。", "高手": "高手 gāo shǒu：第一音节韵母不同（gāo 与 gē），意思是技术高明的人。", "车手": "车手 chē shǒu：第一音节声母不同（chē 与 gē），意思是赛车或骑车比赛的选手。", "得手": "得手 dé shǒu：第一音节声母不同（dé 与 gē），意思是成功地到手。", "国手": "国手 guó shǒu：第一音节韵母不同（guó 与 gē），意思是技艺在全国一流的高手。"}, "sentence_index": null, "correct_answer": "歌手"}, "level_3": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手指以唱歌为职业的人，可以说“她是一名职业歌手”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是人，不能说“她是一名职业月亮”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“名”只用于人，不能说“一名桌子”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理事物，不指人，不能作为职业身份。"}], "explanations": {"歌手": "歌手指以唱歌为职业的人，可以说“她是一名职业歌手”。", "月亮": "语义：月亮是天体，不是人，不能说“她是一名职业月亮”。", "桌子": "搭配：量词“名”只用于人，不能说“一名桌子”。", "河流": "语义：河流是地理事物，不指人，不能作为职业身份。"}, "sentence_index": 0, "correct_answer": "歌手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她写的歌手很押韵，念起来很顺口。", "explanation": "这里应该用〈歌词〉。押韵、读起来顺口的是歌词，歌手指唱歌的人，不能用来形容押韵。"}, {"text": "她写了一首很好听的歌手。", "explanation": "这里应该用〈歌曲〉。“写”的对象是歌曲等作品，歌手不是作品。"}, {"text": "她是一只职业歌手。", "explanation": "这里应该用〈名〉或〈位〉。“只”多用于动物或小件物品，不用于指人的歌手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌手", "is_correct": true, "explanation": "歌手是会唱歌的人，年轻的歌手可以“每天都练习唱歌”。"}, {"text": "火", "is_correct": false, "explanation": "语义：火不是人，不会练习唱歌。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：“练习唱歌”的主语必须能唱歌，作品不能练习唱歌。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不会练习唱歌。"}], "explanations": {"歌手": "歌手是会唱歌的人，年轻的歌手可以“每天都练习唱歌”。", "火": "语义：火不是人，不会练习唱歌。", "作品": "搭配：“练习唱歌”的主语必须能唱歌，作品不能练习唱歌。", "石头": "语义：石头不是人，不会练习唱歌。"}, "sentence_index": 6, "correct_answer": "歌手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那场歌手很热闹，门口排起了长队。", "explanation": "这里应该用〈演唱会〉。“场”、“热闹”和“排长队”说的是演唱会，歌手指人，不能说“一场歌手”。"}, {"text": "那场歌手很动人，大家都在鼓掌。", "explanation": "这里应该用〈演出〉。“场”和“动人”说的是演出，歌手指人，不能用来指一场演出。"}, {"text": "那座新歌手是公司的宝贝。", "explanation": "这里应该用〈位〉或〈个〉。“座”用于山、房子等大型固定的东西，不用于指人的歌手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐是一只职业歌手。", "corrected_sentence": "我姐姐是一名职业歌手。", "error_description": "量词用错：“歌手”指人，应该用“名”或“位”，不能用“只”。正确说法是“一名职业歌手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位刚出道歌手昨天来了。", "corrected_sentence": "那位刚出道的歌手昨天来了。", "error_description": "定语用错：“刚出道”修饰“歌手”时中间要加“的”，应说“刚出道的歌手”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
