INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91205, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火是又红又热的东西，能点亮黑夜，也会烫人。", "primary_collocate": null, "pronunciation": "huǒ", "ipa": "xuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "火是红的，也很热。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们在山上点了一堆火。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，火会烫手。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜里，那堆火很亮。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不能玩火。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火的颜色是红的。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们围着火唱歌。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火旁边很暖和。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手碰到了火，很疼。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里很黑，只有一团火在亮。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "团", "label": "量词"}], "register": "中性", "sense_fingerprint": "又红又热、能照亮黑夜、会烫人的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91205, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火", "is_correct": true, "explanation": "火 huǒ：又红又热、能照亮黑夜、会烫人的东西。"}, {"text": "货", "is_correct": false, "explanation": "货 huò：声调不同（huò 为第四声，huǒ 为第三声），意思是商品。"}, {"text": "活", "is_correct": false, "explanation": "活 huó：声调不同（huó 为第二声，huǒ 为第三声），意思是活着、有生命。"}, {"text": "虎", "is_correct": false, "explanation": "虎 hǔ：韵母不同（hǔ 没有 o 音），意思是老虎。"}], "explanations": {"火": "火 huǒ：又红又热、能照亮黑夜、会烫人的东西。", "货": "货 huò：声调不同（huò 为第四声，huǒ 为第三声），意思是商品。", "活": "活 huó：声调不同（huó 为第二声，huǒ 为第三声），意思是活着、有生命。", "虎": "虎 hǔ：韵母不同（hǔ 没有 o 音），意思是老虎。"}, "sentence_index": null, "correct_answer": "火"}, "level_3": {"options": [{"text": "火", "is_correct": true, "explanation": "火是红的，也很热，符合“是红的，也很热”的描述。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是冷的，与“也很热”矛盾。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白的、冷的，不是红的，也不热。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐是白色的晶体，不是红的。"}], "explanations": {"火": "火是红的，也很热，符合“是红的，也很热”的描述。", "冰": "语义：冰是冷的，与“也很热”矛盾。", "雪": "语义：雪是白的、冷的，不是红的，也不热。", "盐": "语义：盐是白色的晶体，不是红的。"}, "sentence_index": 0, "correct_answer": "火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山上捡了一堆火，准备做饭。", "explanation": "这里应该用〈柴〉。火是燃烧时发出的光和热，不能“捡”，捡的是柴。"}, {"text": "我们围着那本火取暖，很暖和。", "explanation": "这里应该用〈堆〉或〈团〉。“本”用于书本一类的东西，火不能用“本”。"}, {"text": "夜里我们在帐篷外看着那幅火。", "explanation": "这里应该用〈堆〉或〈团〉。“幅”用于画、布等平面的东西，火不能用“幅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火", "is_correct": true, "explanation": "火可以被人围着，“我们围着火唱歌”说的是围绕篝火唱歌。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“围着……唱歌”的对象要能被围住，说“围着雨唱歌”不搭配。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在天上，不能被人围着唱歌。"}, {"text": "雷", "is_correct": false, "explanation": "语义：雷是自然现象，不能被人围着唱歌。"}], "explanations": {"火": "火可以被人围着，“我们围着火唱歌”说的是围绕篝火唱歌。", "雨": "搭配：“围着……唱歌”的对象要能被围住，说“围着雨唱歌”不搭配。", "云": "语义：云在天上，不能被人围着唱歌。", "雷": "语义：雷是自然现象，不能被人围着唱歌。"}, "sentence_index": 6, "correct_answer": "火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山里很黑，只有一只火在亮。", "explanation": "这里应该用〈团〉。“只”用于动物或小件物品，火不能用“只”。"}, {"text": "山里很黑，只有一张火在亮。", "explanation": "这里应该用〈团〉。“张”用于纸、桌子等平面的东西，火不能用“张”。"}, {"text": "山里很黑，只有一位火在亮。", "explanation": "这里应该用〈团〉。“位”只用于人，火不能用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在河边生了一只火。", "corrected_sentence": "孩子们在河边生了一堆火。", "error_description": "量词用错：“火”前应该用“堆”或“团”，不能用“只”（“只”多用于动物或小件物品）。正确说法是“一堆火”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都坐在火们旁边。", "corrected_sentence": "大家都坐在火旁边。", "error_description": "复数用错：“火”是无生命的东西，不能加“们”表示复数，应说“大家都坐在火旁边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
