INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体燃烧时发出的光和热。", "primary_collocate": null, "pronunciation": "huǒ", "ipa": "xuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "木头烧起来，就有了火。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子里的火越来越大。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，火更大了。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用水把火浇灭了。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火烧了一整夜。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里的火很快就灭了。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸一碰到火就烧起来了。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火会发出光和热。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员很快把火扑灭了。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火让冷冷的屋子热起来。", "target_word": "火", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "团", "label": "量词"}], "register": "中性", "sense_fingerprint": "东西燃烧时发出的光和热", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "火", "is_correct": true, "explanation": "火 huǒ：物体燃烧时发出的光和热。"}, {"text": "货", "is_correct": false, "explanation": "货 huò：声调不同（huò 为第四声，huǒ 为第三声），意思是商品。"}, {"text": "活", "is_correct": false, "explanation": "活 huó：声调不同（huó 为第二声，huǒ 为第三声），意思是活着、有生命。"}, {"text": "虎", "is_correct": false, "explanation": "虎 hǔ：韵母不同（hǔ 没有 o 音），意思是老虎。"}], "explanations": {"火": "火 huǒ：物体燃烧时发出的光和热。", "货": "货 huò：声调不同（huò 为第四声，huǒ 为第三声），意思是商品。", "活": "活 huó：声调不同（huó 为第二声，huǒ 为第三声），意思是活着、有生命。", "虎": "虎 hǔ：韵母不同（hǔ 没有 o 音），意思是老虎。"}, "sentence_index": null, "correct_answer": "火"}, "level_3": {"options": [{"text": "火", "is_correct": true, "explanation": "木头烧起来，燃烧时发出的光和热就是火，符合“就有了火”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是燃烧的产物，木头烧起来不会变成石头。"}, {"text": "冰", "is_correct": false, "explanation": "语义：燃烧会发热，木头烧起来不会变成冰。"}, {"text": "雪", "is_correct": false, "explanation": "搭配：“烧起来”的结果不能是雪，两者搭配不当。"}], "explanations": {"火": "木头烧起来，燃烧时发出的光和热就是火，符合“就有了火”。", "石头": "语义：石头不是燃烧的产物，木头烧起来不会变成石头。", "冰": "语义：燃烧会发热，木头烧起来不会变成冰。", "雪": "搭配：“烧起来”的结果不能是雪，两者搭配不当。"}, "sentence_index": 0, "correct_answer": "火"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子里烧着一首火，暖和极了。", "explanation": "这里应该用〈堆〉或〈团〉。“首”用于诗歌、歌曲，火不能用“首”。"}, {"text": "我们在院子里点起一面火，大家围过来。", "explanation": "这里应该用〈堆〉或〈团〉。“面”用于旗子、镜子等平面的东西，火不能用“面”。"}, {"text": "冬天的屋子里，烧着一幅火。", "explanation": "这里应该用〈堆〉或〈团〉。“幅”用于画、布等平面的东西，火不能用“幅”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火", "is_correct": true, "explanation": "火能让纸烧起来，“纸一碰到火就烧起来了”符合常识。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能燃烧，碰到石头不会烧起来。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能燃烧，“碰到玻璃就烧起来”不合逻辑。"}, {"text": "盐", "is_correct": false, "explanation": "搭配：“烧起来”要求能燃烧的东西，盐不能燃烧，不说“碰到盐就烧起来”。"}], "explanations": {"火": "火能让纸烧起来，“纸一碰到火就烧起来了”符合常识。", "石头": "语义：石头不能燃烧，碰到石头不会烧起来。", "玻璃": "语义：玻璃不能燃烧，“碰到玻璃就烧起来”不合逻辑。", "盐": "搭配：“烧起来”要求能燃烧的东西，盐不能燃烧，不说“碰到盐就烧起来”。"}, "sentence_index": 6, "correct_answer": "火"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一只火让冷冷的屋子热起来。", "explanation": "这里应该用〈团〉或〈堆〉。“只”用于动物或小件物品，火不能用“只”。"}, {"text": "一张火让冷冷的屋子热起来。", "explanation": "这里应该用〈团〉或〈堆〉。“张”用于纸、桌子等平面的东西，火不能用“张”。"}, {"text": "一位火让冷冷的屋子热起来。", "explanation": "这里应该用〈团〉或〈堆〉。“位”只用于人，火不能用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "房子里烧起了很大火。", "corrected_sentence": "房子里烧起了很大的火。", "error_description": "定语用错：“很大”修饰“火”时要加“的”，应说“很大的火”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堆火们很快就烧完了。", "corrected_sentence": "这堆火很快就烧完了。", "error_description": "复数用错：“火”是无生命的东西，不能加“们”表示复数，应说“这堆火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
