INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神话传说中的妖怪。", "primary_collocate": null, "pronunciation": "yāo", "ipa": "jɑʊ˥", "syllable_count": 1, "sentences": [{"text": "孙悟空打败了那个妖。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说山上有一个妖。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的妖都很厉害。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲了一个妖的故事。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个妖想吃唐僧。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个妖住在很深的山洞里。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都怕山上的妖。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英雄杀死了河里的妖。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话中的妖有时候很可怕。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把妖赶走了。", "target_word": "妖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "神话传说中的妖怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2159400-947f-4fbc-9ddc-227cd6535575') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妖", "is_correct": true, "explanation": "正确：妖（第一声）指神话传说中的妖怪。"}, {"text": "咬", "is_correct": false, "explanation": "「yǎo（第三声）与 yāo（第一声）声调不同，意思是“咬”」。"}, {"text": "摇", "is_correct": false, "explanation": "「yáo（第二声）与 yāo（第一声）声调不同，意思是“摇动”」。"}, {"text": "药", "is_correct": false, "explanation": "「yào（第四声）与 yāo（第一声）声调不同，意思是“药物”」。"}, {"text": "优", "is_correct": false, "explanation": "「yōu 与 yāo 韵母不同（ou 与 ao），意思是“优秀”」。"}], "explanations": {"妖": "正确：妖（第一声）指神话传说中的妖怪。", "咬": "「yǎo（第三声）与 yāo（第一声）声调不同，意思是“咬”」。", "摇": "「yáo（第二声）与 yāo（第一声）声调不同，意思是“摇动”」。", "药": "「yào（第四声）与 yāo（第一声）声调不同，意思是“药物”」。", "优": "「yōu 与 yāo 韵母不同（ou 与 ao），意思是“优秀”」。"}, "sentence_index": null, "correct_answer": "妖"}, "level_3": {"options": [{"text": "妖", "is_correct": true, "explanation": "正确：“妖”是神话传说中的妖怪，可以作“打败了”的宾语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被打败的对象，句子说的是妖怪。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能被当作敌人打败，句子说的是神话中的妖怪。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“打败”的对象须是可以对抗的人或怪物，“作业”不能作“打败”的宾语。"}], "explanations": {"妖": "正确：“妖”是神话传说中的妖怪，可以作“打败了”的宾语。", "天气": "语义：天气不是可以被打败的对象，句子说的是妖怪。", "河流": "语义：河流不能被当作敌人打败，句子说的是神话中的妖怪。", "作业": "搭配：“打败”的对象须是可以对抗的人或怪物，“作业”不能作“打败”的宾语。"}, "sentence_index": 0, "correct_answer": "妖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人去超市买了一个妖。", "explanation": "这里应该用〈西红柿〉。妖是神话中的怪物，不能在超市购买。"}, {"text": "妈妈烤了一个妖。", "explanation": "这里应该用〈面包〉。妖是神话中的怪物，不能被烤来吃。"}, {"text": "我每天骑妖去上学。", "explanation": "这里应该用〈自行车〉。妖是神话中的怪物，不是交通工具，不能骑着去上学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91208, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "妖", "is_correct": true, "explanation": "正确：妖（第一声）指神话传说中的妖怪。"}, {"text": "遥", "is_correct": false, "explanation": "「yáo（第二声）与 yāo（第一声）声调不同，意思是“遥远”」。"}, {"text": "耀", "is_correct": false, "explanation": "「yào（第四声）与 yāo（第一声）声调不同，意思是“耀眼”」。"}, {"text": "忧", "is_correct": false, "explanation": "「yōu 与 yāo 韵母不同（ou 与 ao），意思是“忧愁”」。"}], "explanations": {"妖": "正确：妖（第一声）指神话传说中的妖怪。", "遥": "「yáo（第二声）与 yāo（第一声）声调不同，意思是“遥远”」。", "耀": "「yào（第四声）与 yāo（第一声）声调不同，意思是“耀眼”」。", "忧": "「yōu 与 yāo 韵母不同（ou 与 ao），意思是“忧愁”」。"}, "sentence_index": null, "correct_answer": "妖"}, "level_3": {"options": [{"text": "妖", "is_correct": true, "explanation": "正确：“妖”是神话中会让村民害怕的妖怪，可以作“怕”的宾语。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会让人害怕，句子说的是危险的妖怪。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会让村民害怕，句子说的是山上的威胁。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“怕”的对象须是有威胁的人或事物，“面包”不能让人害怕。"}], "explanations": {"妖": "正确：“妖”是神话中会让村民害怕的妖怪，可以作“怕”的宾语。", "书包": "语义：书包不会让人害怕，句子说的是危险的妖怪。", "作业": "语义：作业不会让村民害怕，句子说的是山上的威胁。", "面包": "搭配：“怕”的对象须是有威胁的人或事物，“面包”不能让人害怕。"}, "sentence_index": 6, "correct_answer": "妖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用妖做了一顿午饭。", "explanation": "这里应该用〈面条〉。妖是神话中的怪物，不能当作食材。"}, {"text": "他用妖拍了一张照片。", "explanation": "这里应该用〈手机〉。妖不能当作拍照的工具。"}, {"text": "他用妖降温。", "explanation": "这里应该用〈空调〉。妖是怪物，不能用来降温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猴子在山洞里找到了那本妖。", "corrected_sentence": "猴子在山洞里找到了那个妖。", "error_description": "错误形式“那本妖”，正确形式“那个妖”。“本”只用于书籍，妖的量词是“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勇士终于把那张妖杀死了。", "corrected_sentence": "勇士终于把那个妖杀死了。", "error_description": "错误形式“那张妖”，正确形式“那个妖”。“张”用于纸、桌子等平面物体，妖的量词是“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c050dcb-c5ed-4eac-8a6a-4fc0d74d09fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
