INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "界是两块地方中间分开的线。", "primary_collocate": "为", "pronunciation": "jiè", "ipa": "tɕjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "两个村子以这条河为界。", "target_word": "界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家以这座山为界。", "target_word": "界", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家和邻居家以那棵树为界。", "target_word": "界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇的东边和西边以这座桥为界。", "target_word": "界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个城市以这条路为界。", "target_word": "界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们以这条线为界，你在左边，我在右边。", "target_word": "界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上以这条红线为界，分出两个省。", "target_word": "界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和公园以一堵墙为界。", "target_word": "界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，以黑板为界，左边是我们的。", "target_word": "界", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两家的地以一条小沟为界。", "target_word": "界", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "界线", "label": "复合"}, {"form": "边界", "label": "复合"}], "register": "中性", "sense_fingerprint": "界：分开两块地方的线，常用于“以……为界”", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91209, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "界", "is_correct": true, "explanation": "界（jiè）：分开两块地方的线。"}, {"text": "解", "is_correct": false, "explanation": "声调：解（jiě）与界（jiè）声调不同（第三声与第四声），意思是解开。"}, {"text": "街", "is_correct": false, "explanation": "声调：街（jiē）与界（jiè）声调不同（第一声与第四声），意思是街道。"}, {"text": "节", "is_correct": false, "explanation": "声调：节（jié）与界（jiè）声调不同（第二声与第四声），意思是节日或段落。"}, {"text": "姐", "is_correct": false, "explanation": "声调：姐（jiě）与界（jiè）声调不同（第三声与第四声），意思是姐姐。"}], "explanations": {"界": "界（jiè）：分开两块地方的线。", "解": "声调：解（jiě）与界（jiè）声调不同（第三声与第四声），意思是解开。", "街": "声调：街（jiē）与界（jiè）声调不同（第一声与第四声），意思是街道。", "节": "声调：节（jié）与界（jiè）声调不同（第二声与第四声），意思是节日或段落。", "姐": "声调：姐（jiě）与界（jiè）声调不同（第三声与第四声），意思是姐姐。"}, "sentence_index": null, "correct_answer": "界"}, "level_3": {"options": [{"text": "界", "is_correct": true, "explanation": "界：“以……为界”的固定说法，表示以河为分界。"}, {"text": "线", "is_correct": false, "explanation": "搭配：“以……为界”是固定格式，不能说“为线”。"}, {"text": "路", "is_correct": false, "explanation": "语义：以河为路不合常理，与两个村子以河分界的语境不符。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是连接两岸的建筑，不能用来划分两个村子，以河为桥说不通。"}], "explanations": {"界": "界：“以……为界”的固定说法，表示以河为分界。", "线": "搭配：“以……为界”是固定格式，不能说“为线”。", "路": "语义：以河为路不合常理，与两个村子以河分界的语境不符。", "桥": "语义：桥是连接两岸的建筑，不能用来划分两个村子，以河为桥说不通。"}, "sentence_index": 0, "correct_answer": "界"}, "level_6": {"correct_sentence_index": 2, "wrong_sentences": [{"text": "我们要把这块地界清楚。", "explanation": "这里应该用〈界定〉。“界”单用作动词时不表示“划定”，划定范围要说界定。"}, {"text": "两个村子之间有一条界。", "explanation": "这里应该用〈界线〉。“界”单用时一般不和“条”组合，计量两村之间的分界要说界线。"}, {"text": "这条河把两个村子界开了。", "explanation": "这里应该用〈隔〉。“界”是名词，不能作动词带“开”，把两地分开要说隔开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91209, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "界", "is_correct": true, "explanation": "界（jiè）：分开两块地方的线。"}, {"text": "结", "is_correct": false, "explanation": "声调：结（jié）与界（jiè）声调不同（第二声与第四声），意思是打结或结束。"}, {"text": "接", "is_correct": false, "explanation": "声调：接（jiē）与界（jiè）声调不同（第一声与第四声），意思是接受或接近。"}, {"text": "洁", "is_correct": false, "explanation": "声调：洁（jié）与界（jiè）声调不同（第二声与第四声），意思是干净。"}], "explanations": {"界": "界（jiè）：分开两块地方的线。", "结": "声调：结（jié）与界（jiè）声调不同（第二声与第四声），意思是打结或结束。", "接": "声调：接（jiē）与界（jiè）声调不同（第一声与第四声），意思是接受或接近。", "洁": "声调：洁（jié）与界（jiè）声调不同（第二声与第四声），意思是干净。"}, "sentence_index": null, "correct_answer": "界"}, "level_3": {"options": [{"text": "界", "is_correct": true, "explanation": "界：“以……为界”的固定说法，与“分出两个省”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“以……为界”的对象应是分界的线或地点，颜色不能作界。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与划分省界无关，与“地图上分出两个省”的语境不符。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：节奏与划分地域无关，不能用来分出两个省。"}], "explanations": {"界": "界：“以……为界”的固定说法，与“分出两个省”的语境相合。", "颜色": "搭配：“以……为界”的对象应是分界的线或地点，颜色不能作界。", "温度": "语义：温度与划分省界无关，与“地图上分出两个省”的语境不符。", "节奏": "语义：节奏与划分地域无关，不能用来分出两个省。"}, "sentence_index": 6, "correct_answer": "界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在两块地中间界了一道墙。", "explanation": "这里应该用〈砌〉。“界”是名词，不能作动词带宾语，建墙要说砌墙。"}, {"text": "田边有一根界，把两块地分开。", "explanation": "这里应该用〈界线〉。“界”单用时不与量词“根”组合，分开两块地的线要说“一道界线”。"}, {"text": "这台电脑的界很漂亮。", "explanation": "这里应该用〈界面〉。“界”单用时不指屏幕上供人操作和观看的部分，这一含义要说界面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家的院子以那道矮墙是界。", "corrected_sentence": "两家的院子以那道矮墙为界。", "error_description": "错误：是界。正确：为界。“以……为界”是固定格式，“为”不能换成“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个小区以一条马路界。", "corrected_sentence": "这两个小区以一条马路为界。", "error_description": "错误：以一条马路界。正确：以一条马路为界。“以……为界”是固定格式，“为”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
