INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91215, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "答应是别人请你做事，你说好。", "primary_collocate": null, "pronunciation": "dā ying", "ipa": "tɑ˥ iŋ", "syllable_count": 2, "sentences": [{"text": "妈妈答应明天带我去公园。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我帮忙，我马上答应了。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板答应给我加工资。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应过我，下个月还钱。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我答应了女儿，周末陪她玩。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不答应我一个人去旅行。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她答应帮我照看小狗。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经答应老师，明天早点来。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的条件，我不能答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生答应今天让他出院。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "答应了", "label": "完成体"}, {"form": "答应过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "别人请求时说好，答应去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91215, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答应", "is_correct": true, "explanation": "答应 dā ying：表示应允别人的请求，即别人请你做事时说好。"}, {"text": "打赢", "is_correct": false, "explanation": "dǎ yíng 与 dā ying 声调不同（第三声、第二声与第一声、轻声），意思是战胜。"}, {"text": "大营", "is_correct": false, "explanation": "dà yíng 与 dā ying 声调不同（第四声、第二声与第一声、轻声），意思是军营。"}, {"text": "答疑", "is_correct": false, "explanation": "dá yí 与 dā ying 声调不同（第二声、第二声与第一声、轻声），第二音节韵母也不同（i 与 ing），意思是解答疑问。"}], "explanations": {"答应": "答应 dā ying：表示应允别人的请求，即别人请你做事时说好。", "打赢": "dǎ yíng 与 dā ying 声调不同（第三声、第二声与第一声、轻声），意思是战胜。", "大营": "dà yíng 与 dā ying 声调不同（第四声、第二声与第一声、轻声），意思是军营。", "答疑": "dá yí 与 dā ying 声调不同（第二声、第二声与第一声、轻声），第二音节韵母也不同（i 与 ing），意思是解答疑问。"}, "sentence_index": null, "correct_answer": "答应"}, "level_3": {"options": [{"text": "答应", "is_correct": true, "explanation": "正确：“妈妈答应明天带我去公园”表示妈妈同意带我去，符合应允的义项。"}, {"text": "解释", "is_correct": false, "explanation": "搭配：“解释”的对象是道理或意思，不能带“带我去公园”这样的动作。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误并加以责备，与“明天带我去公园”这样的安排相矛盾。"}, {"text": "整理", "is_correct": false, "explanation": "搭配：“整理”的对象是物品或房间，不能接“带我去公园”这样的动作。"}], "explanations": {"答应": "正确：“妈妈答应明天带我去公园”表示妈妈同意带我去，符合应允的义项。", "解释": "搭配：“解释”的对象是道理或意思，不能带“带我去公园”这样的动作。", "批评": "语义：“批评”是指出错误并加以责备，与“明天带我去公园”这样的安排相矛盾。", "整理": "搭配：“整理”的对象是物品或房间，不能接“带我去公园”这样的动作。"}, "sentence_index": 0, "correct_answer": "答应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他诚恳地道歉，我答应了他的道歉。", "explanation": "这里应该用〈接受〉。答应用于答应别人的请求，接受对方的道歉要说接受。"}, {"text": "老师表扬了我，我高兴地答应了老师的表扬。", "explanation": "这里应该用〈接受〉。答应用于应下别人的请求去做事，接受别人的表扬要说接受。"}, {"text": "他很快答应了这些麻烦。", "explanation": "这里应该用〈应付〉。答应指应下别人的请求去做事，处理麻烦要说应付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91215, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "答应", "is_correct": true, "explanation": "答应 dā ying：表示应允别人的请求，即同意去做。"}, {"text": "扎营", "is_correct": false, "explanation": "zhā yíng 与 dā ying 声母不同（zh 与 d），第二音节声调也不同，意思是安营扎寨。"}, {"text": "大英", "is_correct": false, "explanation": "dà yīng 与 dā ying 声调不同（第四声、第一声与第一声、轻声），意思是英国。"}, {"text": "打印", "is_correct": false, "explanation": "dǎ yìn 与 dā ying 声调不同（第三声、第四声与第一声、轻声），第二音节韵母也不同（in 与 ing），意思是用打印机印出。"}], "explanations": {"答应": "答应 dā ying：表示应允别人的请求，即同意去做。", "扎营": "zhā yíng 与 dā ying 声母不同（zh 与 d），第二音节声调也不同，意思是安营扎寨。", "大英": "dà yīng 与 dā ying 声调不同（第四声、第一声与第一声、轻声），意思是英国。", "打印": "dǎ yìn 与 dā ying 声调不同（第三声、第四声与第一声、轻声），第二音节韵母也不同（in 与 ing），意思是用打印机印出。"}, "sentence_index": null, "correct_answer": "答应"}, "level_3": {"options": [{"text": "答应", "is_correct": true, "explanation": "正确：“她答应帮我照看小狗”表示她同意帮忙，符合应允的义项。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽的感情，与“帮我照看小狗”的善意相反，句意不通。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”后要带被劝的人，“劝帮我照看小狗”缺少对象，句子不完整。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能与“帮我照看小狗”搭配。"}], "explanations": {"答应": "正确：“她答应帮我照看小狗”表示她同意帮忙，符合应允的义项。", "嘲笑": "语义：“嘲笑”带有讥讽的感情，与“帮我照看小狗”的善意相反，句意不通。", "劝": "配价：“劝”后要带被劝的人，“劝帮我照看小狗”缺少对象，句子不完整。", "修理": "搭配：“修理”的对象是器物，不能与“帮我照看小狗”搭配。"}, "sentence_index": 6, "correct_answer": "答应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他答应了一本书，放在桌上。", "explanation": "这里应该用〈买〉。答应表示应允别人的请求，不能用于得到物品，买书要说买。"}, {"text": "他终于答应了自己的错误。", "explanation": "这里应该用〈承认〉。答应指应下别人的请求去做事，承认自己的错误要说承认。"}, {"text": "他立即答应了大家的批评，并开始改正。", "explanation": "这里应该用〈接受〉。答应指应下别人的请求去做事，虚心听取批评要说接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他请我周末去帮忙，我没答应了。", "corrected_sentence": "他请我周末去帮忙，我没答应。", "error_description": "错误：“没答应了”。正确：“没答应”。“没”否定动作时，动词后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她请我帮忙照看小狗，我答应地很痛快。", "corrected_sentence": "她请我帮忙照看小狗，我答应得很痛快。", "error_description": "错误：“答应地很痛快”，误用“地”引出补语。正确：“答应得很痛快”。“地”用于动词前修饰动作，动词后的补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
