INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "答应是被叫或被问时出声回应，表示听见了。", "primary_collocate": null, "pronunciation": "dā ying", "ipa": "tɑ˥ iŋ", "syllable_count": 2, "sentences": [{"text": "我敲了半天门，里面没人答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叫他吃饭，他在房间里大声答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫到我的名字，我马上答应了一声。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喊了他三次，他都没答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在楼下喊他，他从二楼的窗口答应了一声。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话那头有人轻轻答应了一声，随即没了声音。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻地答应了一声，就走了。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到有人叫他，他连忙答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叫了几遍，孩子在床上才小声答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背对着我坐着，我叫他，他却一声也没答应。", "target_word": "答应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "答应了", "label": "完成体"}, {"form": "答应过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "被叫或被问时出声回应，表示听见了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "答应", "is_correct": true, "explanation": "答应 dā ying：被叫或被问时出声回应，表示听见了。"}, {"text": "打赢", "is_correct": false, "explanation": "dǎ yíng 与 dā ying 声调不同（第三声、第二声与第一声、轻声），意思是战胜。"}, {"text": "大营", "is_correct": false, "explanation": "dà yíng 与 dā ying 声调不同（第四声、第二声与第一声、轻声），意思是军营。"}, {"text": "答疑", "is_correct": false, "explanation": "dá yí 与 dā ying 声调不同（第二声、第二声与第一声、轻声），第二音节韵母也不同（i 与 ing），意思是解答疑问。"}], "explanations": {"答应": "答应 dā ying：被叫或被问时出声回应，表示听见了。", "打赢": "dǎ yíng 与 dā ying 声调不同（第三声、第二声与第一声、轻声），意思是战胜。", "大营": "dà yíng 与 dā ying 声调不同（第四声、第二声与第一声、轻声），意思是军营。", "答疑": "dá yí 与 dā ying 声调不同（第二声、第二声与第一声、轻声），第二音节韵母也不同（i 与 ing），意思是解答疑问。"}, "sentence_index": null, "correct_answer": "答应"}, "level_3": {"options": [{"text": "答应", "is_correct": true, "explanation": "正确：“没人答应”表示屋里没有人出声回应，符合回应的义项。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”是上级同意下级的请求，与敲门后有没有人出声回应无关。"}, {"text": "驳斥", "is_correct": false, "explanation": "语义：“驳斥”是反驳别人的言论，与敲门后没人出声的情境不符。"}, {"text": "吩咐", "is_correct": false, "explanation": "语义：“吩咐”是叫别人去做事，与敲门后有没有人出声回应无关。"}], "explanations": {"答应": "正确：“没人答应”表示屋里没有人出声回应，符合回应的义项。", "批准": "语义：“批准”是上级同意下级的请求，与敲门后有没有人出声回应无关。", "驳斥": "语义：“驳斥”是反驳别人的言论，与敲门后没人出声的情境不符。", "吩咐": "语义：“吩咐”是叫别人去做事，与敲门后有没有人出声回应无关。"}, "sentence_index": 0, "correct_answer": "答应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快答应了我的信。", "explanation": "这里应该用〈回复〉。答应表示出声回应或应允请求，回复信件要用回复。"}, {"text": "他向我道歉，我答应了他的道歉。", "explanation": "这里应该用〈接受〉。答应表示出声回应或应允请求，对别人的道歉要说接受。"}, {"text": "我叫他的名字，他答应看了我一眼。", "explanation": "这里应该用〈回头〉。答应表示出声回应或应允，不能与“看了我一眼”这样的动作搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "答应", "is_correct": true, "explanation": "答应 dā ying：表示被叫或被问时出声回应。"}, {"text": "扎营", "is_correct": false, "explanation": "zhā yíng 与 dā ying 声母不同（zh 与 d），第二音节声调也不同，意思是安营扎寨。"}, {"text": "大英", "is_correct": false, "explanation": "dà yīng 与 dā ying 声调不同（第四声、第一声与第一声、轻声），意思是英国。"}, {"text": "打印", "is_correct": false, "explanation": "dǎ yìn 与 dā ying 声调不同（第三声、第四声与第一声、轻声），第二音节韵母也不同（in 与 ing），意思是用打印机印出。"}], "explanations": {"答应": "答应 dā ying：表示被叫或被问时出声回应。", "扎营": "zhā yíng 与 dā ying 声母不同（zh 与 d），第二音节声调也不同，意思是安营扎寨。", "大英": "dà yīng 与 dā ying 声调不同（第四声、第一声与第一声、轻声），意思是英国。", "打印": "dǎ yìn 与 dā ying 声调不同（第三声、第四声与第一声、轻声），第二音节韵母也不同（in 与 ing），意思是用打印机印出。"}, "sentence_index": null, "correct_answer": "答应"}, "level_3": {"options": [{"text": "答应", "is_correct": true, "explanation": "正确：“她轻轻地答应了一声”指她轻声回应了一下，符合出声回应的义项。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”不能与“一声”搭配表示发出声音，“扔了一声”不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹住，与轻声回应的动作无关，句意荒诞。"}, {"text": "收", "is_correct": false, "explanation": "搭配：“收”不能与“一声”搭配表示发出声音，“收了一声”不通。"}], "explanations": {"答应": "正确：“她轻轻地答应了一声”指她轻声回应了一下，符合出声回应的义项。", "扔": "搭配：“扔”不能与“一声”搭配表示发出声音，“扔了一声”不通。", "咬": "语义：“咬”是用牙齿夹住，与轻声回应的动作无关，句意荒诞。", "收": "搭配：“收”不能与“一声”搭配表示发出声音，“收了一声”不通。"}, "sentence_index": 6, "correct_answer": "答应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他主动答应了自己的错误。", "explanation": "这里应该用〈承认〉。答应表示应允或回应，承认错误要说承认。"}, {"text": "他默默答应了大家的责备。", "explanation": "这里应该用〈承受〉。答应表示应允或回应，不能与“责备”搭配，承受批评要说承受。"}, {"text": "他很快答应了这个麻烦。", "explanation": "这里应该用〈解决〉。答应表示应允或回应，不能用于处理麻烦，解决麻烦要说解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我叫了他两声，他没答应了。", "corrected_sentence": "我叫了他两声，他没答应。", "error_description": "错误：“没答应了”。正确：“没答应”。“没”否定动作时，动词后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听到叫声，答应地很快。", "corrected_sentence": "他听到叫声，答应得很快。", "error_description": "错误：“答应地很快”，误用“地”引出补语。正确：“答应得很快”。“地”用于动词前修饰动作，动词后的补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
