INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "继承是接下前面的人留下来的东西。", "primary_collocate": null, "pronunciation": "jì chéng", "ipa": "tɕi˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他继承了爷爷留下的老房子。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿继承了妈妈的那本旧书。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块手表是我从爸爸那里继承的。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥继承了父亲的小书店。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她继承了奶奶留下的一笔钱。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张旧桌子是他继承下来的。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我什么也没继承，一切靠自己。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了叔叔留下的一辆车。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人去世后，孩子们继承了他的田地。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她继承了外婆留下的那件红衣服。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "继承了", "label": "完成体标"}, {"form": "继承着", "label": "持续体标"}, {"form": "继承过", "label": "经历体标"}, {"form": "继承人", "label": "复合"}, {"form": "繼承", "label": "繁体"}], "register": "中性", "sense_fingerprint": "接下前人留下来的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91217, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "继承", "is_correct": true, "explanation": "目标词，读音 jì chéng，意思是接下前人留下来的东西。"}, {"text": "集成", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是把各部分组合成一个整体。"}, {"text": "进程", "is_correct": false, "explanation": "jìn 比 jì 多一个韵尾 n，意思是事情发展的过程。"}, {"text": "制成", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），意思是按一定方法做成某物。"}, {"text": "几成", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是大约几成（几分之几）。"}], "explanations": {"继承": "目标词，读音 jì chéng，意思是接下前人留下来的东西。", "集成": "jí（第二声）与 jì（第四声）声调不同，意思是把各部分组合成一个整体。", "进程": "jìn 比 jì 多一个韵尾 n，意思是事情发展的过程。", "制成": "zhì 与 jì 声母不同（zh 与 j），意思是按一定方法做成某物。", "几成": "jǐ（第三声）与 jì（第四声）声调不同，意思是大约几成（几分之几）。"}, "sentence_index": null, "correct_answer": "继承"}, "level_3": {"options": [{"text": "继承", "is_correct": true, "explanation": "语义：继承表示接下前人留下的东西，与“爷爷留下的老房子”相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，老房子不能被吃。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”的对象一般是能抱起来的东西，不能说抱老房子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲等，不能用来唱房子。"}], "explanations": {"继承": "语义：继承表示接下前人留下的东西，与“爷爷留下的老房子”相符。", "吃": "语义：吃的对象是食物，老房子不能被吃。", "抱": "搭配：“抱”的对象一般是能抱起来的东西，不能说抱老房子。", "唱": "语义：唱的对象是歌曲等，不能用来唱房子。"}, "sentence_index": 0, "correct_answer": "继承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从老师那里继承了一个好消息。", "explanation": "这里应该用〈得到〉。继承指接下前人留下来的财产或东西，好消息不能被继承，应说得到。"}, {"text": "我继承了朋友寄来的礼物。", "explanation": "这里应该用〈收到〉。继承要求是前人留下来的东西，朋友寄来的礼物不是遗留下来的，应说收到。"}, {"text": "他继承了朋友的感冒。", "explanation": "这里应该用〈染上〉。继承指接下前人留下来的财产或东西，感冒是被传染的，不是遗留下来的，应说染上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "继承", "is_correct": true, "explanation": "语义：继承表示接下前人留下的东西，这里说“什么也没继承”，与“一切靠自己”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，“什么也没唱”与句意无关。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是具体的动作，“什么也没咬”与“一切靠自己”无关，句意不通。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：感谢需要说明感谢的对象或原因，“什么也没感谢”不成立。"}], "explanations": {"继承": "语义：继承表示接下前人留下的东西，这里说“什么也没继承”，与“一切靠自己”相符。", "唱": "语义：唱的对象是歌曲，“什么也没唱”与句意无关。", "咬": "语义：咬是具体的动作，“什么也没咬”与“一切靠自己”无关，句意不通。", "感谢": "搭配：感谢需要说明感谢的对象或原因，“什么也没感谢”不成立。"}, "sentence_index": 6, "correct_answer": "继承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她继承了这次考试的好成绩。", "explanation": "这里应该用〈取得〉。继承指接下前人留下来的东西，考试成绩要靠自己努力取得，不能说继承，应说取得。"}, {"text": "他继承了一笔奖学金。", "explanation": "这里应该用〈获得〉。继承指接下前人留下来的财产，奖学金是凭成绩获得的，不是前人留下的，应说获得。"}, {"text": "他继承了一张驾照。", "explanation": "这里应该用〈取得〉。继承指接下前人留下来的财产或东西，驾照要通过考试取得，不是前人留下的，应说取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从外公那里继承了过这间小屋。", "corrected_sentence": "我从外公那里继承了这间小屋。", "error_description": "“了”与“过”不能同时用在动词“继承”后，两个体标并用是错误的；表示已完成的动作只用“了”，应说“继承了这间小屋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我什么也没继承了，全靠自己打拼。", "corrected_sentence": "我什么也没继承，全靠自己打拼。", "error_description": "“没”否定动作时不能与“了”同用：应直接说“没继承”，不能说“没继承了”；句中的“了”位于“继承”之后，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
