INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依法承受财产；接续前人的事业或传统。", "primary_collocate": null, "pronunciation": "jì chéng", "ipa": "tɕi˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "法律规定，孩子可以继承父母的财产。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了父亲的公司，成为新老板。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要继承中国的好传统。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她继承了老师的事业，继续做研究。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人继承了祖先的手艺。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子有权继承这些财产。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该继承和发扬优良传统。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了家里的茶馆，还开了新店。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙子继承了爷爷的所有财产。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想继承父亲的事业，做一名医生。", "target_word": "继承", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "继承了", "label": "完成体标"}, {"form": "继承着", "label": "持续体标"}, {"form": "继承过", "label": "经历体标"}, {"form": "继承人", "label": "复合"}, {"form": "继承权", "label": "复合"}, {"form": "繼承", "label": "繁体"}], "register": "中性", "sense_fingerprint": "依法承受财产，或接续前人的事业、传统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "继承", "is_correct": true, "explanation": "目标词，读音 jì chéng，意思是依法承受财产或接续前人的事业。"}, {"text": "集成", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是把各部分组合成一个整体。"}, {"text": "进程", "is_correct": false, "explanation": "jìn 比 jì 多一个韵尾 n，意思是事情发展的过程。"}, {"text": "制成", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），意思是按一定方法做成某物。"}, {"text": "几成", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是大约几成（几分之几）。"}], "explanations": {"继承": "目标词，读音 jì chéng，意思是依法承受财产或接续前人的事业。", "集成": "jí（第二声）与 jì（第四声）声调不同，意思是把各部分组合成一个整体。", "进程": "jìn 比 jì 多一个韵尾 n，意思是事情发展的过程。", "制成": "zhì 与 jì 声母不同（zh 与 j），意思是按一定方法做成某物。", "几成": "jǐ（第三声）与 jì（第四声）声调不同，意思是大约几成（几分之几）。"}, "sentence_index": null, "correct_answer": "继承"}, "level_3": {"options": [{"text": "继承", "is_correct": true, "explanation": "语义：继承表示依法承受财产，与“孩子可以……父母的财产”相符。"}, {"text": "继续", "is_correct": false, "explanation": "搭配：“继续”后接的是行为或工作，不能说继续父母的财产。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是转换语言，与财产无关，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量用于长度、重量等，不能用于财产，句意不通。"}], "explanations": {"继承": "语义：继承表示依法承受财产，与“孩子可以……父母的财产”相符。", "继续": "搭配：“继续”后接的是行为或工作，不能说继续父母的财产。", "翻译": "语义：翻译是转换语言，与财产无关，句意不通。", "测量": "语义：测量用于长度、重量等，不能用于财产，句意不通。"}, "sentence_index": 0, "correct_answer": "继承"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他继承了老师的批评。", "explanation": "这里应该用〈接受〉。继承的是前人留下的财产或事业，老师的批评是对方说的话，应说接受。"}, {"text": "她继承了一个奖项。", "explanation": "这里应该用〈获得〉。奖项是凭成绩取得的，不是前人留下的，应说获得。"}, {"text": "我们继承了他的鼓励。", "explanation": "这里应该用〈收到〉。鼓励是别人给予的，不是遗留下来的东西，应说收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "继承", "is_correct": true, "explanation": "语义：此处的继承表示接续前人的传统，与“发扬”搭配，句意通顺。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃与发扬意思相反，两者不能并列。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：遗忘与发扬相反，句意自相矛盾。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除的对象是建筑、设施等，不能用于传统。"}], "explanations": {"继承": "语义：此处的继承表示接续前人的传统，与“发扬”搭配，句意通顺。", "放弃": "语义：放弃与发扬意思相反，两者不能并列。", "遗忘": "语义：遗忘与发扬相反，句意自相矛盾。", "拆除": "搭配：拆除的对象是建筑、设施等，不能用于传统。"}, "sentence_index": 6, "correct_answer": "继承"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他继承了自己的错误。", "explanation": "这里应该用〈承认〉。错误不是可以继承的东西，应说承认错误。"}, {"text": "她继承了老师的表扬。", "explanation": "这里应该用〈得到〉。表扬是别人给予的，不是前人留下的，应说得到。"}, {"text": "我们继承了大家的意见。", "explanation": "这里应该用〈采纳〉。意见是听取后接受的，不是遗留下来的，应说采纳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她早就继承奶奶的那家小餐馆。", "corrected_sentence": "她早就继承了奶奶的那家小餐馆。", "error_description": "“继承”表示已完成的承受，应写作“早就继承了”；“早就继承奶奶的”缺少“了”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要把这门手艺继承出去。", "corrected_sentence": "我们要把这门手艺继承下去。", "error_description": "“继承”后的补语应为“下去”，表示延续下去；写成“出去”与句意不符，“继承出去”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
