INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91221, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脱离是离开原来在一起的地方或人。", "primary_collocate": null, "pronunciation": "tuō lí", "ipa": "tʰwo˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "小羊脱离了羊群，走丢了。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受伤后脱离了大部队。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭很快脱离了地面。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车厢脱离了火车，停在路边。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里脱离了同伴，迷路了。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船脱离了大船，漂到远处。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想脱离朋友们，所以没走。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员受了伤，只好脱离队伍。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗脱离主人，跑进了树林。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球脱离了他的手，飞上天空。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱离了", "label": "完成体"}, {"form": "脱离过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "从原来所在的群体、地方或接触处分开离去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91221, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脱离", "is_correct": true, "explanation": "脱离 tuō lí：表示从原来所在的群体、地方或接触处分开离去。"}, {"text": "推理", "is_correct": false, "explanation": "tuī lǐ 与 tuō lí 韵母不同（ī 与 ō），lǐ 与 lí 声调也不同，意思是根据已知推断。"}, {"text": "脱粒", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。"}, {"text": "脱力", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}], "explanations": {"脱离": "脱离 tuō lí：表示从原来所在的群体、地方或接触处分开离去。", "推理": "tuī lǐ 与 tuō lí 韵母不同（ī 与 ō），lǐ 与 lí 声调也不同，意思是根据已知推断。", "脱粒": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。", "脱力": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}, "sentence_index": null, "correct_answer": "脱离"}, "level_3": {"options": [{"text": "脱离", "is_correct": true, "explanation": "正确：“小羊脱离了羊群，走丢了”表示小羊离开羊群，符合分开离去的义项。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”的对象是物品或房间，不能用于“羊群”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用于“羊群”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，与“走丢了”的结果无关，句意不通。"}], "explanations": {"脱离": "正确：“小羊脱离了羊群，走丢了”表示小羊离开羊群，符合分开离去的义项。", "收拾": "搭配：“收拾”的对象是物品或房间，不能用于“羊群”。", "修理": "搭配：“修理”的对象是器物，不能用于“羊群”。", "咬": "语义：“咬”指用牙齿咬，与“走丢了”的结果无关，句意不通。"}, "sentence_index": 0, "correct_answer": "脱离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他脱离了帽子，放在桌上。", "explanation": "这里应该用〈摘下〉。脱离指从原来在一起的地方分开，摘下帽子要说摘下。"}, {"text": "他把盘子擦了好几遍，终于脱离了上面的油。", "explanation": "这里应该用〈洗掉〉。脱离指从原来在一起的地方分开，去掉油渍要说洗掉。"}, {"text": "比赛脱离了。", "explanation": "这里应该用〈取消〉。脱离表示分开离去，比赛停止举行要说取消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91221, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脱离", "is_correct": true, "explanation": "脱离 tuō lí：表示从原来所在的群体、地方或接触处分开离去。"}, {"text": "推力", "is_correct": false, "explanation": "tuī lì 与 tuō lí 韵母不同（ī 与 ō），lì 与 lí 声调也不同，意思是推动的力量。"}, {"text": "说理", "is_correct": false, "explanation": "shuō lǐ 与 tuō lí 声母不同（sh 与 t），第二音节声调也不同（第三声与第二声），意思是讲道理。"}, {"text": "脱粒", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。"}], "explanations": {"脱离": "脱离 tuō lí：表示从原来所在的群体、地方或接触处分开离去。", "推力": "tuī lì 与 tuō lí 韵母不同（ī 与 ō），lì 与 lí 声调也不同，意思是推动的力量。", "说理": "shuō lǐ 与 tuō lí 声母不同（sh 与 t），第二音节声调也不同（第三声与第二声），意思是讲道理。", "脱粒": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。"}, "sentence_index": null, "correct_answer": "脱离"}, "level_3": {"options": [{"text": "脱离", "is_correct": true, "explanation": "正确：“他不想脱离朋友们，所以没走”表示他不想离开朋友，符合分开离去的义项。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”强调身体接触，不能表示与朋友分开，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与朋友无关，“不想吃朋友们”句意荒诞。"}, {"text": "嫁", "is_correct": false, "explanation": "搭配：“嫁”的对象是婚配的人，不能与“朋友们”搭配。"}], "explanations": {"脱离": "正确：“他不想脱离朋友们，所以没走”表示他不想离开朋友，符合分开离去的义项。", "抱": "搭配：“抱”强调身体接触，不能表示与朋友分开，句意不通。", "吃": "语义：“吃”与朋友无关，“不想吃朋友们”句意荒诞。", "嫁": "搭配：“嫁”的对象是婚配的人，不能与“朋友们”搭配。"}, "sentence_index": 6, "correct_answer": "脱离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从盒子里脱离了一支笔。", "explanation": "这里应该用〈取出〉。脱离指从原来在一起的地方分开，从盒子里拿东西要说取出。"}, {"text": "他一把脱离了气球的绳子。", "explanation": "这里应该用〈抓住〉。脱离表示分开离去，不能表示用手握住东西。"}, {"text": "他脱离了那份旧报纸。", "explanation": "这里应该用〈扔掉〉。脱离表示从原来的地方分开，丢弃物品要用扔掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他松开手后，风筝慢慢脱离在他的手。", "corrected_sentence": "他松开手后，风筝慢慢脱离了他的手。", "error_description": "错误：“脱离在他的手”，在“脱离”后误加“在”。正确：“脱离了他的手”。“脱离”后直接带宾语，并用“了”表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只鸟脱离着鸟群，飞走了。", "corrected_sentence": "那只鸟脱离了鸟群，飞走了。", "error_description": "错误：“脱离着鸟群”，把“了”误写成“着”。正确：“脱离了鸟群”。“脱离”表示已经完成的分开，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "联系", "is_correct": true, "explanation": "反义：“脱离群众”与“联系群众”相对，脱离表示断绝，联系表示相连。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：研究是深入探讨问题，与脱离的断绝义无关。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：修理是使器物恢复正常，与脱离无关。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：散步是悠闲地走动，与脱离无关。"}], "correct_answer": "联系", "explanations": {"联系": "反义：“脱离群众”与“联系群众”相对，脱离表示断绝，联系表示相连。", "研究": "无反义关系：研究是深入探讨问题，与脱离的断绝义无关。", "修理": "无反义关系：修理是使器物恢复正常，与脱离无关。", "散步": "无反义关系：散步是悠闲地走动，与脱离无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结合", "is_correct": true, "explanation": "反义：“脱离实际”与“结合实际”相对，脱离表示断绝，结合表示连接。"}, {"text": "阅读", "is_correct": false, "explanation": "无反义关系：阅读是看书报，与脱离无关。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：游泳是在水中活动，与脱离无关。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：打扫是清理场所，与脱离无关。"}], "correct_answer": "结合", "explanations": {"结合": "反义：“脱离实际”与“结合实际”相对，脱离表示断绝，结合表示连接。", "阅读": "无反义关系：阅读是看书报，与脱离无关。", "游泳": "无反义关系：游泳是在水中活动，与脱离无关。", "打扫": "无反义关系：打扫是清理场所，与脱离无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开；断绝关系。", "primary_collocate": null, "pronunciation": "tuō lí", "ipa": "tʰwo˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "他已经脱离了那个组织。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人早就和家里脱离关系了。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的想法太脱离现实了。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习不能脱离生活。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想脱离父母，自己生活。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们脱离了原来的公司，自己做生意。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人已经脱离危险了。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大后，总想脱离父母的管理。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报上写了声明，宣布脱离父子关系。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事不能脱离实际情况。", "target_word": "脱离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱离了", "label": "完成体"}, {"form": "脱离过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "离开某种状态或断绝与人、事物的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脱离", "is_correct": true, "explanation": "脱离 tuō lí：表示离开某种状态，或断绝与人、事物的关系。"}, {"text": "推理", "is_correct": false, "explanation": "tuī lǐ 与 tuō lí 韵母不同（ī 与 ō），lǐ 与 lí 声调也不同，意思是根据已知推断。"}, {"text": "脱粒", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。"}, {"text": "脱力", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}], "explanations": {"脱离": "脱离 tuō lí：表示离开某种状态，或断绝与人、事物的关系。", "推理": "tuī lǐ 与 tuō lí 韵母不同（ī 与 ō），lǐ 与 lí 声调也不同，意思是根据已知推断。", "脱粒": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是使谷物与穗秆等分离。", "脱力": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}, "sentence_index": null, "correct_answer": "脱离"}, "level_3": {"options": [{"text": "脱离", "is_correct": true, "explanation": "正确：“他已经脱离了那个组织”表示他已经断绝与组织的关系，符合本义项。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器物，不能用于“组织”。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是有形的物品，“那个组织”不能被搬运。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“那个组织”作宾语。"}], "explanations": {"脱离": "正确：“他已经脱离了那个组织”表示他已经断绝与组织的关系，符合本义项。", "修理": "搭配：“修理”的对象是器物，不能用于“组织”。", "搬运": "搭配：“搬运”的对象是有形的物品，“那个组织”不能被搬运。", "哭": "配价：“哭”是不及物动词，不能带“那个组织”作宾语。"}, "sentence_index": 0, "correct_answer": "脱离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议中途，他脱离了座位去接电话。", "explanation": "这里应该用〈离开〉。脱离指离开某种状态或断绝与群体、关系的联系，暂时走开座位要用离开。"}, {"text": "他的头发脱离了很多。", "explanation": "这里应该用〈脱落〉。脱离多指离开群体、关系或状态，头发掉下来要用脱落。"}, {"text": "进屋后，他脱离了外套。", "explanation": "这里应该用〈脱掉〉。脱离表示断绝关系或离开某种状态，脱衣服要用脱掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脱离", "is_correct": true, "explanation": "脱离 tuō lí：表示离开某种状态，或断绝与人、事物的关系。"}, {"text": "推力", "is_correct": false, "explanation": "tuī lì 与 tuō lí 韵母不同（ī 与 ō），lì 与 lí 声调也不同，意思是推动的力量。"}, {"text": "说理", "is_correct": false, "explanation": "shuō lǐ 与 tuō lí 声母不同（sh 与 t），第二音节声调也不同（第三声与第二声），意思是讲道理。"}, {"text": "脱力", "is_correct": false, "explanation": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}], "explanations": {"脱离": "脱离 tuō lí：表示离开某种状态，或断绝与人、事物的关系。", "推力": "tuī lì 与 tuō lí 韵母不同（ī 与 ō），lì 与 lí 声调也不同，意思是推动的力量。", "说理": "shuō lǐ 与 tuō lí 声母不同（sh 与 t），第二音节声调也不同（第三声与第二声），意思是讲道理。", "脱力": "tuō lì 与 tuō lí 的第二音节声调不同（第四声与第二声），意思是失去力气。"}, "sentence_index": null, "correct_answer": "脱离"}, "level_3": {"options": [{"text": "脱离", "is_correct": true, "explanation": "正确：“病人已经脱离危险了”表示病人已经摆脱危险，符合本义项。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”的对象是物品或人员，不能与“危险”搭配。"}, {"text": "编织", "is_correct": false, "explanation": "搭配：“编织”指把线等编成物件，不能与“危险”搭配。"}, {"text": "死亡", "is_correct": false, "explanation": "配价：“死亡”是不及物动词，不能带“危险”作宾语。"}], "explanations": {"脱离": "正确：“病人已经脱离危险了”表示病人已经摆脱危险，符合本义项。", "挑选": "搭配：“挑选”的对象是物品或人员，不能与“危险”搭配。", "编织": "搭配：“编织”指把线等编成物件，不能与“危险”搭配。", "死亡": "配价：“死亡”是不及物动词，不能带“危险”作宾语。"}, "sentence_index": 6, "correct_answer": "脱离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然脱离了跑步。", "explanation": "这里应该用〈停止〉。脱离表示断绝关系或脱出状态，不能直接带“跑步”这样的动作作宾语，停下动作要用停止。"}, {"text": "他脱离了窗户。", "explanation": "这里应该用〈打开〉。脱离不用于开关门窗这类具体动作，打开窗户要说打开。"}, {"text": "他很快脱离了作业，去玩了。", "explanation": "这里应该用〈完成〉。脱离表示断绝关系或离开某种状态，做完作业要说完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于脱离在那个团体。", "corrected_sentence": "他终于脱离了那个团体。", "error_description": "错误：“脱离在那个团体”，在“脱离”后误加“在”。正确：“脱离了那个团体”。“脱离”后直接带宾语，并用“了”表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病人终于脱离着危险。", "corrected_sentence": "病人终于脱离了危险。", "error_description": "错误：“脱离着危险”，把“了”误写成“着”。正确：“脱离了危险”。“脱离”表示已经完成的状态变化，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
