INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91223, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把声音留在机器里，以后还能再听。", "primary_collocate": null, "pronunciation": "lù yīn", "ipa": "lu˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "老师上课时，同学们可以用手机录音。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会以前，请先打开手机开始录音。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想录音，以后再听老师讲的课。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上都在房间里录音练英语。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访时一直在录音，没有停过。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里太吵了，现在不能录音。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他录音前，先让大家安静一下。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我开始录音，半个小时后机器没电了。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问我可以在会议上录音吗？", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子第一次说话，妈妈马上拿手机录音。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "录音机", "label": "复合"}, {"form": "录音笔", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手机或机器把声音留下来，动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91223, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：动词，把声音留在机器里，以后能再听。"}, {"text": "录影", "is_correct": false, "explanation": "yǐng（第三声）与 yīn（第一声）韵母与声调都不同，意思是录影（录制影像）。"}, {"text": "树荫", "is_correct": false, "explanation": "shù 与 lù 声母不同（sh 与 l），意思是树荫（树木形成的阴凉）。"}, {"text": "绿荫", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿荫（树木形成的阴凉）。"}], "explanations": {"录音": "录音：动词，把声音留在机器里，以后能再听。", "录影": "yǐng（第三声）与 yīn（第一声）韵母与声调都不同，意思是录影（录制影像）。", "树荫": "shù 与 lù 声母不同（sh 与 l），意思是树荫（树木形成的阴凉）。", "绿荫": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿荫（树木形成的阴凉）。"}, "sentence_index": null, "correct_answer": "录音"}, "level_3": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：动词，此处指用手机把课堂上的声音录下来。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：手机不能用来睡觉，而且“上课时”不允许做这种事，句子与语境冲突。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“用”后接工具，“洗澡”不能用手机来做，搭配不成立。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步不需要手机，且与“上课时”的语境不合。"}], "explanations": {"录音": "录音：动词，此处指用手机把课堂上的声音录下来。", "睡觉": "语义：手机不能用来睡觉，而且“上课时”不允许做这种事，句子与语境冲突。", "洗澡": "搭配：“用”后接工具，“洗澡”不能用手机来做，搭配不成立。", "散步": "语义：散步不需要手机，且与“上课时”的语境不合。"}, "sentence_index": 0, "correct_answer": "录音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用手机把婚礼的画面录音了下来。", "explanation": "这里应该用〈录像〉。录音只能录下声音，婚礼的画面要用录像。"}, {"text": "公司录音了五个新员工。", "explanation": "这里应该用〈录用〉。录用指招收、聘用人员，录音只能用于录制声音。"}, {"text": "他把照片录音到电脑里。", "explanation": "这里应该用〈导入〉。录音只能录下声音，照片应该导入电脑，不能录音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91223, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：动词，把声音留在机器里，以后能再听。"}, {"text": "露营", "is_correct": false, "explanation": "yíng（第二声）与 yīn（第一声）韵母与声调都不同，意思是露营（在户外搭帐篷住宿）。"}, {"text": "注音", "is_correct": false, "explanation": "zhù 与 lù 声母不同，意思是注音（用符号标注字的读音）。"}, {"text": "绿茵", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿茵（绿色的草地）。"}], "explanations": {"录音": "录音：动词，把声音留在机器里，以后能再听。", "露营": "yíng（第二声）与 yīn（第一声）韵母与声调都不同，意思是露营（在户外搭帐篷住宿）。", "注音": "zhù 与 lù 声母不同，意思是注音（用符号标注字的读音）。", "绿茵": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿茵（绿色的草地）。"}, "sentence_index": null, "correct_answer": "录音"}, "level_3": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：动词，此处指在开始前把声音录下来。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”与后半句“先让大家安静一下”的要求矛盾。"}, {"text": "喊叫", "is_correct": false, "explanation": "语义：“喊叫”与“先让大家安静一下”的语境冲突。"}, {"text": "喧哗", "is_correct": false, "explanation": "语域：“喧哗”是书面语，与口语句不合，且与“安静一下”的语义相悖。"}], "explanations": {"录音": "录音：动词，此处指在开始前把声音录下来。", "吵闹": "语义：“吵闹”与后半句“先让大家安静一下”的要求矛盾。", "喊叫": "语义：“喊叫”与“先让大家安静一下”的语境冲突。", "喧哗": "语域：“喧哗”是书面语，与口语句不合，且与“安静一下”的语义相悖。"}, "sentence_index": 6, "correct_answer": "录音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天用密码录音电脑。", "explanation": "这里应该用〈登录〉。登录指进入系统，录音指把声音录下来，不能用于进入电脑。"}, {"text": "他去派出所录音户口。", "explanation": "这里应该用〈登记〉。登记指把信息记录在册，录音不能用于办理户口。"}, {"text": "医生认真录音病人的体温。", "explanation": "这里应该用〈记录〉。记录指写下或记下数据，录音不能用于记录体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打算录音老师的讲课，回家再听。", "corrected_sentence": "我打算录下老师的讲课，回家再听。", "error_description": "“录音”是离合词，不能直接带宾语。错误在于在离合词后面直接加了宾语“老师的讲课”，应说“录下老师的讲课”或“录老师的讲课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他录音完就走了。", "corrected_sentence": "他录完音就走了。", "error_description": "“录音”是离合词，结果补语“完”应插在“录”和“音”之间，即说“录完音”，不能说“录音完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
