INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "录下来的声音材料，可以播放或保存。", "primary_collocate": null, "pronunciation": "lù yīn", "ipa": "lu˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "这段录音很清楚，我听了三遍。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们放了一段英语录音。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把妈妈的录音存在手机里。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把会议录音发给我。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在听那段录音。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是奶奶讲故事的录音，我很喜欢。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "录音里有很多人说话的声音。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时，我们要先听录音再做题。", "target_word": "录音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直留着爸爸的录音。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个录音太短了，听不出他说什么。", "target_word": "录音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段录音", "label": "量词"}, {"form": "录音机", "label": "复合"}], "register": "中性", "sense_fingerprint": "录下来的声音材料，可以播放、保存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e5eb461-8e2e-4423-8692-ca4884dea8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：名词，录下来的声音材料，此处指可以播放的录音。"}, {"text": "录影", "is_correct": false, "explanation": "yǐng（第三声）与 yīn（第一声）韵母与声调都不同，意思是录影（录制影像）。"}, {"text": "树荫", "is_correct": false, "explanation": "shù 与 lù 声母不同（sh 与 l），意思是树荫（树木形成的阴凉）。"}, {"text": "绿荫", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿荫（树木形成的阴凉）。"}], "explanations": {"录音": "录音：名词，录下来的声音材料，此处指可以播放的录音。", "录影": "yǐng（第三声）与 yīn（第一声）韵母与声调都不同，意思是录影（录制影像）。", "树荫": "shù 与 lù 声母不同（sh 与 l），意思是树荫（树木形成的阴凉）。", "绿荫": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿荫（树木形成的阴凉）。"}, "sentence_index": null, "correct_answer": "录音"}, "level_3": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：名词，指录下来的声音材料，可以听。"}, {"text": "笔记", "is_correct": false, "explanation": "语义：笔记是写下来用来看的，不能听，与“我听了三遍”冲突。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是用来看的，不能听，与“我听了三遍”冲突。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：量词“段”不用于“雨”，“这段雨”不成立。"}], "explanations": {"录音": "录音：名词，指录下来的声音材料，可以听。", "笔记": "语义：笔记是写下来用来看的，不能听，与“我听了三遍”冲突。", "照片": "语义：照片是用来看的，不能听，与“我听了三遍”冲突。", "雨": "搭配：量词“段”不用于“雨”，“这段雨”不成立。"}, "sentence_index": 0, "correct_answer": "录音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把录音的电池换了。", "explanation": "这里应该用〈录音机〉。录音指录下的声音内容，本身没有电池，电池属于录音机。"}, {"text": "老师把录音拿进了教室，同学们都在等。", "explanation": "这里应该用〈收录机〉。录音指录下的声音内容，不能指用来播放的机器。"}, {"text": "我把录音充满了电。", "explanation": "这里应该用〈录音笔〉。录音是声音内容，不能充电，充电的是录音笔这类设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：名词，录下来的声音材料，此处指可以播放的录音。"}, {"text": "露营", "is_correct": false, "explanation": "yíng（第二声）与 yīn（第一声）韵母与声调都不同，意思是露营（在户外搭帐篷住宿）。"}, {"text": "注音", "is_correct": false, "explanation": "zhù 与 lù 声母不同，意思是注音（用符号标注字的读音）。"}, {"text": "绿茵", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿茵（绿色的草地）。"}], "explanations": {"录音": "录音：名词，录下来的声音材料，此处指可以播放的录音。", "露营": "yíng（第二声）与 yīn（第一声）韵母与声调都不同，意思是露营（在户外搭帐篷住宿）。", "注音": "zhù 与 lù 声母不同，意思是注音（用符号标注字的读音）。", "绿茵": "lǜ 与 lù 韵母不同（ü 与 u），意思是绿茵（绿色的草地）。"}, "sentence_index": null, "correct_answer": "录音"}, "level_3": {"options": [{"text": "录音", "is_correct": true, "explanation": "录音：名词，指录下来的声音材料，里面可以有人说话的声音。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子里不会有人说话的声音，与句意不合。"}, {"text": "相册", "is_correct": false, "explanation": "语义：相册里是照片，没有声音，与“有很多人说话的声音”冲突。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是声音材料，里面不会录有人说话的声音，与句意不合。"}], "explanations": {"录音": "录音：名词，指录下来的声音材料，里面可以有人说话的声音。", "镜子": "语义：镜子里不会有人说话的声音，与句意不合。", "相册": "语义：相册里是照片，没有声音，与“有很多人说话的声音”冲突。", "天空": "语义：天空不是声音材料，里面不会录有人说话的声音，与句意不合。"}, "sentence_index": 6, "correct_answer": "录音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给这幅画录音，挂在墙上。", "explanation": "这里应该用〈画〉。录音只能录下声音，不能用来录制图画。"}, {"text": "这段录音很清楚，我看了三遍。", "explanation": "这里应该用〈录像〉。录像是可以看的影像，录音是声音，不能用“看”来接。"}, {"text": "他在黑板上录音了一行字。", "explanation": "这里应该用〈写〉。录音录的是声音，在黑板上写字不能用录音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 