INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在桌上找到了一只录音，听了很久。", "corrected_sentence": "我在桌上找到了一段录音，听了很久。", "error_description": "量词用错。“录音”作为录下来的声音材料应使用量词“段”，“只”不能用于录音，应说“一段录音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天晚上都听一台录音。", "corrected_sentence": "他每天晚上都听一段录音。", "error_description": "量词用错。录音作为录下的内容应使用“段”，“台”是机器的量词，不能用来修饰录音。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1dac30-eecb-4430-ba06-76a6654182b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
