INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91225, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟从是走在别人后面，听他的话。", "primary_collocate": null, "pronunciation": "gēn cóng", "ipa": "kən˥ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "孩子跟从妈妈走进商店。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们跟从着老师排好队。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小羊跟从羊妈妈走过小桥。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路跟从爸爸，不说话。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总是跟从我，我说什么他做什么。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们跟从班长走出教室。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要跟从大人，别乱跑。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个听话的孩子，什么都跟从爸爸。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子们跟从着鸭妈妈走向河边。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟从师傅学做饭，师傅说什么他就做什么。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟从了", "label": "完成体标"}, {"form": "跟从着", "label": "持续体标"}, {"form": "跟从过", "label": "经历体标"}, {"form": "跟從", "label": "繁体"}], "register": "书面", "sense_fingerprint": "走在别人后面，听他的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟从", "is_correct": true, "explanation": "“跟从”表示跟在别人后面走，符合“孩子跟着妈妈走进商店”的语境。"}, {"text": "监督", "is_correct": false, "explanation": "语义：“监督”指检查督促，与“走进商店”的跟随行为无关。"}, {"text": "研究", "is_correct": false, "explanation": "搭配：“研究”不能带“妈妈走进商店”这类动作短语作宾语。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：“训练”的对象是人或动物的技能，不能与“走进商店”搭配。"}], "explanations": {"跟从": "“跟从”表示跟在别人后面走，符合“孩子跟着妈妈走进商店”的语境。", "监督": "语义：“监督”指检查督促，与“走进商店”的跟随行为无关。", "研究": "搭配：“研究”不能带“妈妈走进商店”这类动作短语作宾语。", "训练": "搭配：“训练”的对象是人或动物的技能，不能与“走进商店”搭配。"}, "sentence_index": 0, "correct_answer": "跟从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子跟从妈妈的心情，每天都很高兴。", "explanation": "这里应该用〈受影响〉。“跟从”只表示跟在后面或听从，不表示受他人情绪左右，应说“受影响”。"}, {"text": "这位律师跟从当事人的案子，每天都在忙。", "explanation": "这里应该用〈负责〉。“跟从”只表示跟在后面或听从，不表示承担事务，应说“负责”。"}, {"text": "我们要跟从纪律，不能随便迟到。", "explanation": "这里应该用〈遵守〉。“跟从”的对象是人，不能用于制度或纪律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟从", "is_correct": true, "explanation": "“跟从”表示听从大人、跟在大人后面，符合“孩子要听大人的话”的语境。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”与“别乱跑”的叮嘱语境相反，句意不通。"}, {"text": "辩论", "is_correct": false, "explanation": "配价：“辩论”不能直接带人作宾语，需用“与”引出对象。"}, {"text": "冒犯", "is_correct": false, "explanation": "语义：“冒犯”指得罪他人，与“别乱跑”的劝导语境无关。"}], "explanations": {"跟从": "“跟从”表示听从大人、跟在大人后面，符合“孩子要听大人的话”的语境。", "欺骗": "语义：“欺骗”与“别乱跑”的叮嘱语境相反，句意不通。", "辩论": "配价：“辩论”不能直接带人作宾语，需用“与”引出对象。", "冒犯": "语义：“冒犯”指得罪他人，与“别乱跑”的劝导语境无关。"}, "sentence_index": 6, "correct_answer": "跟从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保姆跟从孩子的成绩，每天都督促他。", "explanation": "这里应该用〈督促〉。“跟从”只表示跟在后面或听从，不表示催促，应说“督促”。"}, {"text": "队长跟从大家，走在最前面。", "explanation": "这里应该用〈带领〉。“跟从”是跟在别人后面，与“走在最前面”的带领相反。"}, {"text": "老师跟从学生的成长，每天都在评分。", "explanation": "这里应该用〈评价〉。“跟从”强调跟在后面，不表示对人或事物作出评价，应说“评价”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟跟从着哥哥着回家。", "corrected_sentence": "弟弟跟从着哥哥回家。", "error_description": "错误在于持续体标“着”多写了一次：“着”应紧接动词“跟从”，宾语“哥哥”之后再加“着”不合语法，应删去，写作“弟弟跟从着哥哥回家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们跟从着着老师走进教室。", "corrected_sentence": "学生们跟从着老师走进教室。", "error_description": "错误形式是“跟从着着老师走进教室”，正确形式是“跟从着老师走进教室”。持续体标“着”只用一次，重复写成“着着”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违抗", "is_correct": true, "explanation": "“违抗”指不听从、对抗命令，与“跟从”的服从义构成反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身前往，与“跟从”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”与“跟从”没有反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”指等候某事或某人，与“跟从”没有反义关系。"}], "correct_answer": "违抗", "explanations": {"违抗": "“违抗”指不听从、对抗命令，与“跟从”的服从义构成反义关系。", "出发": "“出发”指动身前往，与“跟从”没有反义关系。", "吃饭": "“吃饭”与“跟从”没有反义关系。", "等待": "“等待”指等候某事或某人，与“跟从”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反抗", "is_correct": true, "explanation": "“反抗”指对抗、不服从，与“服从”构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“跟从”没有反义关系。"}, {"text": "入睡", "is_correct": false, "explanation": "“入睡”指进入睡眠状态，与“跟从”没有反义关系。"}, {"text": "工作", "is_correct": false, "explanation": "“工作”指从事劳动或职务活动，与“跟从”没有反义关系。"}], "correct_answer": "反抗", "explanations": {"反抗": "“反抗”指对抗、不服从，与“服从”构成反义关系。", "散步": "“散步”指随意走动，与“跟从”没有反义关系。", "入睡": "“入睡”指进入睡眠状态，与“跟从”没有反义关系。", "工作": "“工作”指从事劳动或职务活动，与“跟从”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跟随；服从。", "primary_collocate": null, "pronunciation": "gēn cóng", "ipa": "kən˥ tsʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小狗一直跟从着主人走回家。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们跟从老师参观了博物馆。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很有主见，不肯跟从坏朋友。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们都跟从队长，不敢违抗命令。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子总喜欢跟从哥哥。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要盲目跟从大家的做法。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟从导游走进了山洞。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人跟从儿子搬到了城里。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都跟从着他的脚步向前走。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不跟从别人，总有自己的想法。", "target_word": "跟从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟从了", "label": "完成体标"}, {"form": "跟从着", "label": "持续体标"}, {"form": "跟从过", "label": "经历体标"}, {"form": "跟從", "label": "繁体"}], "register": "书面", "sense_fingerprint": "跟随别人，或服从别人的意见、指挥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跟从", "is_correct": true, "explanation": "“跟从”表示跟随别人走，符合“小狗跟着主人走回家”的语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是物品，小狗不能“修理着主人走回家”，句意不通。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶，与“走回家”的亲近语境相反。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：小狗不能赞美主人，“赞美着主人走回家”语义不通。"}], "explanations": {"跟从": "“跟从”表示跟随别人走，符合“小狗跟着主人走回家”的语境。", "修理": "语义：“修理”的对象是物品，小狗不能“修理着主人走回家”，句意不通。", "嫌弃": "语义：“嫌弃”表示厌恶，与“走回家”的亲近语境相反。", "赞美": "语义：小狗不能赞美主人，“赞美着主人走回家”语义不通。"}, "sentence_index": 0, "correct_answer": "跟从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们跟从老师的成绩，每天都很在意。", "explanation": "这里应该用〈关注〉。“跟从”的对象是人或意见，不能跟从成绩这类结果，表示留意应说“关注”。"}, {"text": "这位律师跟从当事人的案子，每天都在忙。", "explanation": "这里应该用〈负责〉。“跟从”只表示跟在后面或听从，不表示承担事务，应说“负责”。"}, {"text": "我们要跟从纪律，不能随便迟到。", "explanation": "这里应该用〈遵守〉。“跟从”的对象是人，不能用于制度或纪律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟从", "is_correct": true, "explanation": "“跟从”表示跟在导游后面走，符合“他跟着导游走进了山洞”的语境。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或事情，不能直接带人作宾语，句意不通。"}, {"text": "辩论", "is_correct": false, "explanation": "配价：“辩论”不能直接带人作宾语，需用“与”引出对象。"}, {"text": "询问", "is_correct": false, "explanation": "语义：“询问”需带问话内容，“询问导游走进了山洞”句意不通。"}], "explanations": {"跟从": "“跟从”表示跟在导游后面走，符合“他跟着导游走进了山洞”的语境。", "讨论": "搭配：“讨论”的对象是问题或事情，不能直接带人作宾语，句意不通。", "辩论": "配价：“辩论”不能直接带人作宾语，需用“与”引出对象。", "询问": "语义：“询问”需带问话内容，“询问导游走进了山洞”句意不通。"}, "sentence_index": 6, "correct_answer": "跟从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈跟从孩子的健康，每天都很关注。", "explanation": "这里应该用〈关心〉。“跟从”的对象是人或意见，不能跟从“健康”这样的事物。"}, {"text": "我们要跟从交通规则，红灯停，绿灯行。", "explanation": "这里应该用〈遵守〉。“跟从”的对象是人或人的意见，不能用于规则、制度，应说“遵守交通规则”。"}, {"text": "老师跟从学生做作业。", "explanation": "这里应该用〈监督〉。“跟从”表示跟随或听从，不表示检查或督促。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗一直跟从着着妈妈散步。", "corrected_sentence": "小狗一直跟从着妈妈散步。", "error_description": "错误形式是“跟从着着妈妈散步”，正确形式是“跟从着妈妈散步”。持续体标“着”只用一次，重复写成“着着”是多余的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人跟从着儿子着去超市。", "corrected_sentence": "老人跟从着儿子去超市。", "error_description": "错误在于持续体标“着”多写了一次：“着”应紧接动词“跟从”，宾语“儿子”之后的“着”多余，应删去，写作“老人跟从着儿子去超市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
