INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91227, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "另外加上，和别的东西放在一起。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu⁵¹", "syllable_count": 1, "sentences": [{"text": "申请表上要附一张照片。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的证件附上，再寄给我们。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发票要附在报销单后面。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮件里附了两个文件。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在信里附了一张全家的照片。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名时，请附上学生证的复印件。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表后面附了三张发票。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寄东西时，请附上你的地址。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片附在信的后面。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把合同和照片一起附上了。", "target_word": "附", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "附了", "label": "体标"}, {"form": "附上", "label": "复合"}], "register": "书面", "sense_fingerprint": "把东西另外加上并放在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "附", "is_correct": true, "explanation": "正确。附 fù（第四声）表示另外加上，和别的东西放在一起。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是官府、住宅。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 fù 声母不同（h 与 f），意思是门户、人家。"}], "explanations": {"附": "正确。附 fù（第四声）表示另外加上，和别的东西放在一起。", "夫": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。", "府": "fǔ（第三声）与 fù（第四声）声调不同，意思是官府、住宅。", "户": "hù（第四声）与 fù 声母不同（h 与 f），意思是门户、人家。"}, "sentence_index": null, "correct_answer": "附"}, "level_3": {"options": [{"text": "撕", "is_correct": false, "explanation": "语义：「撕」是撕破，与申请表要求的「附上」意思相反。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：「戴」要接帽子、眼镜等，不能接「照片」。"}, {"text": "附", "is_correct": true, "explanation": "正确。申请表上另外附带一张照片，用「附」。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」要接歌曲，不能接「照片」。"}], "explanations": {"撕": "语义：「撕」是撕破，与申请表要求的「附上」意思相反。", "戴": "搭配：「戴」要接帽子、眼镜等，不能接「照片」。", "附": "正确。申请表上另外附带一张照片，用「附」。", "唱": "搭配：「唱」要接歌曲，不能接「照片」。"}, "sentence_index": 0, "correct_answer": "附"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门时我附了两把伞。", "explanation": "这里应该用〈带〉。附指随文件另外附带，不用于随身携带东西，带伞要说「带」。"}, {"text": "箱子里附了两件衣服。", "explanation": "这里应该用〈装〉。附不表示把东西放进容器里，往箱子里放衣服要说「装」。"}, {"text": "门口附了一个牌子。", "explanation": "这里应该用〈挂〉。附不表示把牌子悬挂起来，挂牌子要说「挂」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91227, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "附", "is_correct": true, "explanation": "正确。附 fù（第四声）表示另外加上，和别的东西放在一起。"}, {"text": "福", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是福气。"}, {"text": "腐", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是腐烂。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 fù 声母不同（h 与 f），意思是保护。"}], "explanations": {"附": "正确。附 fù（第四声）表示另外加上，和别的东西放在一起。", "福": "fú（第二声）与 fù（第四声）声调不同，意思是福气。", "腐": "fǔ（第三声）与 fù（第四声）声调不同，意思是腐烂。", "护": "hù（第四声）与 fù 声母不同（h 与 f），意思是保护。"}, "sentence_index": null, "correct_answer": "附"}, "level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：「穿」要接衣服、鞋子，不能接「发票」。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指把东西咽下，与把发票附在表格后面的意思不符。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：「骑」要接自行车、马等，不能接「发票」。"}, {"text": "附", "is_correct": true, "explanation": "正确。表格后面另外附带三张发票，用「附」。"}], "explanations": {"穿": "搭配：「穿」要接衣服、鞋子，不能接「发票」。", "吃": "语义：「吃」指把东西咽下，与把发票附在表格后面的意思不符。", "骑": "搭配：「骑」要接自行车、马等，不能接「发票」。", "附": "正确。表格后面另外附带三张发票，用「附」。"}, "sentence_index": 6, "correct_answer": "附"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快附了我们的俱乐部。", "explanation": "这里应该用〈加入〉。附不表示加入组织，加入俱乐部要说「加入」。"}, {"text": "他用力附了那扇门。", "explanation": "这里应该用〈推〉。附不表示用力使物体移动，推门要说「推」。"}, {"text": "她用力附了那只箱子。", "explanation": "这里应该用〈抬〉。附不表示托起物体，抬箱子要说「抬」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EX