INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公众对事物的共同看法和议论。", "primary_collocate": null, "pronunciation": "yú lùn", "ipa": "y˧˥ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "社会舆论对这个问题很关心。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒体应该正确引导舆论。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舆论压力让公司改变了做法。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公众舆论一直在监督政府的工作。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新政策引起了广泛的舆论关注。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舆论普遍认为这个价格太高。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话在网络舆论中引起了争论。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社会舆论可以督促官员更认真地工作。", "target_word": "舆论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故发生后，舆论一片哗然。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的政策要先听听舆论的意见。", "target_word": "舆论", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "舆论界", "label": "复合"}, {"form": "輿論", "label": "繁体"}], "register": "书面", "sense_fingerprint": "舆论：公众对事物形成的共同看法和议论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舆论", "is_correct": true, "explanation": "正确。“舆论”指公众的共同看法，可以“关心”问题，符合“社会舆论对这个问题很关心”。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，不会“关心”问题。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，没有“关心”的意思。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不能“关心”问题。"}], "explanations": {"舆论": "正确。“舆论”指公众的共同看法，可以“关心”问题，符合“社会舆论对这个问题很关心”。", "粮食": "语义：粮食是食物，不会“关心”问题。", "词典": "语义：词典是工具书，没有“关心”的意思。", "颜色": "语义：颜色是事物的属性，不能“关心”问题。"}, "sentence_index": 0, "correct_answer": "舆论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写了一篇舆论，登在报纸上。", "explanation": "这里应该用〈评论〉。“舆论”是公众的共同看法，不是个人写的文章。"}, {"text": "政府把舆论藏进了抽屉。", "explanation": "这里应该用〈文件〉。“舆论”是抽象的看法，不能像物件一样藏进抽屉。"}, {"text": "我个人的舆论一直在监督政府的工作。", "explanation": "这里应该用〈意见〉。“舆论”指公众的共同看法，不属于一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舆论", "is_correct": true, "explanation": "正确。“网络舆论”指网上公众的看法，符合“他的话在网络舆论中引起了争论”。"}, {"text": "硬盘", "is_correct": false, "explanation": "语义：硬盘是存储设备，不能作为“引起争论”的场所。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压是电学概念，与“争论”无关。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是“争论”发生的公共看法空间。"}], "explanations": {"舆论": "正确。“网络舆论”指网上公众的看法，符合“他的话在网络舆论中引起了争论”。", "硬盘": "语义：硬盘是存储设备，不能作为“引起争论”的场所。", "电压": "语义：电压是电学概念，与“争论”无关。", "厨房": "语义：厨房是房间，不是“争论”发生的公共看法空间。"}, "sentence_index": 6, "correct_answer": "舆论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好的政策要先听听舆论的命令。", "explanation": "这里应该用〈意见〉。“舆论”是众人的看法，不能发出“命令”。"}, {"text": "好的政策要先听听舆论先生的意见。", "explanation": "这里应该用〈公众〉。“舆论”是抽象的看法，不是人，不能称作“先生”。"}, {"text": "好的政策要先听听舆论的作者的意见。", "explanation": "这里应该用〈公众〉。“舆论”是众人的共同看法，没有“作者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事形成了强大的社会舆论的。", "corrected_sentence": "这件事形成了强大的社会舆论。", "error_description": "结构错误：“这件事形成了强大的社会舆论”已是完整句，句末多出的“的”没有“是”字呼应，句子不通；去掉“的”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次选举后，舆论们十分热烈。", "corrected_sentence": "这次选举后，舆论十分热烈。", "error_description": "“们”只加在指人的名词后，“舆论”是抽象名词，不能说“舆论们”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
