INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事有多难。", "primary_collocate": null, "pronunciation": "nán dù", "ipa": "nan˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "你觉得这件事的难度有多大？", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没试过的人，不知道它的难度。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动作的难度很高，需要练很久。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先看看这道题的难度，再决定做不做。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工作有难度，但我想试一试。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题的难度差不多。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次都把比赛的难度提高一点。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的难度太高，我弹不好。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唱这首歌没有什么难度。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭的难度其实不大，你来试试。", "target_word": "难度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "难度系数", "label": "复合"}, {"form": "難度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "难度：一件事有多难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "难度", "is_correct": true, "explanation": "难度：一件事有多难，与“有多大”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观，事情没有颜色，不说“这件事的颜色有多大”。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指光的明暗，不能用来描述一件事。"}, {"text": "气味", "is_correct": false, "explanation": "语义：事情没有气味，不能说“事情的气味有多大”。"}], "explanations": {"难度": "难度：一件事有多难，与“有多大”相符。", "颜色": "语义：颜色是外观，事情没有颜色，不说“这件事的颜色有多大”。", "亮度": "语义：亮度指光的明暗，不能用来描述一件事。", "气味": "语义：事情没有气味，不能说“事情的气味有多大”。"}, "sentence_index": 0, "correct_answer": "难度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想先看看这道难度，再决定做不做。", "explanation": "这里应该用〈题〉。“难度”指难的程度，不能指题目本身。"}, {"text": "我想先解出这道难度，再决定做不做。", "explanation": "这里应该用〈难题〉。“解出”的对象是题，“难度”不能被解出。"}, {"text": "这门课的难度很多，我得先复习。", "explanation": "这里应该用〈内容〉。“难度”说的是难的程度，不能用“很多”来形容，课程的分量应说“内容很多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "难度", "is_correct": true, "explanation": "难度：比赛的困难程度，“提高”可用于此。"}, {"text": "形状", "is_correct": false, "explanation": "语义：比赛没有形状，不能说“把比赛的形状提高一点”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：比赛没有身高，不能说“把比赛的身高提高”。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“发型”是外观，不能被“提高”，“提高发型”不通。"}], "explanations": {"难度": "难度：比赛的困难程度，“提高”可用于此。", "形状": "语义：比赛没有形状，不能说“把比赛的形状提高一点”。", "身高": "语义：比赛没有身高，不能说“把比赛的身高提高”。", "发型": "搭配：“发型”是外观，不能被“提高”，“提高发型”不通。"}, "sentence_index": 6, "correct_answer": "难度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司陷入难度，很难翻身。", "explanation": "这里应该用〈困境〉。“陷入”搭配“困境”，不能说“陷入难度”。"}, {"text": "这是个难度，大家都解不出来。", "explanation": "这里应该用〈难题〉。“难度”指程度，不指具体的题，应说“这是个难题”。"}, {"text": "他把这道题的难度找了很久，最后放弃了。", "explanation": "这里应该用〈答案〉。找的是答案，“难度”指难的程度，不能被“找”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的难度比上次提起了不少。", "corrected_sentence": "这次比赛的难度比上次提高了不少。", "error_description": "搭配错误：“难度”应与“提高”搭配，“提起”指拿起或谈起，不说“提起难度”。应说“提高了不少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这次考试的难度加高了不少。", "corrected_sentence": "老师把这次考试的难度提高了不少。", "error_description": "搭配错误：“难度”应与“提高”搭配，“加高”只用于实际高度（如加高围墙），不说“加高难度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
