INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一周的末尾，通常指星期六和星期日。", "primary_collocate": null, "pronunciation": "zhōu mò", "ipa": "ʈʂoʊ˥ mwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "周末商店里的人特别多。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们周末去看电影，好吗？", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个周末都去爬山。", "target_word": "周末", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末就是星期六和星期日。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末我要加班，不能陪你了。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的路上车很多，我们坐地铁吧。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸周末喜欢在家看书。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一周工作五天，周末休息两天。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末快到了，大家都很高兴。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们约好这个周末见面。", "target_word": "周末", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "週末", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周末：一周的末尾，通常指星期六和星期日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7282aa94-d036-4e81-924d-e6357978ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周末", "is_correct": true, "explanation": "正确。“周末”指一周末尾的星期六和星期日，可以说“周末商店里的人特别多”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是时间，不能放在句首表示“什么时候”商店里人多。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是要做的功课，不是时间，不能说“作业商店里的人特别多”。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”是一顿饭，不是时间段，放在这里句子不通。"}], "explanations": {"周末": "正确。“周末”指一周末尾的星期六和星期日，可以说“周末商店里的人特别多”。", "天气": "语义：“天气”不是时间，不能放在句首表示“什么时候”商店里人多。", "作业": "语义：“作业”是要做的功课，不是时间，不能说“作业商店里的人特别多”。", "早饭": "语义：“早饭”是一顿饭，不是时间段，放在这里句子不通。"}, "sentence_index": 0, "correct_answer": "周末"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的周末最精彩。", "explanation": "这里应该用〈结尾〉。“周末”指一周的最后两天，不能指比赛的结尾。"}, {"text": "他把周末借给了朋友。", "explanation": "这里应该用〈时间〉。“周末”是一段时间，不能像物品一样借给别人。"}, {"text": "周末是一周的开始。", "explanation": "这里应该用〈周一〉。“周末”指一周的最后两天，不能说成一周的开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "周末", "is_correct": true, "explanation": "正确。“爸爸周末喜欢在家看书”中，“周末”作时间状语，指星期六和星期日。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不是时间，不能放在“喜欢”前面说明什么时候。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作时间状语，“爸爸地铁喜欢在家看书”不通。"}, {"text": "商店", "is_correct": false, "explanation": "语义：“商店”是地点，与后面的“在家”冲突，也不能表示时间。"}], "explanations": {"周末": "正确。“爸爸周末喜欢在家看书”中，“周末”作时间状语，指星期六和星期日。", "书包": "语义：“书包”是物品，不是时间，不能放在“喜欢”前面说明什么时候。", "地铁": "语义：“地铁”是交通工具，不能作时间状语，“爸爸地铁喜欢在家看书”不通。", "商店": "语义：“商店”是地点，与后面的“在家”冲突，也不能表示时间。"}, "sentence_index": 6, "correct_answer": "周末"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的周末写得很精彩。", "explanation": "这里应该用〈结尾〉。“周末”指一周的最后两天，不能指作品的结尾。"}, {"text": "我们坐在周末上聊天。", "explanation": "这里应该用〈椅子〉之类的具体物品。“周末”是时间，不能当作椅子来坐。"}, {"text": "我的爱好是周末。", "explanation": "这里应该用〈活动〉。“爱好”指经常做的具体事情，“周末”是时间段，不能作“爱好”的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们周末的去打球吧。", "corrected_sentence": "我们周末去打球吧。", "error_description": "结构错误：“周末”作时间状语，后面不加“的”，应说“周末去打球”；“周末的”不能直接修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在山上度过了一只周末。", "corrected_sentence": "我们在山上度过了一个周末。", "error_description": "量词错误：“周末”应用量词“个”。“只”用于动物或单个小物件，不能修饰“周末”，应改为“一个周末”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a137e12-c3d7-4f96-b32b-42b82b4a2e7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
