INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坏人想出来骗人的办法。", "primary_collocate": null, "pronunciation": "piàn jú", "ipa": "pʰjɛn˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个骗局，你别上当。", "target_word": "骗局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人差点儿掉进坏人的骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察发现了这个骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想出一个骗局，让大家相信他们。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个骗局很简单，可是很多人没看出来。", "target_word": "骗局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就知道那是个骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友提醒我，这很可能是骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个又一个骗局，让他不再相信别人。", "target_word": "骗局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会看出网上的骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那场骗局让很多学生很难过。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "坏人想出来骗人的办法、计谋，泛指骗人的手段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗局", "is_correct": true, "explanation": "骗局：正确。坏人设下的骗人办法，与“别上当”的提醒相符。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：考卷是考试用的试卷，不会让人上当，与“别上当”的提醒矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不会让人上当，与“别上当”的提醒矛盾。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日不是需要防备的事，与“别上当”的提醒矛盾。"}], "explanations": {"骗局": "骗局：正确。坏人设下的骗人办法，与“别上当”的提醒相符。", "考卷": "语义：考卷是考试用的试卷，不会让人上当，与“别上当”的提醒矛盾。", "作业": "语义：作业是学习任务，不会让人上当，与“别上当”的提醒矛盾。", "生日": "语义：生日不是需要防备的事，与“别上当”的提醒矛盾。"}, "sentence_index": 0, "correct_answer": "骗局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们吃了一个骗局，想骗很多人。", "explanation": "这里应该用〈食物〉。骗局是骗人的圈套，不能吃；能吃的是食物。"}, {"text": "他们举行了一场骗局。", "explanation": "这里应该用〈比赛〉。骗局是骗人的圈套，不能举行；举行的是比赛。"}, {"text": "他洗了一个骗局。", "explanation": "这里应该用〈衣服〉。骗局不能洗，洗的是衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骗局", "is_correct": true, "explanation": "骗局：正确。“很可能是”与朋友的提醒语境相符，指可能的骗人圈套。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不是需要朋友提醒防范的东西，与语境不合。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：红绿灯是交通信号，与“很可能是”的提醒语境毫无关系，句意不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室设施，与“很可能是”的提醒语境毫无关系，句意不通。"}], "explanations": {"骗局": "骗局：正确。“很可能是”与朋友的提醒语境相符，指可能的骗人圈套。", "蛋糕": "语义：蛋糕是食物，不是需要朋友提醒防范的东西，与语境不合。", "红绿灯": "语义：红绿灯是交通信号，与“很可能是”的提醒语境毫无关系，句意不通。", "黑板": "语义：黑板是教室设施，与“很可能是”的提醒语境毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "骗局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校发放了一个骗局。", "explanation": "这里应该用〈奖学金〉。骗局是骗人的圈套，不能发放；学校发放的是奖学金。"}, {"text": "他唱了一个骗局。", "explanation": "这里应该用〈歌曲〉。骗局不能唱，唱的是歌曲。"}, {"text": "他挑选了一个骗局。", "explanation": "这里应该用〈礼物〉。骗局不能被挑选，挑选的是礼物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被一只骗局骗走了钱。", "corrected_sentence": "他被一场骗局骗走了钱。", "error_description": "错误：“一只骗局”，正确：“一场骗局”。“只”用于动物等，骗局要用“场”或“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们设下了一枚骗局，骗走了很多钱。", "corrected_sentence": "他们设下了一个骗局，骗走了很多钱。", "error_description": "错误：“一枚骗局”，正确：“一个骗局”。“枚”用于硬币、奖章等小物件，骗局应用“个”或“场”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
