INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为骗取钱财而设下的圈套。", "primary_collocate": null, "pronunciation": "piàn jú", "ipa": "pʰjɛn˥˩ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这个骗局让他损失了一万块钱。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里的人说我中奖了，这是骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她投了很多钱，才知道是骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有很多买东西的骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人把存款交给陌生人，这是个骗局。", "target_word": "骗局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子设下一个骗局，想骗走我们的钱。", "target_word": "骗局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说投资能赚大钱，其实是个骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察抓住了设骗局的人。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想快点儿赚钱，结果掉进了骗局。", "target_word": "骗局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种骗局专门骗不会用手机的老人。", "target_word": "骗局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "为骗取钱财而设下的圈套，如诈骗、假投资", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骗局", "is_correct": true, "explanation": "骗局：正确。为骗取钱财设下的圈套，与“损失了一万块钱”相符。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不会让人损失钱财，与“让他损失了一万块钱”矛盾。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是获得的钱，不会让人损失钱财，与句意矛盾。"}, {"text": "礼堂", "is_correct": false, "explanation": "语义：礼堂是建筑，不能让人损失钱财，与句意矛盾。"}], "explanations": {"骗局": "骗局：正确。为骗取钱财设下的圈套，与“损失了一万块钱”相符。", "礼物": "语义：礼物不会让人损失钱财，与“让他损失了一万块钱”矛盾。", "奖金": "语义：奖金是获得的钱，不会让人损失钱财，与句意矛盾。", "礼堂": "语义：礼堂是建筑，不能让人损失钱财，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "骗局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们煮了一个骗局，专门骗老人。", "explanation": "这里应该用〈汤〉。骗局是骗人的圈套，不能煮；能煮的是汤。"}, {"text": "他们举办了一场骗局。", "explanation": "这里应该用〈宴会〉。骗局是骗人的圈套，不能举办；举办的是宴会。"}, {"text": "歌手唱了一个骗局。", "explanation": "这里应该用〈歌曲〉。骗局不能唱，唱的是歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "骗局", "is_correct": true, "explanation": "骗局：正确。“其实是个”引出与“赚大钱”相反的真相，骗局正合语境。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：红绿灯是交通信号，与投资赚钱的话题毫无关系，句意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与投资赚钱的话题毫无关系，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，与投资的说法毫无关系，句意不通。"}], "explanations": {"骗局": "骗局：正确。“其实是个”引出与“赚大钱”相反的真相，骗局正合语境。", "红绿灯": "语义：红绿灯是交通信号，与投资赚钱的话题毫无关系，句意不通。", "蛋糕": "语义：蛋糕是食物，与投资赚钱的话题毫无关系，句意不通。", "冰箱": "语义：冰箱是家电，与投资的说法毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "骗局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蒸了一个骗局。", "explanation": "这里应该用〈馒头〉。骗局不能蒸，蒸的是馒头。"}, {"text": "老师提出了一个骗局。", "explanation": "这里应该用〈建议〉。骗局是骗人的圈套，不能提出；提出的是建议。"}, {"text": "他骑了一个骗局。", "explanation": "这里应该用〈自行车〉。骗局不能骑，骑的是自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被一幅骗局骗走了全部积蓄。", "corrected_sentence": "他被一场骗局骗走了全部积蓄。", "error_description": "错误：“一幅骗局”，正确：“一场骗局”。“幅”用于字画，骗局要用“场”或“个”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该提防这种的骗局。", "corrected_sentence": "我们应该提防这种骗局。", "error_description": "错误：“这种的骗局”，正确：“这种骗局”。指示词“这种”修饰名词时后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
