INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91237, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "运是把东西从这里搬到那里。", "primary_collocate": null, "pronunciation": "yùn", "ipa": "yn˥˩", "syllable_count": 1, "sentences": [{"text": "爸爸开着卡车去运沙子。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜是早上从乡下运来的。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把这批桌子运到新学校。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船正运着很多大米。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自行车把西瓜运到市场去卖。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥太小，大卡车运不过去。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明帮奶奶把水果运回了家。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他们运了五次东西。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把这些箱子运到车站。", "target_word": "运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里有船，可以用船运货。", "target_word": "运", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "運", "label": "繁体"}, {"form": "运着", "label": "体标（持续）"}, {"form": "运了", "label": "体标（完成）"}, {"form": "运送", "label": "复合"}], "register": "中性", "sense_fingerprint": "运：把东西从这里搬到那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78a3ef50-e145-4c82-a7e3-e5ad63c2ba2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91237, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。运（yùn）指把东西从这里搬到那里。"}, {"text": "允", "is_correct": false, "explanation": "允（yǔn）与运（yùn）声调不同，意思是允许、同意。"}, {"text": "匀", "is_correct": false, "explanation": "匀（yún）与运（yùn）声调不同，意思是均匀。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与运（yùn）声调相同，但韵母不同（in 与 un），意思是印刷、印记。"}], "explanations": {"运": "正确。运（yùn）指把东西从这里搬到那里。", "允": "允（yǔn）与运（yùn）声调不同，意思是允许、同意。", "匀": "匀（yún）与运（yùn）声调不同，意思是均匀。", "印": "印（yìn）与运（yùn）声调相同，但韵母不同（in 与 un），意思是印刷、印记。"}, "sentence_index": null, "correct_answer": "运"}, "level_3": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。“去运沙子”表示用卡车把沙子运走，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“去喝沙子”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，不能带“沙子”作宾语，句子不通。"}, {"text": "骑", "is_correct": false, "explanation": "配价：“骑”的宾语应是车马，不能以“沙子”作宾语，句子不成立。"}], "explanations": {"运": "正确。“去运沙子”表示用卡车把沙子运走，符合句意。", "喝": "搭配：“喝”的对象是饮品，不能说“去喝沙子”。", "写": "语义：“写”指书写，不能带“沙子”作宾语，句子不通。", "骑": "配价：“骑”的宾语应是车马，不能以“沙子”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我运着一个小袋子去超市。", "explanation": "这里应该用〈提〉。运多用于大批货物，手里提一个小袋子要用“提”。"}, {"text": "他把这封信运到了外地。", "explanation": "这里应该用〈寄〉。信件通过邮递寄出要用“寄”，“运”多指货物的运送。"}, {"text": "妈妈运着一碗汤走进屋。", "explanation": "这里应该用〈端〉。一碗汤要用“端”，“运”指大批量的运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91237, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。运（yùn）指把东西从这里搬到那里。"}, {"text": "云", "is_correct": false, "explanation": "云（yún）与运（yùn）声调不同，意思是云彩。"}, {"text": "陨", "is_correct": false, "explanation": "陨（yǔn）与运（yùn）声调不同，意思是坠落、陨落。"}, {"text": "玉", "is_correct": false, "explanation": "玉（yù）与运（yùn）只差韵尾 n，意思是玉石。"}], "explanations": {"运": "正确。运（yùn）指把东西从这里搬到那里。", "云": "云（yún）与运（yùn）声调不同，意思是云彩。", "陨": "陨（yǔn）与运（yùn）声调不同，意思是坠落、陨落。", "玉": "玉（yù）与运（yùn）只差韵尾 n，意思是玉石。"}, "sentence_index": null, "correct_answer": "运"}, "level_3": {"options": [{"text": "运", "is_correct": true, "explanation": "正确。“把水果运回了家”表示把水果运送回家，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不表示移动，“吃回了家”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与搬运水果无关，“唱回了家”不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，不能表示把水果带回家，句子不通。"}], "explanations": {"运": "正确。“把水果运回了家”表示把水果运送回家，符合句意。", "吃": "搭配：“吃”不表示移动，“吃回了家”不成立。", "唱": "语义：“唱”指发声歌唱，与搬运水果无关，“唱回了家”不通。", "咬": "语义：“咬”指用牙齿咬，不能表示把水果带回家，句子不通。"}, "sentence_index": 6, "correct_answer": "运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟运着一支笔去教室。", "explanation": "这里应该用〈拿〉。运指成批或大件货物的搬运，拿一支笔去教室要用“拿”。"}, {"text": "哥哥运着一条小狗去公园散步。", "explanation": "这里应该用〈牵〉。牵着小狗散步是牵引同行，不是运送货物，“运”不用于此。"}, {"text": "小女孩运着一个书包去学校。", "explanation": "这里应该用〈背〉。书包背在身上要用“背”，运多指成批货物的运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把三箱菜运了市场。", "corrected_sentence": "他把三箱菜运到了市场。", "error_description": "“运”后漏掉表示终点的补语“到”，应写成“运到了市场”；“运了市场”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这箱衣服运到着新家。", "corrected_sentence": "我们把这箱衣服运到了新家。", "error_description": "“运到”后的动态助词应用“了”表示完成，不能用“着”；“运到着新家”不通，应改为“运到了新家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97ab08f6-eff5-4844-8a61-698e5c570316') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
