INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为避免危险、保障人身或财产不受损害而进行的权衡与顾虑。", "primary_collocate": null, "pronunciation": "ān quán kǎo lǜ", "ipa": "an˥ tɕʰyɛn˧˥ kʰaʊ˨˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "出于安全考虑，银行晚上不开门。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司出于安全考虑，给每台电脑都设了密码。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥出于安全考虑，一次只能过十个人。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基于安全考虑，工厂里不能带火柴进去。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行前，安全考虑一定不能少。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们出于安全考虑，把贵重东西放进了保险箱。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校出于安全考虑，晚上六点就关了大门。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，这样做是出于安全考虑，不是为了省钱。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于安全考虑，飞机起飞前要检查很多次。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了价格，买车时也要有安全考虑。", "target_word": "安全考虑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "为保障人身财产不受损害的权衡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娱乐", "is_correct": false, "explanation": "语义：娱乐不能解释银行晚上不开门的理由，与句中的安全背景冲突。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“出于”后接的是原因，“身高”不能作为银行关门的原因，说不通。"}, {"text": "安全考虑", "is_correct": true, "explanation": "正确：“出于安全考虑”表示出于保障安全的权衡，与银行晚上不开门的原因相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不能成为银行晚上不开门的理由，句中的原因应是安全。"}], "explanations": {"娱乐": "语义：娱乐不能解释银行晚上不开门的理由，与句中的安全背景冲突。", "身高": "搭配：“出于”后接的是原因，“身高”不能作为银行关门的原因，说不通。", "安全考虑": "正确：“出于安全考虑”表示出于保障安全的权衡，与银行晚上不开门的原因相符。", "心情": "语义：心情不能成为银行晚上不开门的理由，句中的原因应是安全。"}, "sentence_index": 0, "correct_answer": "安全考虑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里装了很多安全考虑。", "explanation": "这里应该用〈安全措施〉。安全考虑是事前的权衡，装设的应是具体的安全措施。"}, {"text": "工厂门口挂着一块安全考虑牌。", "explanation": "这里应该用〈安全标志〉。牌子上写的是安全标志，“安全考虑”不能挂在门口。"}, {"text": "工厂要求大家树立安全考虑。", "explanation": "这里应该用〈安全意识〉。树立的是意识、观念；安全考虑是事前的权衡，不能被树立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色与学校关门的理由无关，句子表达的是安全原因。"}, {"text": "饮食", "is_correct": false, "explanation": "搭配：“出于”后接的原因不能是“饮食”，学校不会因饮食而关门，说不通。"}, {"text": "安全考虑", "is_correct": true, "explanation": "正确：“出于安全考虑”表示学校出于安全的权衡，与晚上六点关门的做法相符。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩不能解释学校晚上关门，与句中的安全语境冲突。"}], "explanations": {"颜色": "语义：颜色与学校关门的理由无关，句子表达的是安全原因。", "饮食": "搭配：“出于”后接的原因不能是“饮食”，学校不会因饮食而关门，说不通。", "安全考虑": "正确：“出于安全考虑”表示学校出于安全的权衡，与晚上六点关门的做法相符。", "成绩": "语义：成绩不能解释学校晚上关门，与句中的安全语境冲突。"}, "sentence_index": 6, "correct_answer": "安全考虑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开车要系安全考虑。", "explanation": "这里应该用〈安全带〉。系的是安全带；安全考虑是心里的权衡，不能系在身上。"}, {"text": "我们的安全考虑每天都来检查。", "explanation": "这里应该用〈安全员〉。能来检查的是人，“安全考虑”是抽象的权衡，不能来检查。"}, {"text": "违反安全考虑的工人会受到处罚。", "explanation": "这里应该用〈安全准则〉。违反的是规章、准则；安全考虑是事前的权衡，不是可以违反的规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出发前，我们做了一座安全考虑。", "corrected_sentence": "出发前，我们做了一番安全考虑。", "error_description": "量词错误：“座”不能用来计量“安全考虑”，应说“一番安全考虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "买房子时，也要有一座安全考虑。", "corrected_sentence": "买房子时，也要有一番安全考虑。", "error_description": "量词错误：“座”用于山、楼房等大型固定物，不能计量“安全考虑”；应说“一番安全考虑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
