INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91243, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "遗憾是事情没做成，心里有点难过。", "primary_collocate": null, "pronunciation": "yí hàn", "ipa": "i˧˥ xɑn˥˩", "syllable_count": 2, "sentences": [{"text": "你不能来，真遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很遗憾，我们没有赢这场比赛。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没考上大学，我觉得很遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么好的电影，你没看到，太遗憾了。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗憾的是，他没能来参加我的生日。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你要搬家，我感到很遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "票卖完了，大家都觉得很遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得太早，没看到孩子毕业，真遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没见到老朋友，心里有点遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很遗憾，没能和你们一起去旅行。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遗憾地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "事情没成功，心里觉得可惜难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗憾", "is_correct": true, "explanation": "“遗憾”表示事情没做成而感到可惜，与“你不能来”的语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示开心，与“你不能来”的失望语境相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌或样子，不能用来评价“你不能来”这件事。"}, {"text": "欣慰", "is_correct": false, "explanation": "语义：“欣慰”指事情如愿后的安慰，与“你不能来”的失望语境不符。"}], "explanations": {"遗憾": "“遗憾”表示事情没做成而感到可惜，与“你不能来”的语境相符。", "高兴": "语义：“高兴”表示开心，与“你不能来”的失望语境相反。", "漂亮": "体貌：“漂亮”形容外貌或样子，不能用来评价“你不能来”这件事。", "欣慰": "语义：“欣慰”指事情如愿后的安慰，与“你不能来”的失望语境不符。"}, "sentence_index": 0, "correct_answer": "遗憾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人把毕生积蓄捐给了学校，我很遗憾。", "explanation": "这里应该用〈感动〉。遗憾指没做成事情的可惜，不能用来表达对别人善举的感动。"}, {"text": "谢谢你的帮助，我很遗憾。", "explanation": "这里应该用〈感谢〉。遗憾指事情没做成的可惜，表达谢意应说“谢谢”或“感谢”，不能用“遗憾”。"}, {"text": "听说你考上了，我很遗憾。", "explanation": "这里应该用〈高兴〉。遗憾表示事情没成而难过，对别人的好消息不能用遗憾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗憾", "is_correct": true, "explanation": "“遗憾”表示事情没成而可惜，与票卖完、大家失望的语境相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”指风趣的谈吐，与票卖完的事实无关。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”只形容身高，不能用来评价售票的情况。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”指没有污物，与售票的情况不搭。"}], "explanations": {"遗憾": "“遗憾”表示事情没成而可惜，与票卖完、大家失望的语境相符。", "幽默": "语义：“幽默”指风趣的谈吐，与票卖完的事实无关。", "矮": "体貌：“矮”只形容身高，不能用来评价售票的情况。", "干净": "语义：“干净”指没有污物，与售票的情况不搭。"}, "sentence_index": 6, "correct_answer": "遗憾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子还没回家，我很遗憾。", "explanation": "这里应该用〈担心〉。遗憾是对没做成的事的可惜，不能表达对亲人安危的担忧。"}, {"text": "他突然出现在门口，我很遗憾。", "explanation": "这里应该用〈惊讶〉。遗憾不能表示突然看到某人时的惊讶。"}, {"text": "明天就要见面了，我很遗憾。", "explanation": "这里应该用〈期待〉。遗憾指已经没做成的可惜，不能表示对未来事情的盼望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遗憾的离开了这座城市。", "corrected_sentence": "他遗憾地离开了这座城市。", "error_description": "“遗憾”在动词前作状语时要用“地”，不能用“的”。错误形式是“遗憾的”，正确形式是“遗憾地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很遗憾的没能参加音乐会。", "corrected_sentence": "我很遗憾没能参加音乐会。", "error_description": "错误：“遗憾”后多加了“的”。“的”不能用在这里连接后面的“没能”，删去即正确：“我很遗憾没能参加音乐会。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
