INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "未能如愿而感到可惜、不满足。", "primary_collocate": null, "pronunciation": "yí hàn", "ipa": "i˧˥ xɑn˥˩", "syllable_count": 2, "sentences": [{"text": "没去成北京，是我一生的遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后一直留着一个遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没学会游泳，是我心里的遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行没去海边，留下了一点遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没能见到奶奶最后一面，成了永远的遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想弥补当年的遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没能拿到冠军，这是他职业生涯中的一个遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生总有一些遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小说没写完，成了一个大遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想给自己留下遗憾。", "target_word": "遗憾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个遗憾", "label": "量词"}], "register": "通用", "sense_fingerprint": "没能实现愿望而留在心里的可惜和不满足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a2a2b1e-4516-41bb-876d-84f61919da5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗憾", "is_correct": true, "explanation": "“遗憾”指未能如愿而留下的可惜，与没去成北京相符。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：“荣誉”是光彩的名声，与没去成北京的失落相反。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指快乐的感受，与没能实现的心愿不符。"}, {"text": "习惯", "is_correct": false, "explanation": "搭配：“一生的习惯”指长期的行为，不能用来说没去成北京。"}], "explanations": {"遗憾": "“遗憾”指未能如愿而留下的可惜，与没去成北京相符。", "荣誉": "语义：“荣誉”是光彩的名声，与没去成北京的失落相反。", "乐趣": "语义：“乐趣”指快乐的感受，与没能实现的心愿不符。", "习惯": "搭配：“一生的习惯”指长期的行为，不能用来说没去成北京。"}, "sentence_index": 0, "correct_answer": "遗憾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从书包里拿出一个遗憾，放在桌子上。", "explanation": "这里应该用〈苹果〉。遗憾是心里未能如愿的可惜，是抽象的，不能从书包里拿出来放在桌上。"}, {"text": "我们正在策划一个遗憾。", "explanation": "这里应该用〈活动〉。“策划”搭配活动、方案，遗憾是未能如愿的可惜，不能被策划。"}, {"text": "他犯了一个遗憾。", "explanation": "这里应该用〈错误〉。“犯”搭配错误，遗憾不能说被“犯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗憾", "is_correct": true, "explanation": "“遗憾”指未能如愿而感到可惜，与没拿到冠军相符。"}, {"text": "成就", "is_correct": false, "explanation": "语义：“成就”指取得的好成绩，与没拿到冠军的情况相反。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：“奖杯”是获奖的实物，与没能拿到冠军的情况矛盾。"}, {"text": "纪念", "is_correct": false, "explanation": "语义：“纪念”指留作回忆的东西或事情，没拿到冠军不是纪念，而是心里的可惜。"}], "explanations": {"遗憾": "“遗憾”指未能如愿而感到可惜，与没拿到冠军相符。", "成就": "语义：“成就”指取得的好成绩，与没拿到冠军的情况相反。", "奖杯": "语义：“奖杯”是获奖的实物，与没能拿到冠军的情况矛盾。", "纪念": "语义：“纪念”指留作回忆的东西或事情，没拿到冠军不是纪念，而是心里的可惜。"}, "sentence_index": 6, "correct_answer": "遗憾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次面试是一个难得的遗憾，我不想错过。", "explanation": "这里应该用〈机会〉。“错过”搭配机会，遗憾是已经发生的可惜，不能被错过。"}, {"text": "他在比赛中取得了一个遗憾。", "explanation": "这里应该用〈成绩〉。“取得”搭配成绩、胜利，遗憾不能被取得。"}, {"text": "他最近交了一个新遗憾。", "explanation": "这里应该用〈朋友〉。“交”搭配可以交往的人，遗憾不能被交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里一直装着一只遗憾。", "corrected_sentence": "他心里一直装着一个遗憾。", "error_description": "错误：“一只遗憾”，量词“只”不能用于“遗憾”。正确：“一个遗憾”。“只”多用于动物或成对物品，“遗憾”应搭配量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我心里一直有一个的遗憾。", "corrected_sentence": "我心里一直有一个遗憾。", "error_description": "“一个遗憾”之间不能加“的”，这里多出的“的”是错误。正确形式是“一个遗憾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f6a00e5-19a4-438f-93e4-98482f999c3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
