INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家具是家里用的桌子、椅子、床这些东西。", "primary_collocate": null, "pronunciation": "jiā jù", "ipa": "tɕja˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "我们刚搬家，还没有买新家具。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套家具是用木头做的。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的家具不多，但是很干净。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把旧家具搬到了小房间里。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的家具又好看又便宜。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子里要买床、桌子和别的家具。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里的家具都是白色的。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一件小家具放在窗户旁边。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的时候，大件家具要先搬上去。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个星期都擦一次家具。", "target_word": "家具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "旧家具", "label": "复合"}], "register": "中性", "sense_fingerprint": "家里用的桌椅床等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "搭配：“买”不能接“空气”，要买的应是可以购买的物品。"}, {"text": "家具", "is_correct": true, "explanation": "正确：“买新家具”指买新的桌椅床柜，符合刚搬家后还没买东西的情境。"}, {"text": "信息", "is_correct": false, "explanation": "语境：搬家后缺的是家用实物，“买新”的对象应是家具，“信息”与语境不合。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不是可以购买的东西，与“买新”的语义冲突。"}], "explanations": {"空气": "搭配：“买”不能接“空气”，要买的应是可以购买的物品。", "家具": "正确：“买新家具”指买新的桌椅床柜，符合刚搬家后还没买东西的情境。", "信息": "语境：搬家后缺的是家用实物，“买新”的对象应是家具，“信息”与语境不合。", "孩子": "语义：孩子不是可以购买的东西，与“买新”的语义冲突。"}, "sentence_index": 0, "correct_answer": "家具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的家具很和睦，经常一起吃饭。", "explanation": "这里应该用〈家庭〉。“和睦”形容家人之间的关系，家具是桌椅床柜等物件，不能和睦。"}, {"text": "洗衣机和冰箱都属于家具。", "explanation": "这里应该用〈电器〉。洗衣机、冰箱是家用电器，不属于家具。"}, {"text": "妈妈用家具做饭很方便。", "explanation": "这里应该用〈家电〉。电饭煲等家电可以用来做饭；家具是桌椅床柜，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白云", "is_correct": false, "explanation": "语义：白云在天上，不会出现在客厅里，与“客厅里的”冲突。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是客厅里的常见物品，与“客厅里的……都是白色的”说不通。"}, {"text": "家具", "is_correct": true, "explanation": "正确：“客厅里的家具”指客厅里的桌椅沙发等，颜色可以是白色，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不在客厅里，与句子的地点冲突。"}], "explanations": {"白云": "语义：白云在天上，不会出现在客厅里，与“客厅里的”冲突。", "墨水": "语义：墨水不是客厅里的常见物品，与“客厅里的……都是白色的”说不通。", "家具": "正确：“客厅里的家具”指客厅里的桌椅沙发等，颜色可以是白色，符合句意。", "天空": "语义：天空不在客厅里，与句子的地点冲突。"}, "sentence_index": 6, "correct_answer": "家具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们喜欢玩家具，每天都在房间里跑来跑去。", "explanation": "这里应该用〈玩具〉。玩耍用的是玩具；家具是桌椅床柜，不能用来玩。"}, {"text": "我的书包里装着家具。", "explanation": "这里应该用〈文具〉。书包里装的是笔、本子等文具，家具太大，装不进书包。"}, {"text": "她每天练家具，字写得越来越好。", "explanation": "家具是桌椅床柜等物件，不能被练习；“练”用于技能，如书法、乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在新家里买了几条家具。", "corrected_sentence": "我们在新家里买了几件家具。", "error_description": "量词错误：“条”用于细长的东西，家具应用“件”或“套”计量，应说“几件家具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新搬来的邻居买了几根家具。", "corrected_sentence": "新搬来的邻居买了几件家具。", "error_description": "量词错误：“根”用于细长的东西，家具应用“件”或“套”计量，应说“几件家具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
