INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "院长是管一个学院或医院的人。", "primary_collocate": null, "pronunciation": "yuàn zhǎng", "ipa": "ɥɛn˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家医院的院长是一位老医生。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院长在会上说，医院要买新机器。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学院的院长很年轻，只有四十岁。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院长请所有医生下午三点开会。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们都想见一见学院的院长。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从医生做到了院长，工作了三十年。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院长站在医院门口，欢迎新来的医生。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生有问题，可以去找学院的院长。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位院长管着三百多个医生和护士。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院的院长和老师们一起开了一个会。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副院长", "label": "复合词"}, {"form": "院長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "院长：医院或学院的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "院长", "is_correct": true, "explanation": "正确。“这家医院的院长”指医院的负责人，与句中“是一位老医生”相符。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”不是人，不能“是一位老医生”。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：“校长”指学校的负责人，医院不设“校长”，不能说“这家医院的校长”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是在校学习的人，不是医院的负责人，与“老医生”矛盾。"}], "explanations": {"院长": "正确。“这家医院的院长”指医院的负责人，与句中“是一位老医生”相符。", "电梯": "语义：“电梯”不是人，不能“是一位老医生”。", "校长": "搭配：“校长”指学校的负责人，医院不设“校长”，不能说“这家医院的校长”。", "学生": "语义：“学生”是在校学习的人，不是医院的负责人，与“老医生”矛盾。"}, "sentence_index": 0, "correct_answer": "院长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所小学的院长每天早上都在门口欢迎学生。", "explanation": "这里应该用〈校长〉。小学的负责人叫“校长”，院长管理的是学院或医院。"}, {"text": "儿科院长每周都来查房，很负责。", "explanation": "这里应该用〈主任〉。科室的负责人叫“主任”，院长管理的是学院或医院，不说“儿科院长”。"}, {"text": "这家医院有一把院长，很有名。", "explanation": "这里应该用〈位〉。“把”用于有柄的器具，指人要用“位”或“名”，不说“一把院长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院长", "is_correct": true, "explanation": "正确。“院长站在医院门口”符合院长迎接新同事的场景，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不是人，不能“站在门口”欢迎医生。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是人，不能站着欢迎新来的医生。"}, {"text": "班长", "is_correct": false, "explanation": "搭配：“班长”指班级的负责人，不用于医院，不说“班长站在医院门口”。"}], "explanations": {"院长": "正确。“院长站在医院门口”符合院长迎接新同事的场景，与句意相符。", "窗户": "语义：“窗户”不是人，不能“站在门口”欢迎医生。", "电脑": "语义：“电脑”不是人，不能站着欢迎新来的医生。", "班长": "搭配：“班长”指班级的负责人，不用于医院，不说“班长站在医院门口”。"}, "sentence_index": 6, "correct_answer": "院长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的院长很能干，每天都来车间。", "explanation": "这里应该用〈厂长〉。工厂的负责人叫“厂长”，院长用于学院或医院。"}, {"text": "这个协会的院长每月开一次会。", "explanation": "这里应该用〈会长〉。协会的负责人叫“会长”，院长用于学院或医院。"}, {"text": "这家公司的院长今年要去国外。", "explanation": "这里应该用〈董事长〉。公司的负责人一般称“董事长”或“总经理”，院长用于学院或医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院新来了一只院长。", "corrected_sentence": "这家医院新来了一位院长。", "error_description": "错误：“一只院长”，量词“只”用于动物或物件。正确：“一位院长”，指人要用“位”或“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位新来院长很年轻。", "corrected_sentence": "这位新来的院长很年轻。", "error_description": "错误：“新来院长”，定语是动词短语“新来”时，后面要加“的”。正确：“新来的院长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
