INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "医院、学院等机构的负责人。", "primary_collocate": null, "pronunciation": "yuàn zhǎng", "ipa": "ɥɛn˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "养老院的院长每天都会看看老人们。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院的院长在大会上说了今年的工作。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个研究院的院长是一位有名的科学家。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤儿院的院长对每个孩子都像妈妈一样。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是医院的院长，负责管理所有医生。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的院长想把医院办得更好。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院长说，明年学院要多招一百个学生。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当上了医院的院长，大家都为她高兴。", "target_word": "院长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所大学有十个学院，每个学院有一位院长。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这封信交给医院的院长。", "target_word": "院长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "副院长", "label": "复合词"}, {"form": "院長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "院长：医院、学院、研究院、法院等机构的负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c40d4862-37ee-47f3-905b-3a171e8ebee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "院长", "is_correct": true, "explanation": "正确。“养老院的院长”指养老院的负责人，与句中“看看老人们”的管理职责相符。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：“校长”指学校的负责人，养老院不说“校长”，不能说“养老院的校长”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是人，不能“看看老人们”。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“看看老人们”的关怀行为矛盾，也不可能担任养老院的负责人。"}], "explanations": {"院长": "正确。“养老院的院长”指养老院的负责人，与句中“看看老人们”的管理职责相符。", "校长": "搭配：“校长”指学校的负责人，养老院不说“校长”，不能说“养老院的校长”。", "厨房": "语义：“厨房”不是人，不能“看看老人们”。", "小偷": "语义：“小偷”与“看看老人们”的关怀行为矛盾，也不可能担任养老院的负责人。"}, "sentence_index": 0, "correct_answer": "院长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家书店的院长很有学问，每天都来店里。", "explanation": "这里应该用〈店长〉。书店的负责人叫“店长”，院长用于医院、学院、研究院等机构。"}, {"text": "这所小学的院长每周都来看学生。", "explanation": "这里应该用〈校长〉。小学的负责人叫“校长”，院长用于医院、学院、研究院等机构。"}, {"text": "这家养老院有一把院长，很有名。", "explanation": "这里应该用〈位〉。“把”用于有柄的器具，指人要用“位”或“名”，不说“一把院长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "院长", "is_correct": true, "explanation": "正确。“院长说”，院长负责学院事务，可以宣布招生计划，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是人，不能宣布招生计划，与句意矛盾。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不是人，不能宣布招生计划。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是人，不能宣布学院的招生计划，与句意矛盾。"}], "explanations": {"院长": "正确。“院长说”，院长负责学院事务，可以宣布招生计划，与句意相符。", "桌子": "语义：“桌子”不是人，不能宣布招生计划，与句意矛盾。", "椅子": "语义：“椅子”不是人，不能宣布招生计划。", "厨房": "语义：“厨房”不是人，不能宣布学院的招生计划，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "院长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的院长负责销售。", "explanation": "这里应该用〈经理〉。公司的负责人一般称“经理”或“总经理”，院长用于医院、学院、研究院等机构。"}, {"text": "这个市场监督局的院长很忙。", "explanation": "这里应该用〈局长〉。局的负责人叫“局长”，院长用于医院、学院、研究院等机构。"}, {"text": "这支球队的院长很厉害。", "explanation": "这里应该用〈队长〉。球队的负责人叫“队长”，院长用于医院、学院、研究院等机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个研究院新来了一只院长。", "corrected_sentence": "这个研究院新来了一位院长。", "error_description": "错误：“一只院长”，量词“只”用于动物或物件。正确：“一位院长”，指人要用“位”或“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位新来院长很和蔼。", "corrected_sentence": "这位新来的院长很和蔼。", "error_description": "错误：“新来院长”，定语是动词短语“新来”时，后面要加“的”。正确：“新来的院长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '364f77a8-ec68-4b8d-bf6e-18b6c1821b69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
