INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实业是做出东西来卖的工厂和生意。", "primary_collocate": null, "pronunciation": "shí yè", "ipa": "ʂɨ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他回到家乡，办起了自己的实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司从做小生意开始，慢慢发展成大实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把卖房子的钱都投到实业上了。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿受雇于人，想自己创办实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的实业有三家工厂和两家商店。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她父亲经营实业几十年，很少涉足股市。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的实业很发达，工厂很多。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿投机取巧，只想脚踏实地经营实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在上海办过实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行愿意借钱给做实业的人。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自己办的、生产东西来卖的工厂和生意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91253, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：实业指自己办的工厂和生意。"}, {"text": "事业", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是事业。"}, {"text": "失业", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失去工作。"}, {"text": "十月", "is_correct": false, "explanation": "yuè（第四声）与 yè（第四声）声调相同，只多了介音 u，意思是十月。"}], "explanations": {"实业": "正确：实业指自己办的工厂和生意。", "事业": "shì（第四声）与 shí（第二声）声调不同，意思是事业。", "失业": "shī（第一声）与 shí（第二声）声调不同，意思是失去工作。", "十月": "yuè（第四声）与 yè（第四声）声调相同，只多了介音 u，意思是十月。"}, "sentence_index": null, "correct_answer": "实业"}, "level_3": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：「实业」指自己办的工厂和生意，与「办起了自己的」相合。"}, {"text": "哲学", "is_correct": false, "explanation": "搭配：「办」能带「工厂、学校」这类机构名词，不能说「办哲学」。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能被「办起」来。"}, {"text": "时光", "is_correct": false, "explanation": "语义：「时光」指时间，不是可以创办的事业或企业。"}], "explanations": {"实业": "正确：「实业」指自己办的工厂和生意，与「办起了自己的」相合。", "哲学": "搭配：「办」能带「工厂、学校」这类机构名词，不能说「办哲学」。", "身材": "体貌：「身材」指人的体形，不能被「办起」来。", "时光": "语义：「时光」指时间，不是可以创办的事业或企业。"}, "sentence_index": 0, "correct_answer": "实业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一生都献给了革命实业。", "explanation": "这里应该用〈事业〉。「实业」指工业、商业等生产经营，「革命事业」是政治性的事业，不是生产经营。"}, {"text": "他一边打工，一边完成了实业。", "explanation": "这里应该用〈学业〉。「完成」通常搭配「学业」，「实业」指生产经营的行业，不能说「完成实业」。"}, {"text": "他找到了一份实业，每天准时上班。", "explanation": "这里应该用〈工作〉。「实业」指生产经营的行业，不指具体的工作岗位，找工作要说「工作」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：「实业」指工业、商业等生产经营，与「很发达，工厂很多」相合。"}, {"text": "草原", "is_correct": false, "explanation": "语义：「草原」是地貌，不能说「很发达」，也与「工厂很多」不协调。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「发达」不能修饰「寿命」，「寿命」也不能用「很发达」来描述。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：「面积」一般说「大」或「小」，不说「很发达」。"}], "explanations": {"实业": "正确：「实业」指工业、商业等生产经营，与「很发达，工厂很多」相合。", "草原": "语义：「草原」是地貌，不能说「很发达」，也与「工厂很多」不协调。", "寿命": "搭配：「发达」不能修饰「寿命」，「寿命」也不能用「很发达」来描述。", "面积": "搭配：「面积」一般说「大」或「小」，不说「很发达」。"}, "sentence_index": 6, "correct_answer": "实业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最大的实业是打篮球。", "explanation": "这里应该用〈爱好〉。「实业」指生产经营，不指业余爱好，说最大的爱好要用「爱好」。"}, {"text": "他的实业是律师。", "explanation": "这里应该用〈职业〉。「实业」是生产经营的领域，不指职业身份，律师是职业，不能说「他的实业是律师」。"}, {"text": "他过着平静的实业，很少出门。", "explanation": "这里应该用〈生活〉。「实业」指生产经营，不能说「过实业」，过的是生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在家乡实业起了一家工厂。", "corrected_sentence": "他在家乡办起了一家工厂。", "error_description": "词性错误：「实业」是名词，不能当动词用，不能说「实业起了一家工厂」，应改用动词「办」：「他在家乡办起了一家工厂」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他实业二十年了。", "corrected_sentence": "他从事实业二十年了。", "error_description": "动词漏掉了。「实业」前需要动词「从事」，只说「实业二十年」不成句，应为「他从事实业二十年了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
