INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指工业、商业、交通运输等生产经营事业。", "primary_collocate": null, "pronunciation": "shí yè", "ipa": "ʂɨ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "政府鼓励大家发展实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路、工厂、商店都属于实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百年前，很多人想用实业来帮助国家变强。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板的实业包括工厂、商店和船运。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的实业发展得很快。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了做官，转而投身实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的实业遍布全国。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让当时的实业受到了很大的损失。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行要支持实业，不能只想着赚快钱。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了管理以后，他回国经营实业。", "target_word": "实业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "工业、商业、交通运输等生产经营事业的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：实业指工业、商业等生产经营事业。"}, {"text": "事业", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是事业。"}, {"text": "失业", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失去工作。"}, {"text": "十月", "is_correct": false, "explanation": "yuè（第四声）与 yè（第四声）声调相同，只多了介音 u，意思是十月。"}], "explanations": {"实业": "正确：实业指工业、商业等生产经营事业。", "事业": "shì（第四声）与 shí（第二声）声调不同，意思是事业。", "失业": "shī（第一声）与 shí（第二声）声调不同，意思是失去工作。", "十月": "yuè（第四声）与 yè（第四声）声调相同，只多了介音 u，意思是十月。"}, "sentence_index": null, "correct_answer": "实业"}, "level_3": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：「实业」指生产经营事业，可以被「发展」。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「发展」不能带「寿命」，应说「延长寿命」。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「大海」是自然事物，不能被「发展」，「发展大海」不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「发展」不能带「脾气」，可以说「发脾气」，但不说「发展脾气」。"}], "explanations": {"实业": "正确：「实业」指生产经营事业，可以被「发展」。", "寿命": "搭配：「发展」不能带「寿命」，应说「延长寿命」。", "大海": "语义：「大海」是自然事物，不能被「发展」，「发展大海」不成立。", "脾气": "搭配：「发展」不能带「脾气」，可以说「发脾气」，但不说「发展脾气」。"}, "sentence_index": 0, "correct_answer": "实业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他读大学时成绩很好，顺利完成了实业。", "explanation": "这里应该用〈学业〉。「完成」通常搭配「学业」，「实业」指生产经营的事业，不能被「完成」。"}, {"text": "他最大的实业是下棋。", "explanation": "这里应该用〈爱好〉。「实业」指生产经营，不指业余爱好，说最大的爱好要用「爱好」。"}, {"text": "他把一生都献给了革命实业。", "explanation": "这里应该用〈事业〉。「革命事业」是政治性的事业，不是生产经营，「实业」不能用来指革命。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实业", "is_correct": true, "explanation": "正确：「实业」指生产经营的企业和事业，与「遍布全国」相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：「眼睛」是身体器官，不能说「遍布全国」。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是内心状态，不能像工厂、商店一样「遍布全国」。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是人的属性，不能分布在各地，「年龄遍布全国」不成立。"}], "explanations": {"实业": "正确：「实业」指生产经营的企业和事业，与「遍布全国」相合。", "眼睛": "体貌：「眼睛」是身体器官，不能说「遍布全国」。", "心情": "语义：「心情」是内心状态，不能像工厂、商店一样「遍布全国」。", "年龄": "语义：「年龄」是人的属性，不能分布在各地，「年龄遍布全国」不成立。"}, "sentence_index": 6, "correct_answer": "实业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找到了一份实业，每天准时上班。", "explanation": "这里应该用〈工作〉。「实业」指生产经营的领域，不指具体岗位，找工作要说「工作」。"}, {"text": "他的实业是律师。", "explanation": "这里应该用〈职业〉。「实业」不指职业身份，律师是职业，不能说「他的实业是律师」。"}, {"text": "他过着平静的实业，很少出门。", "explanation": "这里应该用〈生活〉。「实业」指生产经营，不能说「过实业」，过的是生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕业后打算实业。", "corrected_sentence": "他毕业后打算投身实业。", "error_description": "缺少动词：「实业」是名词，不能直接跟在「打算」后面作谓语，前面要加动词「投身」，应为「他毕业后打算投身实业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参观实业三十年了。", "corrected_sentence": "他经营实业三十年了。", "error_description": "动词用错。「实业」是生产经营的事业，应与「经营」搭配；「参观」通常针对可以看的场所或展览，一般不说「参观实业」。应为「他经营实业三十年了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
