INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91255, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一周是七天，从星期一到星期日。", "primary_collocate": null, "pronunciation": "yì zhōu", "ipa": "i˥˩ ʈʂou˥", "syllable_count": 2, "sentences": [{"text": "一周有七天。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一周从星期一开始。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一周我每天都很忙。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一周里我有三天上班。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一周上五天课。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一周工作五天。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下一周我们要考试。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一周的最后一天是星期日。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一周去两次图书馆。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一周的天气很好。", "target_word": "一周", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一週", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日历上从星期一到星期日的一个星期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一周", "is_correct": true, "explanation": "正确：一周是七天，与「有七天」相符。"}, {"text": "一天", "is_correct": false, "explanation": "语义：一天是二十四小时，不可能有七天。"}, {"text": "一旬", "is_correct": false, "explanation": "语域：旬是书面或古文用语，指十天，口语中不用于此，且与「有七天」矛盾。"}, {"text": "一小时", "is_correct": false, "explanation": "语义：一小时是六十分钟，不是七天，与「有七天」矛盾。"}], "explanations": {"一周": "正确：一周是七天，与「有七天」相符。", "一天": "语义：一天是二十四小时，不可能有七天。", "一旬": "语域：旬是书面或古文用语，指十天，口语中不用于此，且与「有七天」矛盾。", "一小时": "语义：一小时是六十分钟，不是七天，与「有七天」矛盾。"}, "sentence_index": 0, "correct_answer": "一周"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把一周放进了书包。", "explanation": "这里应该用〈时间〉。一周是一段时间，不是可以装进书包的实物；把它当作物体放进去，是误用了它的时段义。"}, {"text": "我一周八点起床。", "explanation": "这里应该用〈每天〉。一周表示一段时间，不能和几点钟这样的具体时刻连用来说起床时间；每天八点起床才通顺。"}, {"text": "我买了一周苹果。", "explanation": "这里应该用〈一袋〉。「周」不能作苹果的量词，买苹果要用「袋」「箱」等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一周", "is_correct": true, "explanation": "正确：下一周指接下来的七天，与「我们要考试」相符。"}, {"text": "一秒", "is_correct": false, "explanation": "语义：一秒太短，「下一秒我们要考试」与常理不合。"}, {"text": "一斤", "is_correct": false, "explanation": "语义：斤是重量单位，不是时间，「下一斤我们要考试」说不通。"}, {"text": "一刻", "is_correct": false, "explanation": "语义：「下一刻」指紧接着的那一瞬，用来安排考试时间太紧，不合常理。"}], "explanations": {"一周": "正确：下一周指接下来的七天，与「我们要考试」相符。", "一秒": "语义：一秒太短，「下一秒我们要考试」与常理不合。", "一斤": "语义：斤是重量单位，不是时间，「下一斤我们要考试」说不通。", "一刻": "语义：「下一刻」指紧接着的那一瞬，用来安排考试时间太紧，不合常理。"}, "sentence_index": 6, "correct_answer": "一周"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他晚上九点睡觉，一周九点睡觉。", "explanation": "这里应该用〈每晚〉。一周表示一段时间，不能和具体钟点连用来说睡觉时间；应说每晚九点睡觉。"}, {"text": "一周是星期一。", "explanation": "这里应该用〈今天〉。一周指七天的时间段，不能用来说明某一天是星期几。"}, {"text": "教室里有一周学生。", "explanation": "这里应该用〈一群〉。「周」不是学生的量词，形容许多人应用「群」或「班」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一周个跑三次步。", "corrected_sentence": "我一周跑三次步。", "error_description": "「一周」是表示频率的时间状语，「一周」后面不能加量词「个」，正确说法是「我一周跑三次步」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个一周天气很好。", "corrected_sentence": "这一周天气很好。", "error_description": "「一周」前面不能加量词「个」，应说「这一周」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
