INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前一次，不是这一次。", "primary_collocate": null, "pronunciation": "shàng huí", "ipa": "ʂɑŋ˥˩ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "上回你说的那家饭馆在哪儿？", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这回比上回考得好多了。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回我来的时候，这里还没有桥。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回是他请客，这回该我了。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回的作业，老师已经改完了。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记得上回你没带伞。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的菜比上回的好吃。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回开会，大家都迟到了。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回我们见面是在春天。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上回讲的故事，我还没听完。", "target_word": "上回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "与这一次相对的前一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4cfc666-8119-44d9-9cb1-da1cda7a5a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91257, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上回", "is_correct": true, "explanation": "正确：上回，指紧挨着这一次的前一次。"}, {"text": "商会", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，商会指工商业团体，意思不同。"}, {"text": "上会", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，上会指去参加会议，意思不同。"}, {"text": "伤毁", "is_correct": false, "explanation": "shānghuǐ（第一声、第三声）与 shànghuí（第四声、第二声）声调不同。伤毁指损伤毁坏，意思不同。"}, {"text": "上位", "is_correct": false, "explanation": "wèi 与 huí 的声母和声调都不同。上位指较高的地位，意思不同。"}], "explanations": {"上回": "正确：上回，指紧挨着这一次的前一次。", "商会": "shāng（第一声）与 shàng（第四声）声调不同，商会指工商业团体，意思不同。", "上会": "huì（第四声）与 huí（第二声）声调不同，上会指去参加会议，意思不同。", "伤毁": "shānghuǐ（第一声、第三声）与 shànghuí（第四声、第二声）声调不同。伤毁指损伤毁坏，意思不同。", "上位": "wèi 与 huí 的声母和声调都不同。上位指较高的地位，意思不同。"}, "sentence_index": null, "correct_answer": "上回"}, "level_3": {"options": [{"text": "上回", "is_correct": true, "explanation": "正确：“上回”指前一次，与“你说的那家饭馆”所指已发生的事相符。"}, {"text": "下回", "is_correct": false, "explanation": "语义：“下回”指以后的一次，与“你说的”这一已经发生的事相矛盾。"}, {"text": "身材", "is_correct": false, "explanation": "搭配：“身材”指人的体形，不能与“你说的那家饭馆”搭配。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不表示时间，无法说明“你说的那家饭馆”是什么时候被提到的。"}], "explanations": {"上回": "正确：“上回”指前一次，与“你说的那家饭馆”所指已发生的事相符。", "下回": "语义：“下回”指以后的一次，与“你说的”这一已经发生的事相矛盾。", "身材": "搭配：“身材”指人的体形，不能与“你说的那家饭馆”搭配。", "电影": "语义：“电影”不表示时间，无法说明“你说的那家饭馆”是什么时候被提到的。"}, "sentence_index": 0, "correct_answer": "上回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上回我常来这里吃饭。", "explanation": "这里应该用〈以前〉。上回只指紧挨着这一次的那一次，不能用来说过去经常发生的事。"}, {"text": "上回这座桥有三百年的历史。", "explanation": "这里应该用〈以往〉。上回指紧挨着这一次的那一次，不能用来说事物长期具有的状况。"}, {"text": "上回你再来吧。", "explanation": "这里应该用〈下回〉。上回指已经过去的一次，不能用于邀请对方将来再来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上回", "is_correct": true, "explanation": "正确：“上回”指前一次，与“这次的菜”形成比较，句子成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“钢琴”是乐器，不能与“菜”构成可比较的对象。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体部位，不能与“这次的菜”比较。"}, {"text": "背景", "is_correct": false, "explanation": "搭配：“背景”指事物的背后环境，不能作为菜的比较对象。"}], "explanations": {"上回": "正确：“上回”指前一次，与“这次的菜”形成比较，句子成立。", "钢琴": "搭配：“钢琴”是乐器，不能与“菜”构成可比较的对象。", "眼睛": "搭配：“眼睛”是身体部位，不能与“这次的菜”比较。", "背景": "搭配：“背景”指事物的背后环境，不能作为菜的比较对象。"}, "sentence_index": 6, "correct_answer": "上回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上回三年他一直在国外。", "explanation": "这里应该用〈过去〉。上回指紧挨着这一次的那一次，不能用来指一段时间。"}, {"text": "上回一定来看看我。", "explanation": "这里应该用〈下次〉。上回指已经过去的那一次，不能用于约定将来的事。"}, {"text": "上回这里是一片农田。", "explanation": "这里应该用〈从前〉。上回指某一次的事件，不能用来描述过去长期的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上回的在超市见到他。", "corrected_sentence": "我上回在超市见到他。", "error_description": "错误：“我上回的在超市见到他”。“上回”作时间状语，后面不能加“的”，应说“我上回在超市见到他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很上回我没带伞，这次带了。", "corrected_sentence": "上回我没带伞，这次带了。", "error_description": "错误：“很上回我没带伞”。“上回”是时间词，不能受“很”修饰，应说“上回我没带伞，这次带了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ed85737-82a6-4a39-a84e-ad3be8e0929b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
