INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "少将是军队里很高的一种官职。", "primary_collocate": null, "pronunciation": "shào jiàng", "ipa": "ʂau̯˥˩ tɕi̯ɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在军队里是一位少将。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位少将带着士兵去了山区。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将的工作很重要，也很辛苦。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了少将以后，回家的时间更少了。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时是军队里的少将。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将给士兵们讲了一个故事。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当少将，所以每天锻炼身体。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位少将在会上说了几句话。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将坐车去军营看士兵。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的少将走得很快。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位少将", "label": "量词"}, {"form": "少將", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军队里很高的官职、担任这种官职的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91259, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少将", "is_correct": true, "explanation": "正确答案，指军队里很高的官职。"}, {"text": "上将", "is_correct": false, "explanation": "shàng 与 shào 韵母不同（ang 与 ao），声调相同（第四声），意思是军衔，高于中将。"}, {"text": "少见", "is_correct": false, "explanation": "少见读 shǎo jiàn，第一个字是第三声（shǎo，不是 shào），第二个字 jiàn 与 jiàng 韵母不同，意思是很少见到。"}, {"text": "小将", "is_correct": false, "explanation": "小将读 xiǎo jiàng，声母 x 与 sh 不同，第一个字是第三声，意思是年轻的将领或年轻有为的人，不是军衔。"}], "explanations": {"少将": "正确答案，指军队里很高的官职。", "上将": "shàng 与 shào 韵母不同（ang 与 ao），声调相同（第四声），意思是军衔，高于中将。", "少见": "少见读 shǎo jiàn，第一个字是第三声（shǎo，不是 shào），第二个字 jiàn 与 jiàng 韵母不同，意思是很少见到。", "小将": "小将读 xiǎo jiàng，声母 x 与 sh 不同，第一个字是第三声，意思是年轻的将领或年轻有为的人，不是军衔。"}, "sentence_index": null, "correct_answer": "少将"}, "level_3": {"options": [{"text": "少将", "is_correct": true, "explanation": "正确答案，“他在军队里是一位少将”指担任这一官职的人，与句意相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不是军队里的官职，与“在军队里是一位”冲突。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“房子”。"}, {"text": "青蛙", "is_correct": false, "explanation": "语义：青蛙不能在军队里担任官职，句意不通。"}], "explanations": {"少将": "正确答案，“他在军队里是一位少将”指担任这一官职的人，与句意相符。", "小猫": "语义：小猫不是军队里的官职，与“在军队里是一位”冲突。", "房子": "搭配：量词“位”只用于人，不能修饰“房子”。", "青蛙": "语义：青蛙不能在军队里担任官职，句意不通。"}, "sentence_index": 0, "correct_answer": "少将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在军营里当了少将，负责做饭。", "explanation": "这里应该用〈炊事员〉。“少将”是军衔，军营里做饭的职务要说“炊事员”。"}, {"text": "他在球场上当了少将，专门负责守门。", "explanation": "这里应该用〈门将〉。“少将”是军衔，球场上守门的职务要说“门将”。"}, {"text": "我在超市里认识了一个少将，他是收银员。", "explanation": "这里应该用〈收银员〉。“少将”是军衔，超市里的工作要说“收银员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：“当”要求能担任的身份，窗户无法担任，与“我想当”冲突。"}, {"text": "少将", "is_correct": true, "explanation": "正确答案，“我想当少将”表示想担任这一官职，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被当作身份或职业，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“当”后接身份或职业，不能说“当石头”。"}], "explanations": {"窗户": "语义：“当”要求能担任的身份，窗户无法担任，与“我想当”冲突。", "少将": "正确答案，“我想当少将”表示想担任这一官职，与句意相符。", "空气": "语义：空气不能被当作身份或职业，句意不通。", "石头": "搭配：“当”后接身份或职业，不能说“当石头”。"}, "sentence_index": 6, "correct_answer": "少将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班来了一个少将，他负责给同学们讲笑话。", "explanation": "这里应该用〈讲笑话的人〉。“少将”是军衔，指讲笑话的职业时不能用“少将”。"}, {"text": "那位少将在操场上跑步，他是新来的体育老师。", "explanation": "这里应该用〈体育老师〉。“少将”是军衔，指学校里的教师职务要说“体育老师”。"}, {"text": "饭店里的少将每天给客人做菜。", "explanation": "这里应该用〈厨师〉。“少将”是军衔，在饭店给客人做菜的职业要说“厨师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想当了少将，所以很努力。", "corrected_sentence": "他想当少将，所以很努力。", "error_description": "错误在“了”。“想”表示打算，后面的“当”不能加“了”，应说“想当少将”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只少将的话很有道理。", "corrected_sentence": "那位少将的话很有道理。", "error_description": "错误在量词。「只」多用于动物或某些物品，不能指人；指称「少将」这样的人应说「那位少将」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
