INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军衔名，位于中将之下、大校之上的将官。", "primary_collocate": null, "pronunciation": "shào jiàng", "ipa": "ʂau̯˥˩ tɕi̯ɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他今年升成了少将。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将的军衔比大校高。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位少将在军队里工作了三十年。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是中将的下属，是一位少将。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王少将昨天来我们学校讲话。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少将比中将低一级。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位少将穿着绿色的军装。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从大校升为少将，用了十年。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的叔叔是少将，工作很忙。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里的少将不多，他很了不起。", "target_word": "少将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位少将", "label": "量词"}, {"form": "少將", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军衔，中将之下、大校之上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少将", "is_correct": true, "explanation": "正确答案，指军衔名，位于中将之下、大校之上。"}, {"text": "上将", "is_correct": false, "explanation": "shàng 与 shào 韵母不同（ang 与 ao），声调相同（第四声），意思是军衔，高于中将。"}, {"text": "少见", "is_correct": false, "explanation": "少见读 shǎo jiàn，第一个字是第三声（shǎo，不是 shào），第二个字 jiàn 与 jiàng 韵母不同，意思是很少见到。"}, {"text": "小将", "is_correct": false, "explanation": "小将读 xiǎo jiàng，声母 x 与 sh 不同，第一个字是第三声，意思是年轻的将领或年轻有为的人，不是军衔。"}], "explanations": {"少将": "正确答案，指军衔名，位于中将之下、大校之上。", "上将": "shàng 与 shào 韵母不同（ang 与 ao），声调相同（第四声），意思是军衔，高于中将。", "少见": "少见读 shǎo jiàn，第一个字是第三声（shǎo，不是 shào），第二个字 jiàn 与 jiàng 韵母不同，意思是很少见到。", "小将": "小将读 xiǎo jiàng，声母 x 与 sh 不同，第一个字是第三声，意思是年轻的将领或年轻有为的人，不是军衔。"}, "sentence_index": null, "correct_answer": "少将"}, "level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：“升成了”需要接职务或等级，“春天”不能作为职级，句子不通。"}, {"text": "少将", "is_correct": true, "explanation": "正确答案，“升成了少将”表示晋升为这一军衔，与句意相符。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“升”说的是职务或等级，不能用来指人的体形。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是任何职务或等级，与“升成了”搭配不通。"}], "explanations": {"春天": "语义：“升成了”需要接职务或等级，“春天”不能作为职级，句子不通。", "少将": "正确答案，“升成了少将”表示晋升为这一军衔，与句意相符。", "胖子": "体貌：“升”说的是职务或等级，不能用来指人的体形。", "石头": "语义：石头不是任何职务或等级，与“升成了”搭配不通。"}, "sentence_index": 0, "correct_answer": "少将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工厂里当了少将，每天负责检查产品。", "explanation": "这里应该用〈质检员〉。“少将”是军衔，工厂里检查产品的职务要说“质检员”。"}, {"text": "他在医院里当了少将，专门给病人看病。", "explanation": "这里应该用〈医生〉。“少将”是军衔，不指医院里的职业，应说“医生”。"}, {"text": "我爸爸在学校里当了少将，教我们体育。", "explanation": "这里应该用〈体育老师〉。“少将”是军衔，学校里的职业要说“体育老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大熊猫", "is_correct": false, "explanation": "语义：大熊猫不会穿军装，与“那位……穿着绿色的军装”冲突。"}, {"text": "少将", "is_correct": true, "explanation": "正确答案，“少将”指人，可以穿军装，与句意相符。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能修饰“玩具”。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果不会穿军装，句意不通。"}], "explanations": {"大熊猫": "语义：大熊猫不会穿军装，与“那位……穿着绿色的军装”冲突。", "少将": "正确答案，“少将”指人，可以穿军装，与句意相符。", "玩具": "搭配：量词“位”只用于人，不能修饰“玩具”。", "苹果": "语义：苹果不会穿军装，句意不通。"}, "sentence_index": 6, "correct_answer": "少将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的少将很能干，每天都帮老师发作业。", "explanation": "这里应该用〈课代表〉。“少将”是军衔，班里帮老师发作业的职务要说“课代表”。"}, {"text": "他在车间里当少将，负责安排生产。", "explanation": "这里应该用〈车间主任〉。“少将”是军衔，工厂里的管理职务要说“车间主任”。"}, {"text": "他在农场里当少将，每天负责喂猪。", "explanation": "这里应该用〈饲养员〉。“少将”是军衔，农场里的工作要说“饲养员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直少将，很受大家尊敬。", "corrected_sentence": "他一直是少将，很受大家尊敬。", "error_description": "错误在系词。“少将”作谓语时前面要加“是”，应说“他一直是少将”，不能省略“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只少将很了不起，大家都佩服他。", "corrected_sentence": "这位少将很了不起，大家都佩服他。", "error_description": "错误在量词。「只」多用于动物或某些物品，不能指人；指称「少将」这样的人应说「这位少将」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
