INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "一组配合成整体的东西。", "primary_collocate": null, "pronunciation": "yí tào", "ipa": "i˧˥ tʰɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我新买了一套茶具，一共六个杯子。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给孩子买了一套彩色笔。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里有一套很有名的小说，一共五本。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈穿着一套红色的衣服去参加婚礼。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店换了一套新的餐具。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家有一套老沙发。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一套新课本放进了书包。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给每人一套练习题。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一套深色的西装去面试。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一套工具里有锤子和钳子。", "target_word": "一套", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一整套", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：配合成整体的一组东西，如茶具、衣服、工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6fc0c8a-a2f4-4258-9b79-7225f30965f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确答案：一套（yí tào），指配成整体的一组东西。"}, {"text": "椅套", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。"}, {"text": "一道", "is_correct": false, "explanation": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。"}, {"text": "一趟", "is_correct": false, "explanation": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}], "explanations": {"一套": "正确答案：一套（yí tào），指配成整体的一组东西。", "椅套": "yǐ（第三声）与 yí（第二声）声调不同，椅套指椅子上的罩子。", "一道": "tào 与 dào 声母不同：t 送气，d 不送气，一道意思是一起或一条路。", "一趟": "tào 与 tàng 韵母不同（ao 与 ang），一趟指一次往返，是量词。"}, "sentence_index": null, "correct_answer": "一套"}, "level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指成组配合的一整套茶具，与后文“一共六个杯子”相符。"}, {"text": "一对", "is_correct": false, "explanation": "搭配：“对”指成双的东西，六个杯子的一整套茶具不是一对。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对物中的一个，不用于计量茶具。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握的器具，成套的茶具不用“把”计量。"}], "explanations": {"一套": "正确：一套指成组配合的一整套茶具，与后文“一共六个杯子”相符。", "一对": "搭配：“对”指成双的东西，六个杯子的一整套茶具不是一对。", "一只": "搭配：“只”用于动物或成对物中的一个，不用于计量茶具。", "一把": "搭配：“把”用于有柄或可握的器具，成套的茶具不用“把”计量。"}, "sentence_index": 0, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里走着一套小鸡，都在地上找虫子吃。", "explanation": "这里应该用〈一群〉。“一套”指配成整体的一组东西，成群的小鸡要说“一群”。"}, {"text": "我渴了，就喝了一套水。", "explanation": "这里应该用〈一杯〉。“一套”用于配成整体的成组物品，水要用“一杯”计量。"}, {"text": "妈妈去超市买了一套大米。", "explanation": "这里应该用〈一袋〉。“一套”不用于散装的粮食，大米要说“一袋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一套", "is_correct": true, "explanation": "正确：一套指成套的课本，与“放进了书包”的语境相符。"}, {"text": "一块", "is_correct": false, "explanation": "搭配：“块”用于块状的东西，不用于成套的课本。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”用于平而薄的东西，课本不能用“片”计量。"}, {"text": "一张", "is_correct": false, "explanation": "语义：“张”指平面的纸、床等，成册的课本不是一张纸，与“一套”的成组意思不合。"}], "explanations": {"一套": "正确：一套指成套的课本，与“放进了书包”的语境相符。", "一块": "搭配：“块”用于块状的东西，不用于成套的课本。", "一片": "搭配：“片”用于平而薄的东西，课本不能用“片”计量。", "一张": "语义：“张”指平面的纸、床等，成册的课本不是一张纸，与“一套”的成组意思不合。"}, "sentence_index": 6, "correct_answer": "一套"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "仓库里运来了一套砖，堆在门口。", "explanation": "这里应该用〈一批〉。“一套”指配成整体的一组东西，成批运来的散砖要说“一批”。"}, {"text": "枝头挂着一套红枣，红彤彤的。", "explanation": "这里应该用〈一串〉。“一套”指配成整体的一组东西，挂成一串的红枣要说“一串”。"}, {"text": "院子里堆着一套垃圾，都没人收。", "explanation": "这里应该用〈一堆〉。“一套”指配成整体的一组东西，随手堆在一起的垃圾要说“一堆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一套的运动服。", "corrected_sentence": "妈妈给我买了一套运动服。", "error_description": "错误形式：一套的运动服；正确形式：一套运动服。“一套”作数量定语时后面不加“的”，应直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给每个学生发了一套一套练习册。", "corrected_sentence": "老师给每个学生发了一套练习册。", "error_description": "重复错误：错误形式是“一套一套练习册”，正确形式是“一套练习册”。“一套”只出现一次，多写一个“一套”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
