INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91264, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "放假或休假的时期。", "primary_collocate": null, "pronunciation": "jià qī", "ipa": "tɕjä⁵¹ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "假期结束了，我们回学校。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个假期你想去哪儿玩？", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他利用假期学了游泳。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节假期一共有七天。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期里，我每天都早起锻炼。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给了我们一个月的假期。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段假期我一直在家陪父母。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期太短，我们哪儿也没去。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的假期安排好了吗？", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把假期用在旅行上。", "target_word": "假期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "段", "label": "量词"}], "register": "通用", "sense_fingerprint": "放假或休假的一段时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假期", "is_correct": true, "explanation": "假期（jià qī）指放假或休假的一段时期，就是本句的意思。"}, {"text": "架起", "is_correct": false, "explanation": "架起（jiàqǐ）与假期的第二个音节声调不同（第三声与第一声），意思是把东西支起来。"}, {"text": "下期", "is_correct": false, "explanation": "下期（xiàqī）与假期的声母不同（x 与 j），意思是下一个时期。"}, {"text": "借期", "is_correct": false, "explanation": "借期（jièqī）与假期的韵母不同（e 与 a），意思是借用的期限。"}], "explanations": {"假期": "假期（jià qī）指放假或休假的一段时期，就是本句的意思。", "架起": "架起（jiàqǐ）与假期的第二个音节声调不同（第三声与第一声），意思是把东西支起来。", "下期": "下期（xiàqī）与假期的声母不同（x 与 j），意思是下一个时期。", "借期": "借期（jièqī）与假期的韵母不同（e 与 a），意思是借用的期限。"}, "sentence_index": null, "correct_answer": "假期"}, "level_3": {"options": [{"text": "假期", "is_correct": true, "explanation": "假期：指一段休假时间，与“结束”和“回学校”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“结束”不能接颜色，句子不通。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是地点，不是一段时间，不能说结束了。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”一般说变化或好转，不说结束，句子不通。"}], "explanations": {"假期": "假期：指一段休假时间，与“结束”和“回学校”搭配，符合句意。", "颜色": "搭配：“结束”不能接颜色，句子不通。", "宿舍": "语义：宿舍是地点，不是一段时间，不能说结束了。", "天气": "搭配：“天气”一般说变化或好转，不说结束，句子不通。"}, "sentence_index": 0, "correct_answer": "假期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在海边度过了一条假期。", "explanation": "这里应该用〈个〉。假期是一段时间，常用量词是“个”或“段”，“条”用于长形的东西。"}, {"text": "这个假期是我的生日。", "explanation": "这里应该用〈这一天〉。假期指一段休假时间，不能用来指某一天的生日。"}, {"text": "我们明天假期吧。", "explanation": "这里应该用〈放假〉。假期是名词，表示休假时间；表示动作要用放假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假期", "is_correct": true, "explanation": "假期：指一段休假时间，“这段假期”与“在家陪父母”相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是场所，不是一段时间，不能说“这段医院”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是物品，不指时间段，不能用“这段”修饰。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“这段”不能修饰脾气，句子不通。"}], "explanations": {"假期": "假期：指一段休假时间，“这段假期”与“在家陪父母”相符。", "医院": "语义：医院是场所，不是一段时间，不能说“这段医院”。", "电脑": "语义：电脑是物品，不指时间段，不能用“这段”修饰。", "脾气": "搭配：“这段”不能修饰脾气，句子不通。"}, "sentence_index": 6, "correct_answer": "假期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山上度过了一块假期。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，假期应用“个”或“段”。"}, {"text": "我们下个星期一起假期吧。", "explanation": "这里应该用〈放假〉。假期是名词，指一段休假时间，不能当动词用；表示动作要说放假。"}, {"text": "我们在湖边度过了一张假期。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，假期应用“个”或“段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海边过了一只愉快的假期。", "corrected_sentence": "我们在海边过了一个愉快的假期。", "error_description": "量词错误：假期应用量词“个”或“段”，“只”用于动物或成对的东西，不能修饰假期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在家里过了一张安静的假期。", "corrected_sentence": "我们在家里过了一个安静的假期。", "error_description": "量词错误：假期应用量词“个”或“段”，“张”用于纸张等平面的东西，不能修饰假期。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
