INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91265, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一定要表示必须这样做，不能不做。", "primary_collocate": null, "pronunciation": "yí dìng yào", "ipa": "i˧˥ tiŋ˥˩ jɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "过马路时，一定要看红绿灯。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病了，你一定要去看医生。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前一定要关好门窗。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃药以前，一定要先看说明书。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候一定要系安全带。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天考试，你一定要带身份证。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上很滑，大家一定要小心。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前一定要给手机充电。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了那儿，一定要给我打电话。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭前一定要洗手。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "提醒或要求别人必须照做，表示不做不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一定要", "is_correct": true, "explanation": "语义：一定要表示必须照做，与“过马路时”的提醒语境相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：已经表示已经发生，与泛指的提醒语境冲突。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：竟然表示出乎意料，与这里的提醒语气不符。"}, {"text": "切莫", "is_correct": false, "explanation": "语域：切莫是书面用语，表示禁止，与这句口语提醒不协调，句意也相反。"}], "explanations": {"一定要": "语义：一定要表示必须照做，与“过马路时”的提醒语境相符。", "已经": "语义：已经表示已经发生，与泛指的提醒语境冲突。", "竟然": "语义：竟然表示出乎意料，与这里的提醒语气不符。", "切莫": "语域：切莫是书面用语，表示禁止，与这句口语提醒不协调，句意也相反。"}, "sentence_index": 0, "correct_answer": "一定要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树叶在冬天一定要变黄。", "explanation": "这里应该用〈一定会〉。一定要表示必须这样做，用于人的要求或决心；自然现象的必然结果应说“一定会”，“一定要变黄”不通。"}, {"text": "昨天的雨一定要下过。", "explanation": "这里应该用〈肯定〉。一定要表示必须这样做，用于要求或决心；推断已经发生的事应说“肯定”，“一定要下过”不通。"}, {"text": "他年轻时一定要当过兵。", "explanation": "这里应该用〈想必〉。一定要表示必须这样做，用于要求或决心；推测过去的情况应说“想必”，“一定要当过兵”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一定要", "is_correct": true, "explanation": "语义：一定要表示必须照做，与“路上很滑”所提示的注意义务相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不常发生，与“路上很滑”所要求的持续注意不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：曾经表示过去的经历，与“路上很滑”这一当下的提醒不符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：从不表示从来没有，与“要小心”的要求相矛盾。"}], "explanations": {"一定要": "语义：一定要表示必须照做，与“路上很滑”所提示的注意义务相符。", "偶尔": "语义：偶尔表示不常发生，与“路上很滑”所要求的持续注意不合。", "曾经": "语义：曾经表示过去的经历，与“路上很滑”这一当下的提醒不符。", "从不": "语义：从不表示从来没有，与“要小心”的要求相矛盾。"}, "sentence_index": 6, "correct_answer": "一定要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "看样子，他一定要有四十岁了。", "explanation": "这里应该用〈大概〉。一定要表示必须这样做，用于要求或决心；估计年龄应说“大概”，“一定要有四十岁”不通。"}, {"text": "那个湖一定要比海小。", "explanation": "这里应该用〈必定〉。一定要表示必须这样做，不能不做；对事实作判断应说“必定”，“一定要比海小”不通。"}, {"text": "这块石头一定要有三百岁。", "explanation": "这里应该用〈大约〉。一定要表示必须这样做，用于要求或决心；估计事物的年龄应说“大约”，“一定要有三百岁”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次出差你一定要带很护照。", "corrected_sentence": "这次出差你一定要带好护照。", "error_description": "“很”是程度副词，不能直接修饰名词“护照”；此处应使用结果补语“好”，即“带好护照”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出门以前，你一定要带给钥匙。", "corrected_sentence": "出门以前，你一定要带好钥匙。", "error_description": "“带”后的补语应为“好”，表示备齐；“带给”的“给”需要接受者，“带给钥匙”不通，应说“一定要带好钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
