INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91266, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示说话人下定决心、态度坚决，无论如何都要做到。", "primary_collocate": null, "pronunciation": "yí dìng yào", "ipa": "i˧˥ tiŋ˥˩ jɑʊ˥˩", "syllable_count": 3, "sentences": [{"text": "我已经决定了，明天一定要去。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管多难，我一定要学会游泳。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说过，这次比赛一定要赢。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都说不行，他还是一定要试一试。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一定要把这本书看完。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一定要找到丢了的那只小狗。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下了决心，一定要考上大学。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，她一定要亲眼看看我的新学校。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业，我一定要做完才睡觉。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我的梦想，我一定要实现它。", "target_word": "一定要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示说话人下定决心、态度坚决，一定要做成某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一定要", "is_correct": true, "explanation": "语义：一定要表示说话人坚决要去，与“我已经决定了”相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：已经表示已经发生，与“明天”这样的将来时间冲突。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：竟然表示出乎意料，与“已经决定了”的坚决态度相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "搭配：总是用于反复出现的动作，不能用于“明天去”这样的一次性行为。"}], "explanations": {"一定要": "语义：一定要表示说话人坚决要去，与“我已经决定了”相符。", "已经": "语义：已经表示已经发生，与“明天”这样的将来时间冲突。", "竟然": "语义：竟然表示出乎意料，与“已经决定了”的坚决态度相矛盾。", "总是": "搭配：总是用于反复出现的动作，不能用于“明天去”这样的一次性行为。"}, "sentence_index": 0, "correct_answer": "一定要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天一定要来过这里。", "explanation": "这里应该用〈肯定〉。一定要表示必须、坚决，用于要求别人或下定决心；推断已经发生的事应说“肯定”，“一定要来过”不通。"}, {"text": "水在零度以下一定要结冰。", "explanation": "这里应该用〈一定会〉。一定要表示必须、坚决，用于要求或决心；说明自然规律应说“一定会”，“一定要结冰”不通。"}, {"text": "那座古城一定要建于两千年前。", "explanation": "这里应该用〈大概〉。一定要表示必须、坚决，用于要求或决心；对过去的事作估计应说“大概”，“一定要建于”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一定要", "is_correct": true, "explanation": "语义：一定要表示说话人坚决要做到，与“他下了决心”相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：已经表示已经发生，与“下了决心”所指的将来目标矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不常发生，“考上大学”是一次性的结果，与句意不符。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：始终表示持续不变，不能与“考上大学”这种一次性结果搭配。"}], "explanations": {"一定要": "语义：一定要表示说话人坚决要做到，与“他下了决心”相符。", "已经": "语义：已经表示已经发生，与“下了决心”所指的将来目标矛盾。", "偶尔": "语义：偶尔表示不常发生，“考上大学”是一次性的结果，与句意不符。", "始终": "搭配：始终表示持续不变，不能与“考上大学”这种一次性结果搭配。"}, "sentence_index": 6, "correct_answer": "一定要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过这次事故，他的腿一定要残疾。", "explanation": "这里应该用〈必然〉。一定要表示必须、坚决，用于要求或决心；对不由人控制的结果作判断应说“必然”，“一定要残疾”不通。"}, {"text": "他一定要在那儿见过我。", "explanation": "这里应该用〈想必〉。一定要表示必须、坚决，用于要求或决心；推测过去的情况应说“想必”，“一定要见过”不通。"}, {"text": "月亮一定要是圆的。", "explanation": "这里应该用〈本来〉。一定要表示必须、坚决，用于要求或决心；陈述事物本来的样子应说“本来”，“一定要是圆的”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试我一定要已经考出好成绩。", "corrected_sentence": "这次考试我一定要考出好成绩。", "error_description": "“已经”表示已经发生，与“一定要”表示的将来决心相冲突，二者不能同时用在动词前；应去掉“已经”，写作“这次考试我一定要考出好成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一定要拿给这张证书。", "corrected_sentence": "我一定要拿到这张证书。", "error_description": "“拿”后的补语应为“到”，表示拿到手；“拿给”的“给”需要接受者，“拿给这张证书”不通，应说“我一定要拿到这张证书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
