INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山地是有很多山的地方。", "primary_collocate": null, "pronunciation": "shān dì", "ipa": "ʂan˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的北部是山地，夏天很凉快。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在山地，出门就能看见山。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地的路不好走，我们走了三个小时。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里是山地，平地很少。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地的冬天很冷，常常下雪。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山地长大，很会爬山。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山地的空气特别好。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地的村子离城市很远。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西南的山地风景很美，我们去那里拍了很多照片。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地里的天气变化很快，要带雨伞。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片山地", "label": "量词"}, {"form": "山地车", "label": "复合"}], "register": "中性", "sense_fingerprint": "有很多山的地方、地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山地", "is_correct": true, "explanation": "正确答案，指有很多山的地方。"}, {"text": "山底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是山的底部、山脚，与“有很多山的地方”不符。"}, {"text": "山低", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是山不高。"}, {"text": "三地", "is_correct": false, "explanation": "sān 与 shān 声母不同（s 与 sh），声调相同，意思是三个地方。"}], "explanations": {"山地": "正确答案，指有很多山的地方。", "山底": "dǐ（第三声）与 dì（第四声）声调不同，意思是山的底部、山脚，与“有很多山的地方”不符。", "山低": "dī（第一声）与 dì（第四声）声调不同，意思是山不高。", "三地": "sān 与 shān 声母不同（s 与 sh），声调相同，意思是三个地方。"}, "sentence_index": null, "correct_answer": "山地"}, "level_3": {"options": [{"text": "南部", "is_correct": false, "explanation": "语义：句中说“这个国家的北部是……”，“南部”与“北部”矛盾，句意不通。"}, {"text": "山地", "is_correct": true, "explanation": "正确答案，“山地”指多山的地区，与“北部”和“夏天很凉快”相符。"}, {"text": "热带", "is_correct": false, "explanation": "语义：热带的夏天很热，与后句“夏天很凉快”冲突。"}, {"text": "旮旯", "is_correct": false, "explanation": "语义：“旮旯”指角落、小地方，不能用来指一个国家的北部，句意不通。"}], "explanations": {"南部": "语义：句中说“这个国家的北部是……”，“南部”与“北部”矛盾，句意不通。", "山地": "正确答案，“山地”指多山的地区，与“北部”和“夏天很凉快”相符。", "热带": "语义：热带的夏天很热，与后句“夏天很凉快”冲突。", "旮旯": "语义：“旮旯”指角落、小地方，不能用来指一个国家的北部，句意不通。"}, "sentence_index": 0, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片山地连一个小山坡都没有，到处都是水。", "explanation": "这里应该用〈湖区〉。“山地”指多山的地区，“没有山坡、到处是水”说的是湖区。"}, {"text": "这里的山地很平，适合盖大工厂。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区，说“很平”、适合盖大工厂要用“平原”。"}, {"text": "这片山地一望无际，平得像一块大桌子。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区，“一望无际、平得像桌子”描述的是平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山地", "is_correct": true, "explanation": "正确答案，指有很多山的地方。"}, {"text": "山体", "is_correct": false, "explanation": "tǐ（第三声）与 dì（第四声）声母和声调都不同，意思是山的主体。"}, {"text": "山气", "is_correct": false, "explanation": "qì 与 dì 声调相同（第四声），声母不同（q 与 d），意思是山间的空气。"}, {"text": "闪电", "is_correct": false, "explanation": "闪电读 shǎn diàn，shǎn（第三声）与 shān（第一声）声调不同，diàn 与 dì 韵母不同，意思是下雨时天上的电光。"}], "explanations": {"山地": "正确答案，指有很多山的地方。", "山体": "tǐ（第三声）与 dì（第四声）声母和声调都不同，意思是山的主体。", "山气": "qì 与 dì 声调相同（第四声），声母不同（q 与 d），意思是山间的空气。", "闪电": "闪电读 shǎn diàn，shǎn（第三声）与 shān（第一声）声调不同，diàn 与 dì 韵母不同，意思是下雨时天上的电光。"}, "sentence_index": null, "correct_answer": "山地"}, "level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是地方，不能说“空气特别好”，句意不通。"}, {"text": "山地", "is_correct": true, "explanation": "正确答案，“这片山地”指一片多山的地区，与“空气特别好”相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是地方，不能说“空气特别好”，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能说“空气特别好”，句意不通。"}], "explanations": {"书包": "语义：书包是物品，不是地方，不能说“空气特别好”，句意不通。", "山地": "正确答案，“这片山地”指一片多山的地区，与“空气特别好”相符。", "课本": "语义：课本不是地方，不能说“空气特别好”，句意不通。", "眼镜": "语义：眼镜是物品，不能说“空气特别好”，句意不通。"}, "sentence_index": 6, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一片山地只有一座小山，没什么看头。", "explanation": "这里应该用〈小山〉。“山地”指多山的地区，只有一座小山时要说“小山”，不能用“山地”。"}, {"text": "这里的山地没有一座山，全是平地。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区，“没有一座山，全是平地”描述的是平原。"}, {"text": "他一个人爬完了整片山地，只用了十分钟。", "explanation": "这里应该用〈小山〉。“山地”指一大片多山地区，十分钟爬完整片不合常理，只爬一座小山才说“小山”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们走进了一个山地，四周都是树。", "corrected_sentence": "我们走进了一片山地，四周都是树。", "error_description": "错误在量词。“山地”指成片的地区，应使用量词“片”，不能用通用量词“个”。正确说法是“一片山地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们山地里迷路了，天快黑了。", "corrected_sentence": "我们在山地里迷路了，天快黑了。", "error_description": "错误在介词。“山地里”表示地点，前面要加介词“在”，应说“在山地里”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
