INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "多山的地区；山上的土地。", "primary_collocate": null, "pronunciation": "shān dì", "ipa": "ʂan˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "农民在山地上种了很多茶树。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块山地不能种水稻。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在山地里种玉米。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地的土不多，粮食也少。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把山地变成了果园。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地上的草长得很高。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山地一下雨就很滑。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国有很多山地，平原不太多。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山地里住着几户人家。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是山地，不适合开大型工厂。", "target_word": "山地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块山地", "label": "量词"}, {"form": "山地车", "label": "复合"}], "register": "中性", "sense_fingerprint": "山上可以耕种的土地；多山的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山地", "is_correct": true, "explanation": "正确答案，指山上可以耕种的土地或多山的地区。"}, {"text": "山底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是山的底部，不指耕地。"}, {"text": "三地", "is_correct": false, "explanation": "sān 与 shān 声母不同（s 与 sh），声调相同，意思是三个地方。"}, {"text": "山低", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是山不高。"}], "explanations": {"山地": "正确答案，指山上可以耕种的土地或多山的地区。", "山底": "dǐ（第三声）与 dì（第四声）声调不同，意思是山的底部，不指耕地。", "三地": "sān 与 shān 声母不同（s 与 sh），声调相同，意思是三个地方。", "山低": "dī（第一声）与 dì（第四声）声调不同，意思是山不高。"}, "sentence_index": null, "correct_answer": "山地"}, "level_3": {"options": [{"text": "水面", "is_correct": false, "explanation": "语义：水面上不能种茶树，与“农民在……上种了很多茶树”冲突。"}, {"text": "山地", "is_correct": true, "explanation": "正确答案，“山地”指可以耕种的土地，与“种了很多茶树”相符。"}, {"text": "冰川", "is_correct": false, "explanation": "语义：冰川上无法种茶树，与句中的耕种行为冲突。"}, {"text": "广场", "is_correct": false, "explanation": "搭配：“种茶树”要在土地上进行，广场一般不用来种茶树，搭配不当。"}], "explanations": {"水面": "语义：水面上不能种茶树，与“农民在……上种了很多茶树”冲突。", "山地": "正确答案，“山地”指可以耕种的土地，与“种了很多茶树”相符。", "冰川": "语义：冰川上无法种茶树，与句中的耕种行为冲突。", "广场": "搭配：“种茶树”要在土地上进行，广场一般不用来种茶树，搭配不当。"}, "sentence_index": 0, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块山地一座山也没有，全是沙子。", "explanation": "这里应该用〈沙漠〉。“山地”指多山的地区或山上的耕地，“一座山也没有，全是沙子”描述的是沙漠。"}, {"text": "这块山地一眼望不到头，平得像湖面。", "explanation": "这里应该用〈平原〉。“山地”指山上的土地或多山的地区，“平得像湖面”描述的是平原。"}, {"text": "这片山地一望无际，平得像一块大桌子。", "explanation": "这里应该用〈平原〉。“山地”指山上的土地或多山的地区，“一望无际、平得像桌子”描述的是平原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山地", "is_correct": true, "explanation": "正确答案，指山上可以耕种的土地或多山的地区。"}, {"text": "山顶", "is_correct": false, "explanation": "山顶读 shān dǐng，dǐng（第三声）与 dì（第四声）声调和韵母都不同，意思是山的最高处。"}, {"text": "山气", "is_correct": false, "explanation": "qì 与 dì 声调相同（第四声），声母不同（q 与 d），意思是山间的空气。"}, {"text": "闪电", "is_correct": false, "explanation": "闪电读 shǎn diàn，shǎn（第三声）与 shān（第一声）声调不同，diàn 与 dì 韵母不同，意思是下雨时天上的电光。"}], "explanations": {"山地": "正确答案，指山上可以耕种的土地或多山的地区。", "山顶": "山顶读 shān dǐng，dǐng（第三声）与 dì（第四声）声调和韵母都不同，意思是山的最高处。", "山气": "qì 与 dì 声调相同（第四声），声母不同（q 与 d），意思是山间的空气。", "闪电": "闪电读 shǎn diàn，shǎn（第三声）与 shān（第一声）声调不同，diàn 与 dì 韵母不同，意思是下雨时天上的电光。"}, "sentence_index": null, "correct_answer": "山地"}, "level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不会因为下雨而变滑，与“一下雨就很滑”冲突。"}, {"text": "山地", "is_correct": true, "explanation": "正确答案，“这片山地”指一片可耕种或多山的地面，与“一下雨就很滑”相符。"}, {"text": "政府", "is_correct": false, "explanation": "搭配：“这片”指一片地面，不能修饰“政府”这样的机构。"}, {"text": "海面", "is_correct": false, "explanation": "语义：海面不会因为下雨而变滑，与句意不符。"}], "explanations": {"天空": "语义：天空不会因为下雨而变滑，与“一下雨就很滑”冲突。", "山地": "正确答案，“这片山地”指一片可耕种或多山的地面，与“一下雨就很滑”相符。", "政府": "搭配：“这片”指一片地面，不能修饰“政府”这样的机构。", "海面": "语义：海面不会因为下雨而变滑，与句意不符。"}, "sentence_index": 6, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门前的山地上全是平原，没有一座山。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区或山上的土地，“全是平原，没有一座山”与其意思相反。"}, {"text": "他们说这片山地是平地，没有一座山，所以盖了房子。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区，“是平地，没有一座山”描述的是平原。"}, {"text": "我每天走过这片山地去上班，路上全是平地。", "explanation": "这里应该用〈平原〉。“山地”指多山的地区，“路上全是平地”描述的是平原，不是山地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想买一只山地种茶。", "corrected_sentence": "他们想买一块山地种茶。", "error_description": "量词错误：“山地”是一块块土地，前面应用量词“块”，不能用“只”（“只”多用于动物或成对物品）。应说“一块山地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民山地里种了几百棵果树。", "corrected_sentence": "农民在山地里种了几百棵果树。", "error_description": "错误在介词。“山地里”表示地点，前面要加介词“在”，应说“在山地里”，不能省略“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
