INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "照片里最小的一个小点。", "primary_collocate": null, "pronunciation": "xiàng yuán", "ipa": "ɕjɑŋ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "照片放大很多倍后，能看到一个个像元。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个像元都是一个很小的点。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片有很多像元。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "像元越多，照片就越清楚。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机照片的像元很小，眼睛看不清。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片放大，看到了一个像元。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个像元只有一种颜色。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着屏幕说：“这就是一个像元。”", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "像元太大，照片看起来就不清楚。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的像元排得整整齐齐。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "照片放大后能看到的最小的点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "像元", "is_correct": true, "explanation": "正确。“像元”是照片放大后能看到的最小小点，符合语境。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，照片放大后不会看到一个个房间。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：照片放大后看到的是一个个小点，不会是一辆辆汽车。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的想法，照片放大后看不到一个个道理。"}], "explanations": {"像元": "正确。“像元”是照片放大后能看到的最小小点，符合语境。", "房间": "语义：房间是空间，照片放大后不会看到一个个房间。", "汽车": "语义：照片放大后看到的是一个个小点，不会是一辆辆汽车。", "道理": "语义：道理是抽象的想法，照片放大后看不到一个个道理。"}, "sentence_index": 0, "correct_answer": "像元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屏幕上有一张像元，颜色看起来很亮。", "explanation": "这里应该用〈个〉。“张”用于纸张、平面物件，像元是小点，不能用“张”。"}, {"text": "照片的边缘有一条像元，很模糊。", "explanation": "这里应该用〈个〉。“条”用于长条形的东西，像元不能用“条”。"}, {"text": "我把这个像元洗出来送给妈妈。", "explanation": "这里应该用〈相片〉。像元是数字图像中的一个小点，不能洗印出来送人；指洗好的照片要用“相片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "像元", "is_correct": true, "explanation": "正确。“像元”只有一种颜色，符合“一个像元”的语境。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹本身有多种颜色，不可能只有一种颜色。"}, {"text": "国旗", "is_correct": false, "explanation": "语义：国旗有红、黄等多种颜色，不止一种颜色。"}, {"text": "万花筒", "is_correct": false, "explanation": "语义：万花筒里有多种颜色的碎片，不可能只有一种颜色。"}], "explanations": {"像元": "正确。“像元”只有一种颜色，符合“一个像元”的语境。", "彩虹": "语义：彩虹本身有多种颜色，不可能只有一种颜色。", "国旗": "语义：国旗有红、黄等多种颜色，不止一种颜色。", "万花筒": "语义：万花筒里有多种颜色的碎片，不可能只有一种颜色。"}, "sentence_index": 6, "correct_answer": "像元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台相机的像元很便宜，照片很清楚。", "explanation": "这里应该用〈价格〉。“便宜”说的是价格；像元是图像中的一个点，不能说价钱。"}, {"text": "这张照片的像元很苦，看起来很模糊。", "explanation": "像元不能用“苦”来形容：“苦”只用于味道，照片没有味道。"}, {"text": "这幅画的像元很细腻。", "explanation": "这里应该用〈画面〉。像元是单个小点，不能用来形容整幅画的细腻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些像元们都很小，我看不清。", "corrected_sentence": "这些像元都很小，我看不清。", "error_description": "错误在“像元们”：“们”只用于指人，不能加在“像元”后面；应去掉“们”，说“这些像元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块屏幕的每张像元都能发光。", "corrected_sentence": "这块屏幕的每个像元都能发光。", "error_description": "错误在量词“张”：“张”用于纸张、平面物件，不能数“像元”；应用“个”，说“每个像元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
