INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91270, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数字图像中最小的组成单元，即一个像点。", "primary_collocate": null, "pronunciation": "xiàng yuán", "ipa": "ɕjɑŋ˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "数字图像由许多像元组成。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个像元都有自己的亮度值。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星图像的像元大小是十米。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要读取每个像元的数值。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "像元的颜色由三个数字决定。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图像放大后，可以看清每个像元。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机的像元尺寸比较大。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件把相邻的像元合并成一个。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图像分辨率越高，像元就越多。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用程序改变了这个像元的颜色。", "target_word": "像元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "数字图像最小的组成单元，有亮度和颜色数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "像元", "is_correct": true, "explanation": "正确。“像元”是构成数字图像的单位，符合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是构成数字图像的单位，与“数字图像”不符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能组成图像，与“数字图像由许多……组成”不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是构成数字图像的单位，与“数字图像由许多……组成”不符。"}], "explanations": {"像元": "正确。“像元”是构成数字图像的单位，符合语境。", "乐器": "语义：乐器不是构成数字图像的单位，与“数字图像”不符。", "声音": "语义：声音不能组成图像，与“数字图像由许多……组成”不符。", "空气": "语义：空气不是构成数字图像的单位，与“数字图像由许多……组成”不符。"}, "sentence_index": 0, "correct_answer": "像元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要读取每一张像元的数值。", "explanation": "这里应该用〈个〉。“张”用于纸张、平面物件，不能数“像元”。"}, {"text": "这首歌的像元很好听。", "explanation": "这里应该用〈旋律〉。像元是数字图像中的一个点，不能形容歌曲好听。"}, {"text": "这本书一共有三百个像元。", "explanation": "这里应该用〈页〉。书的组成单位是“页”，像元只用于数字图像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "像元", "is_correct": true, "explanation": "正确。“像元”是相机图像的单位，与“尺寸比较大”搭配自然。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是另一种设备，不是这台相机的组成部分，“这台相机的手机尺寸”不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气没有“尺寸”这一属性，不能与“尺寸”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色没有“尺寸”这一说法，“颜色尺寸”搭配不当。"}], "explanations": {"像元": "正确。“像元”是相机图像的单位，与“尺寸比较大”搭配自然。", "手机": "语义：手机是另一种设备，不是这台相机的组成部分，“这台相机的手机尺寸”不通。", "天气": "搭配：天气没有“尺寸”这一属性，不能与“尺寸”搭配。", "颜色": "搭配：颜色没有“尺寸”这一说法，“颜色尺寸”搭配不当。"}, "sentence_index": 6, "correct_answer": "像元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个灯泡的像元很高。", "explanation": "这里应该用〈亮度〉。像元是图像的单位，不能用“高”形容明暗程度；说“亮度很高”才正确。"}, {"text": "这袋米的像元很大。", "explanation": "这里应该用〈颗粒〉。像元只用于数字图像，不能用来描述米粒；说“颗粒很大”才正确。"}, {"text": "这幅画的像元很美。", "explanation": "这里应该用〈画面〉。像元是图像中的单个点，不能用来说整幅画很美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些像元们都很亮，颜色很鲜艳。", "corrected_sentence": "这些像元都很亮，颜色很鲜艳。", "error_description": "错误在“像元们”：“们”只用于指人，不能加在“像元”后面；应去掉“们”，说“这些像元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕上每张像元都亮着。", "corrected_sentence": "屏幕上每个像元都亮着。", "error_description": "错误在量词“张”：“张”用于纸张、平面物件，不能数“像元”；应用“个”，说“每个像元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话或声音听起来使人不舒服，与“中听”构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰明白，与“中听”没有反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：“认真”形容态度，与“中听”的话语感受无反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话或声音听起来使人不舒服，与“中听”构成反义。", "清楚": "无关：“清楚”形容清晰明白，与“中听”没有反义关系。", "认真": "无关：“认真”形容态度，与“中听”的话语感受无反义关系。", "便宜": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌或事物好看，与“中听”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容清洁，与“中听”无反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，与“中听”的反义关系无关。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "漂亮": "无关：“漂亮”形容外貌或事物好看，与“中听”没有反义关系。", "干净": "无关：“干净”形容清洁，与“中听”无反义关系。", "高兴": "无关：“高兴”形容心情，与“中听”的反义关系无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "中听是话说出来，听着让人舒服。", "primary_collocate": null, "pronunciation": "zhòng tīng", "ipa": "ʈʂʊŋ˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "他的话很不中听，大家都不高兴。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话说得真中听，我心里很高兴。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良药苦口，忠言往往不中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话总是很中听，朋友都喜欢她。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这话不中听，说得太直接了。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夸我的几句话特别中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说的话虽然不中听，但是对我有用。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人说了几句中听的话，老板笑了。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话听着不中听，却是真话。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想说句不中听的话，你别生气。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不中听", "label": "否定"}, {"form": "中聽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "中听：话说得让人听着舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“很不中听”指话说得让人听着不舒服，与“大家都不高兴”呼应。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的岁数，不能用来形容“话”，句子不通。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”指人的情绪，不能用来说“话”高兴与否。"}, {"text": "健壮", "is_correct": false, "explanation": "语义：“健壮”形容人或动物的身体，与“话”搭配不当。"}], "explanations": {"中听": "正确。“很不中听”指话说得让人听着不舒服，与“大家都不高兴”呼应。", "年轻": "语义：“年轻”形容人的岁数，不能用来形容“话”，句子不通。", "高兴": "搭配：“高兴”指人的情绪，不能用来说“话”高兴与否。", "健壮": "语义：“健壮”形容人或动物的身体，与“话”搭配不当。"}, "sentence_index": 0, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子坐起来很中听。", "explanation": "这里应该用〈舒服〉。中听只用于言语，不能形容椅子坐着的感觉，坐着舒服要说舒服。"}, {"text": "这场比赛很中听。", "explanation": "这里应该用〈精彩〉。中听只用于说话、言论，不能用来评价比赛，比赛好看要说精彩。"}, {"text": "这道菜很中听。", "explanation": "这里应该用〈可口〉。中听只形容言语，不能用来形容食物，食物好吃要说可口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“不中听”指话说出来让人听着不舒服，与前一分句的“虽然”相呼应。"}, {"text": "好看", "is_correct": false, "explanation": "语义：“好看”形容外貌或景象，不能用来形容“话”。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，与“话”搭配不当。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容物体或身体坚固，不能用来形容说话。"}], "explanations": {"中听": "正确。“不中听”指话说出来让人听着不舒服，与前一分句的“虽然”相呼应。", "好看": "语义：“好看”形容外貌或景象，不能用来形容“话”。", "便宜": "搭配：“便宜”指价格低，与“话”搭配不当。", "结实": "语义：“结实”形容物体或身体坚固，不能用来形容说话。"}, "sentence_index": 6, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很中听。", "explanation": "这里应该用〈感人〉。中听形容说的话，不能用来评价电影，电影让人动容要说感人。"}, {"text": "这本书很中听。", "explanation": "这里应该用〈有趣〉。中听只用于言语，不能用来形容书，书好玩要说有趣。"}, {"text": "这间屋子很中听。", "explanation": "这里应该用〈整洁〉。中听只用于说的话，不能形容房间，房间干净要说整洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这番话说很中听，我很高兴。", "corrected_sentence": "他这番话说得很中听，我很高兴。", "error_description": "错误：“说很中听”，正确：“说得很中听”。“很中听”作程度补语，要用“得”连接动词和补语，漏掉“得”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她说了几句很中听话，我们都很高兴。", "corrected_sentence": "她说了几句很中听的话，我们都很高兴。", "error_description": "错误：“很中听话”，正确：“很中听的话”。“中听”修饰名词“话”时，中间要加“的”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”形容心情，不指话的听感，与“中听”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”形容清晰明白，与“中听”无反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "高兴": "无关：“高兴”形容心情，不指话的听感，与“中听”没有反义关系。", "清楚": "无关：“清楚”形容清晰明白，与“中听”无反义关系。", "便宜": "无关：“便宜”形容价格低，与“中听”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难听", "is_correct": true, "explanation": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "无关：“认真”形容态度，与“中听”没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容清洁，与“中听”无反义关系。"}, {"text": "精致", "is_correct": false, "explanation": "无关：“精致”形容做工或样式精细，与“中听”没有反义关系。"}], "correct_answer": "难听", "explanations": {"难听": "正确。“难听”指话听起来让人不舒服，与“中听”是反义关系。", "认真": "无关：“认真”形容态度，与“中听”没有反义关系。", "干净": "无关：“干净”形容清洁，与“中听”无反义关系。", "精致": "无关：“精致”形容做工或样式精细，与“中听”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "话听起来使人满意或舒服。", "primary_collocate": null, "pronunciation": "zhòng tīng", "ipa": "ʈʂʊŋ˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "老师夸我的话真中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挑了几句中听的话来安慰我。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这话说得不中听，她听了很生气。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同事嘴很甜，说的话都很中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不爱听奉承，可是他的话很中听。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得孩子的话中听，笑得很开心。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的批评一点也不中听，我听了很难受。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好话谁都爱听，中听的话让人心里暖。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要中听一些，别伤了别人的心。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的几句话不太中听，同桌听了不说话。", "target_word": "中听", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不中听", "label": "否定"}, {"form": "中聽", "label": "繁体"}], "register": "口语", "sense_fingerprint": "中听：话听起来让人满意、舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“真中听”指话让人听着舒服，与“老师夸我”的语境相符。"}, {"text": "刺耳", "is_correct": false, "explanation": "语义：“刺耳”指声音尖锐难听，与“老师夸我”的赞扬语境矛盾。"}, {"text": "难看", "is_correct": false, "explanation": "语义：“难看”形容外貌不好看，不能用来说“话”，且与“夸我”矛盾。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，不能用来形容“话”。"}], "explanations": {"中听": "正确。“真中听”指话让人听着舒服，与“老师夸我”的语境相符。", "刺耳": "语义：“刺耳”指声音尖锐难听，与“老师夸我”的赞扬语境矛盾。", "难看": "语义：“难看”形容外貌不好看，不能用来说“话”，且与“夸我”矛盾。", "便宜": "搭配：“便宜”指价格低，不能用来形容“话”。"}, "sentence_index": 0, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的菜很中听。", "explanation": "这里应该用〈好吃〉。中听只用于说的话，不能用来形容食物，食物味道好要说好吃。"}, {"text": "她穿的裙子很中听。", "explanation": "这里应该用〈漂亮〉。中听形容话语，不能形容衣服，衣服好看要说漂亮。"}, {"text": "躺在沙发上很中听。", "explanation": "这里应该用〈舒服〉。中听只用于言语，不能形容身体的感受，身体舒适要说舒服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中听", "is_correct": true, "explanation": "正确。“一点也不中听”指批评让人听着很不舒服，与“我听了很难受”呼应。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音响亮爽利，不用来形容“批评”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或事物的形体，不能用来形容“批评”。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”形容天气或感觉凉爽，与“批评”搭配不当，且与“很难受”的语境无关。"}], "explanations": {"中听": "正确。“一点也不中听”指批评让人听着很不舒服，与“我听了很难受”呼应。", "清脆": "语义：“清脆”形容声音响亮爽利，不用来形容“批评”。", "高大": "搭配：“高大”形容人或事物的形体，不能用来形容“批评”。", "凉快": "语义：“凉快”形容天气或感觉凉爽，与“批评”搭配不当，且与“很难受”的语境无关。"}, "sentence_index": 6, "correct_answer": "中听"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些蔬菜很中听。", "explanation": "这里应该用〈新鲜〉。中听只用于说的话，不能形容蔬菜，蔬菜不陈旧要说新鲜。"}, {"text": "这间教室很中听。", "explanation": "这里应该用〈宽敞〉。中听形容话语，不能形容教室，空间大要说宽敞。"}, {"text": "这些书摆得很中听。", "explanation": "这里应该用〈整齐〉。中听只用于言语，不能用来形容摆放，摆放有序要说整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说的几句话得中听，大家都笑了。", "corrected_sentence": "他说的几句话很中听，大家都笑了。", "error_description": "错误：“得中听”，正确：“很中听”。程度副词“很”修饰形容词，不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人听了我的几句很中听话，笑个不停。", "corrected_sentence": "老人听了我的几句很中听的话，笑个不停。", "error_description": "错误：“很中听话”，正确：“很中听的话”。“中听”修饰名词“话”时，中间要加“的”，漏掉“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
