INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91273, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "左边是你面朝前时，靠着左手的那一边。", "primary_collocate": null, "pronunciation": "zuǒ bian", "ipa": "tswɔ˨˩ pjɛn", "syllable_count": 2, "sentences": [{"text": "我的右边是小李，左边是小王。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过马路时，先看左边，再看右边。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店在银行的左边，很容易找。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你坐在我的左边，好吗？", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的左边坐着一位老先生。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边的门是厕所，右边的是办公室。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车开到了路的左边。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，学校左边有一家花店。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机在书包左边的口袋里。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，人们走路一般靠右边，不靠左边。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "左边儿", "label": "儿化"}, {"form": "左邊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "面朝前时靠左手的一边，与右边相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "左边", "is_correct": true, "explanation": "左边：与前句的“右边”相对，指另一侧，句意完整。"}, {"text": "右边", "is_correct": false, "explanation": "语义：前句已用“右边”指小李，这里再用“右边”指小王，两侧同名，不构成对比。"}, {"text": "左右", "is_correct": false, "explanation": "搭配：“左右”表示大约或两侧，不能指代一个具体的人或位置，不能放在“是小王”前作主语。"}, {"text": "上边", "is_correct": false, "explanation": "语义：“上边”指上方，与“右边”的左右方位不成对比，句意不通。"}], "explanations": {"左边": "左边：与前句的“右边”相对，指另一侧，句意完整。", "右边": "语义：前句已用“右边”指小李，这里再用“右边”指小王，两侧同名，不构成对比。", "左右": "搭配：“左右”表示大约或两侧，不能指代一个具体的人或位置，不能放在“是小王”前作主语。", "上边": "语义：“上边”指上方，与“右边”的左右方位不成对比，句意不通。"}, "sentence_index": 0, "correct_answer": "左边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他左边吃饭，左边看书。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}, {"text": "妈妈左边做饭，左边听广播。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}, {"text": "孩子左边哭，左边笑。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "左边", "is_correct": true, "explanation": "左边：指路的一侧，汽车开到这一侧，句意通顺。"}, {"text": "左脚", "is_correct": false, "explanation": "搭配：“左脚”指人的脚，不能用来指路的一侧。"}, {"text": "左耳", "is_correct": false, "explanation": "搭配：“左耳”指人的耳朵，不能用来指路的一侧。"}, {"text": "左手", "is_correct": false, "explanation": "搭配：“左手”指人的手，不能用来指路的一侧。"}], "explanations": {"左边": "左边：指路的一侧，汽车开到这一侧，句意通顺。", "左脚": "搭配：“左脚”指人的脚，不能用来指路的一侧。", "左耳": "搭配：“左耳”指人的耳朵，不能用来指路的一侧。", "左手": "搭配：“左手”指人的手，不能用来指路的一侧。"}, "sentence_index": 6, "correct_answer": "左边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们等了十分钟左边。", "explanation": "这里应该用〈左右〉。表示大约的数量要说「左右」，「左边」只指方位。"}, {"text": "他的政治观点太左边了。", "explanation": "这里应该用〈左倾〉。谈政治立场时要说〈左倾〉或〈左派〉，“左边”只表示方位，不能指政治观点。"}, {"text": "他习惯用左边写字。", "explanation": "这里应该用〈左手〉。写字用的是手，“左边”只指位置，不能指手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车停向路的左边。", "corrected_sentence": "车停在路的左边。", "error_description": "“向”表示朝某个方向移动，不能表示停在某处；表示所在的位置要用“在”，应为“车停在路的左边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花店学校的左边。", "corrected_sentence": "花店在学校的左边。", "error_description": "缺少介词“在”。“花店”后面要用“在”引出处所，应为“花店在学校的左边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
