INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面向前方时靠左手的一侧。", "primary_collocate": null, "pronunciation": "zuǒ bian", "ipa": "tswɔ˨˩ pjɛn", "syllable_count": 2, "sentences": [{"text": "舞台左边站着一个穿红衣服的女孩。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看黑板的左边，那里有今天的作业。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我习惯睡在床的左边，我太太睡右边。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的左边脸上有一道小疤。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向左边走三步，就能看到那棵大树。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院左边是超市，右边是医院。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在队伍的最左边，个子最高。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把行李放在椅子左边。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片里，站在左边的是我哥哥。", "target_word": "左边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我左边的牙疼了好几天。", "target_word": "左边", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "左边儿", "label": "儿化"}, {"form": "左邊", "label": "繁体"}], "register": "口语", "sense_fingerprint": "面向前方时靠左手的一侧，指位置或方位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "左边", "is_correct": true, "explanation": "左边：指舞台的左侧，句意通顺。"}, {"text": "左手", "is_correct": false, "explanation": "搭配：“左手”指人的手，不能用来指舞台的方位。"}, {"text": "左眼", "is_correct": false, "explanation": "搭配：「左眼」指人的眼睛，不能用来指舞台的方位。"}, {"text": "左腿", "is_correct": false, "explanation": "搭配：“左腿”指人的腿，不能用来指舞台的方位。"}], "explanations": {"左边": "左边：指舞台的左侧，句意通顺。", "左手": "搭配：“左手”指人的手，不能用来指舞台的方位。", "左眼": "搭配：「左眼」指人的眼睛，不能用来指舞台的方位。", "左腿": "搭配：“左腿”指人的腿，不能用来指舞台的方位。"}, "sentence_index": 0, "correct_answer": "左边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹左边唱歌，左边跳舞。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}, {"text": "爸爸左边看报，左边喝茶。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}, {"text": "老师左边讲课，左边喝水。", "explanation": "这里应该用〈一边〉。表示同时做两件事要说“一边……一边……”，“左边”只指方位，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "左边", "is_correct": true, "explanation": "左边：指队伍的左侧，与“最”搭配，句意通顺。"}, {"text": "左脚", "is_correct": false, "explanation": "搭配：“最左脚”不成立，“左脚”指人的脚，不能用来指队伍的位置。"}, {"text": "左眼", "is_correct": false, "explanation": "搭配：“最左眼”不成立，“左眼”指人的眼睛，不能用来指队伍中的位置。"}, {"text": "上方", "is_correct": false, "explanation": "语义：“上方”指高处，队伍是平面排列，不能说站在最上方，句意不合理。"}], "explanations": {"左边": "左边：指队伍的左侧，与“最”搭配，句意通顺。", "左脚": "搭配：“最左脚”不成立，“左脚”指人的脚，不能用来指队伍的位置。", "左眼": "搭配：“最左眼”不成立，“左眼”指人的眼睛，不能用来指队伍中的位置。", "上方": "语义：“上方”指高处，队伍是平面排列，不能说站在最上方，句意不合理。"}, "sentence_index": 6, "correct_answer": "左边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的政治态度太左边了。", "explanation": "这里应该用〈左倾〉。谈政治态度时要说〈左倾〉或〈左派〉，“左边”只表示方位，不能指政治立场。"}, {"text": "他走了大约一百米左边。", "explanation": "这里应该用〈左右〉。表示大约的数量要说「左右」，「左边」只指方位。"}, {"text": "他用左边拿筷子。", "explanation": "这里应该用〈左手〉。拿筷子用的是手，“左边”只指位置，不能指手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "售票处向大门的左边，你一进去就能看到。", "corrected_sentence": "售票处在大门的左边，你一进去就能看到。", "error_description": "“向”表示方向，不能表示事物所在的位置；表示位置要用“在”，应为“售票处在大门的左边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站队伍的左边。", "corrected_sentence": "他站在队伍的左边。", "error_description": "缺少介词“在”。“站”后面要用“在”引出处所，应为“他站在队伍的左边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
