INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91278, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "表示列举未尽，相当于“等等”。", "primary_collocate": null, "pronunciation": "zhī lèi", "ipa": "ʈʂɻ̩⁵⁵ leɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "我喜欢吃苹果、香蕉之类的水果。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有书、本子之类的东西。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常买面包、牛奶之类的早饭。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖笔、纸之类的文具。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有米、面之类的食品。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她包里有手机、钥匙之类的东西。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买了帽子、手套之类的冬天用品。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，要少吃糖、蛋糕之类的甜食。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有猫、狗之类的小动物。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱看足球、篮球之类的比赛。", "target_word": "之类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "列举几个例子后加“之类”，表示还有别的，相当于“等等”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之类", "is_correct": true, "explanation": "之类：表示列举未尽，相当于“等等”，修饰“水果”，与苹果、香蕉的例子相合。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”是疑问语气词，不能表示列举未尽，也不能放在名词前修饰“水果”。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”是语气词，表示疑问或停顿，不能表示还有别的同类。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，现代口语和普通书面语中不用，放在这里不合语域。"}], "explanations": {"之类": "之类：表示列举未尽，相当于“等等”，修饰“水果”，与苹果、香蕉的例子相合。", "吗": "语义：“吗”是疑问语气词，不能表示列举未尽，也不能放在名词前修饰“水果”。", "呢": "语义：“呢”是语气词，表示疑问或停顿，不能表示还有别的同类。", "哉": "语域：“哉”是文言语气词，现代口语和普通书面语中不用，放在这里不合语域。"}, "sentence_index": 0, "correct_answer": "之类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一共有三个学生，小明、小红、小刚之类的都来了。", "explanation": "穷尽列举：前面说明班上一共三个人，“之类”表示还有别的同类，与“一共三个人”矛盾，这里不能用。"}, {"text": "这位是我们学校的张校长之类。", "explanation": "特指：张校长是确定的一个人，“之类”表示还有同类的其他人，这里说明确切身份时不能用“之类”。"}, {"text": "我们明天下午三点之类在学校门口见。", "explanation": "约数：“之类”用于列举同类事物，不能用来表示时间的大概范围，“下午三点”是具体时间，这里不适用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之类", "is_correct": true, "explanation": "之类：表示列举未尽，相当于“等等”，与帽子、手套的例子相合。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”是完成体标记，不能夹在列举项和名词之间修饰“用品”。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”接在动词或形容词后作补语，不能接名词列举。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示经历，不能放在列举项和名词之间。"}], "explanations": {"之类": "之类：表示列举未尽，相当于“等等”，与帽子、手套的例子相合。", "了": "体貌：“了”是完成体标记，不能夹在列举项和名词之间修饰“用品”。", "得": "配价：“得”接在动词或形容词后作补语，不能接名词列举。", "过": "体貌：“过”表示经历，不能放在列举项和名词之间。"}, "sentence_index": 6, "correct_answer": "之类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们年级有三百人之类，今天都到齐了。", "explanation": "这里应该用〈左右〉。之类表示列举未尽，不能用来表示人数的大概，“三百人”是确定的数量。"}, {"text": "这本书是我妈妈之类送给我的。", "explanation": "特指：送书的人是确定的一个人（我妈妈），“之类”表示还有同类的其他人，这里不能用。"}, {"text": "这次考试我考了一百分之类。", "explanation": "这里应该用〈左右〉。之类不能表示分数的大概，“一百分”是确定的分数，应说“一百分左右”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了牛奶、面包之类地食物。", "corrected_sentence": "他买了牛奶、面包之类的食物。", "error_description": "错误形式是“之类地食物”，正确形式是“之类的食物”。“之类”修饰后面的名词时要用结构助词“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们买了小说、杂志之类得读物。", "corrected_sentence": "他们买了小说、杂志之类的读物。", "error_description": "错误形式是“之类得读物”，正确形式是“之类的读物”。“之类”修饰后面的名词时要用结构助词“的”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
