INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91279, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带回是把东西拿着一起回来。", "primary_collocate": null, "pronunciation": "dài huí", "ipa": "taɪ̯˥˩ xweɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我想从北京带回一些茶叶。", "target_word": "带回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从超市带回了很多水果。", "target_word": "带回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸出差回来，给我带回一个玩具。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把在国外买的书都带回家了。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去旅行的时候，别忘了给我带回礼物。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从老家带回了一只小狗。", "target_word": "带回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥带回一个好消息：他找到工作了。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些作业带回家做。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每次去海边，都会带回几个漂亮的贝壳。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从医院带回了药，让奶奶按时吃。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带回了", "label": "体标"}, {"form": "带回过", "label": "体标"}, {"form": "带回来", "label": "复合"}, {"form": "带回去", "label": "复合"}], "register": "中性", "sense_fingerprint": "从外地把东西或消息拿着一起带到家里或这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带回", "is_correct": true, "explanation": "带回：把茶叶拿着从北京回到说话人这里，与句意相符。"}, {"text": "带领", "is_correct": false, "explanation": "配价：「带领」的宾语应是人（如带领学生），不能接「一些茶叶」这样的物品。"}, {"text": "送到", "is_correct": false, "explanation": "配价：「送到」后面需要接一个地点或对象，不能直接接「一些茶叶」。"}, {"text": "运到", "is_correct": false, "explanation": "配价：「运到」后面需要接一个目的地，不能直接接「一些茶叶」。"}], "explanations": {"带回": "带回：把茶叶拿着从北京回到说话人这里，与句意相符。", "带领": "配价：「带领」的宾语应是人（如带领学生），不能接「一些茶叶」这样的物品。", "送到": "配价：「送到」后面需要接一个地点或对象，不能直接接「一些茶叶」。", "运到": "配价：「运到」后面需要接一个目的地，不能直接接「一些茶叶」。"}, "sentence_index": 0, "correct_answer": "带回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师带回学生参观博物馆。", "explanation": "这里应该用〈带领〉。「带回」指把东西拿回来，带人去某地参观要用〈带领〉。"}, {"text": "同学带回我去参加聚会。", "explanation": "这里应该用〈带去〉。「带回」指拿回原处，带人去别的地方要用「带去」，两者方向相反。"}, {"text": "班长带回大家打扫教室。", "explanation": "这里应该用〈带头〉。「带回」不能表示领着大家做事，带头做事要用〈带头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带回", "is_correct": true, "explanation": "带回：把好消息带回来告诉别人，与「找到工作了」的内容相符。"}, {"text": "卖掉", "is_correct": false, "explanation": "搭配：「消息」不能被「卖掉」，两者搭配不当。"}, {"text": "运走", "is_correct": false, "explanation": "搭配：「运走」用于货物，「消息」不能被运走。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：「扔掉」表示丢弃，与「好消息」的内容和语境相反，句意不合理。"}], "explanations": {"带回": "带回：把好消息带回来告诉别人，与「找到工作了」的内容相符。", "卖掉": "搭配：「消息」不能被「卖掉」，两者搭配不当。", "运走": "搭配：「运走」用于货物，「消息」不能被运走。", "扔掉": "语义：「扔掉」表示丢弃，与「好消息」的内容和语境相反，句意不合理。"}, "sentence_index": 6, "correct_answer": "带回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导游带回游客参观景点。", "explanation": "这里应该用〈引导〉。「带回」指把东西拿回来，带领游客去景点要用〈引导〉。"}, {"text": "教练带回队员参加比赛。", "explanation": "这里应该用〈带队〉。「带回」不能表示率领队员去参赛，要用〈带队〉。"}, {"text": "这次改革带回了一片掌声。", "explanation": "这里应该用〈赢得〉。「带回」指把东西拿回原处，获得掌声要说〈赢得〉，不能用「带回」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一袋面包带回家了。", "corrected_sentence": "他把一袋面包带回家了。", "error_description": "「把」漏掉了。处置对象「一袋面包」前要加「把」，应为「他把一袋面包带回家了」，不能说「他一袋面包带回家了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹从姥姥家带回回了一篮鸡蛋。", "corrected_sentence": "妹妹从姥姥家带回了一篮鸡蛋。", "error_description": "「回」多写了一个。「带回」是动补结构，「回」只能出现一次，应为「带回了一篮鸡蛋」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
