INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带着回到原处。", "primary_collocate": null, "pronunciation": "dài huí", "ipa": "taɪ̯˥˩ xweɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "请把借的书带回图书馆。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完雨伞以后，我把它带回了门口的伞架。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出门时带走的钥匙，记得带回来。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借来的相机带回学校，还给了老师。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把玩过的玩具带回原来的地方。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把扔出去的球带回主人身边。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去山上露营后，要把垃圾带回山下。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，周末要把练习本带回教室。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借走的工具全部带回了工具房。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走了，把杯子带回厨房吧。", "target_word": "带回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带回了", "label": "体标"}, {"form": "带回过", "label": "体标"}, {"form": "带回来", "label": "复合"}, {"form": "带回去", "label": "复合"}], "register": "中性", "sense_fingerprint": "把拿出去的东西携带着送回原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带回", "is_correct": true, "explanation": "带回：把借来的书拿着送回图书馆，与「借的书」的归还语境相符。"}, {"text": "借回", "is_correct": false, "explanation": "语义：「借回」表示从别处借来，与「借的书」归还到图书馆的语境相反。"}, {"text": "买回", "is_correct": false, "explanation": "语义：「买回」表示花钱买来，与「借的书」的语境矛盾。"}, {"text": "带走", "is_correct": false, "explanation": "配价：「带走」表示把东西拿离某处，不能以「图书馆」作为送达的终点。"}], "explanations": {"带回": "带回：把借来的书拿着送回图书馆，与「借的书」的归还语境相符。", "借回": "语义：「借回」表示从别处借来，与「借的书」归还到图书馆的语境相反。", "买回": "语义：「买回」表示花钱买来，与「借的书」的语境矛盾。", "带走": "配价：「带走」表示把东西拿离某处，不能以「图书馆」作为送达的终点。"}, "sentence_index": 0, "correct_answer": "带回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游带回游客参观寺庙。", "explanation": "这里应该用〈带领〉。「带回」指把东西拿回原处，带人去某地参观要用〈带领〉。"}, {"text": "妈妈带回我去超市买东西。", "explanation": "这里应该用〈带去〉。「带回」指带回原处，带人去别的地方要用「带去」。"}, {"text": "班长带回大家打扫教室。", "explanation": "这里应该用〈带头〉。「带回」不能表示领着大家做事，带头做事要用〈带头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带回", "is_correct": true, "explanation": "带回：把垃圾拿着回到山下，即原来的地方，与「露营后」的语境相符。"}, {"text": "带领", "is_correct": false, "explanation": "配价：「带领」的宾语应是人，不能说「把垃圾带领山下」。"}, {"text": "带上", "is_correct": false, "explanation": "语义：「上」指向上方，与「山下」的方向相反，句意不合。"}, {"text": "留给", "is_correct": false, "explanation": "配价：「留给」后面需要接受人作宾语，不能直接接地点「山下」。"}], "explanations": {"带回": "带回：把垃圾拿着回到山下，即原来的地方，与「露营后」的语境相符。", "带领": "配价：「带领」的宾语应是人，不能说「把垃圾带领山下」。", "带上": "语义：「上」指向上方，与「山下」的方向相反，句意不合。", "留给": "配价：「留给」后面需要接受人作宾语，不能直接接地点「山下」。"}, "sentence_index": 6, "correct_answer": "带回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带回很多快乐给我们。", "explanation": "这里应该用〈带给〉。「带回」指拿回原处，给人带来快乐要说〈带给〉。"}, {"text": "校长带回老师参观实验室。", "explanation": "这里应该用〈带领〉。「带回」指把东西拿回原处，带人去某地参观要用〈带领〉。"}, {"text": "他在会上带回了一场争吵。", "explanation": "这里应该用〈引发〉。「带回」指拿回原处，引起争吵要说〈引发〉，不能用「带回」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把饭盒带回了宿舍。", "corrected_sentence": "请把饭盒带回宿舍。", "error_description": "「了」用错了。「请」后面是对将来的要求，不能用表示完成的「了」，应为「请把饭盒带回宿舍」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他书包带回了教室。", "corrected_sentence": "他把书包带回了教室。", "error_description": "「把」漏掉了。处置对象「书包」前要加「把」，应为「他把书包带回了教室」，不能省略「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
