INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "全无；一点也没有（多用于书面）。", "primary_collocate": null, "pronunciation": "liǎo wú", "ipa": "liɑʊ˨˩˦ u˧˥", "syllable_count": 2, "sentences": [{"text": "湖面平静，了无波澜。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走后，屋里了无生气。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空干净，了无云影。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事过去很久，他心里了无怨恨。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完书，了无收获。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章了无特色，读起来很没意思。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人了无畏惧，一直往前走。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着离开，了无遗憾。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜深了，街上了无行人。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子了无变化，和多年前一样。", "target_word": "了无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "了無", "label": "繁体"}], "register": "书面", "sense_fingerprint": "了无：全无，多用于书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无波澜”表示水面没有一点起伏，与“平静”相合。"}, {"text": "驯服", "is_correct": false, "explanation": "搭配：“驯服”多用于动物或力量，不说“驯服波澜”。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”用于线、布，与水面的波动无关，句中不通。"}, {"text": "唤醒", "is_correct": false, "explanation": "搭配：“唤醒”多接意识、记忆，不接“波澜”。"}], "explanations": {"了无": "正确。“了无波澜”表示水面没有一点起伏，与“平静”相合。", "驯服": "搭配：“驯服”多用于动物或力量，不说“驯服波澜”。", "织": "语义：“织”用于线、布，与水面的波动无关，句中不通。", "唤醒": "搭配：“唤醒”多接意识、记忆，不接“波澜”。"}, "sentence_index": 0, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事过去很久，他心里了无很多怨恨。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "这件事过去很久，他心里了无更多的怨恨。", "explanation": "这里误把〈了无〉当成“比以前更多”的意思来用，但它表示全无，不能用于比较数量的多少。"}, {"text": "这件事过去很久，他心里了无很深的怨恨。", "explanation": "这里误把〈了无〉当成“程度深、很强烈”的意思来用，但它表示全无。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了无", "is_correct": true, "explanation": "正确。“了无畏惧”表示一点也不害怕，与“一直往前走”相合。"}, {"text": "雕刻", "is_correct": false, "explanation": "搭配：“雕刻”接物体，不接“畏惧”。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”接器物或关系，不说“修补畏惧”。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”与人的心理状态无关，句中不通。"}], "explanations": {"了无": "正确。“了无畏惧”表示一点也不害怕，与“一直往前走”相合。", "雕刻": "搭配：“雕刻”接物体，不接“畏惧”。", "修补": "搭配：“修补”接器物或关系，不说“修补畏惧”。", "播种": "语义：“播种”与人的心理状态无关，句中不通。"}, "sentence_index": 6, "correct_answer": "了无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个小村子了无很多变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“大量、许多”的意思来用，但它表示“一点也没有”。"}, {"text": "这个小村子了无很大的变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“程度大、很明显”的意思来用，但它表示全无，不能说有很大的变化。"}, {"text": "这个小村子了无最大的变化，和多年前一样。", "explanation": "这里误把〈了无〉当成“最、极其”的意思来用，但它表示全无，与“最大”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水面了无过涟漪。", "corrected_sentence": "这条河的水面了无涟漪。", "error_description": "错误：“了无过涟漪”，正确：“了无涟漪”。“了无”是一个书面词，表示一点也没有，后面直接接名词，不能插入表示经历的“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家旧书店的货架上了无很多新书。", "corrected_sentence": "这家旧书店的货架上了无新书。", "error_description": "错误：“了无很多新书”，正确：“了无新书”。“了无”表示全无，不能与“很多”连用，二者意思矛盾，应去掉“很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑暗", "is_correct": true, "explanation": "正确：黑暗与光明是反义词，指没有光亮。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不光滑，与光明没有反义关系。"}, {"text": "冰凉", "is_correct": false, "explanation": "冰凉形容温度低，与光明没有反义关系。"}, {"text": "干瘪", "is_correct": false, "explanation": "干瘪形容缺少水分、不饱满，与光明没有反义关系。"}], "correct_answer": "黑暗", "explanations": {"黑暗": "正确：黑暗与光明是反义词，指没有光亮。", "粗糙": "粗糙形容表面不光滑，与光明没有反义关系。", "冰凉": "冰凉形容温度低，与光明没有反义关系。", "干瘪": "干瘪形容缺少水分、不饱满，与光明没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑暗", "is_correct": true, "explanation": "正确：黑暗与光明是反义词，指没有光亮。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润形容含有水分，与光明没有反义关系。"}, {"text": "辛辣", "is_correct": false, "explanation": "辛辣形容味道，与光明没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆形容声音，与光明没有反义关系。"}], "correct_answer": "黑暗", "explanations": {"黑暗": "正确：黑暗与光明是反义词，指没有光亮。", "湿润": "湿润形容含有水分，与光明没有反义关系。", "辛辣": "辛辣形容味道，与光明没有反义关系。", "清脆": "清脆形容声音，与光明没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很亮，有光，让人觉得有希望。", "primary_collocate": null, "pronunciation": "guāng míng", "ipa": "kwɑŋ˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的前途很光明。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来了，天地都光明了。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的未来一定光明。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里点了灯，一下子光明起来了。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一条光明的路。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们相信明天是光明的。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏事过去了，前面是光明的日子。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光明的灯火让大家有了信心。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到光明的前景，心里很高兴。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于走出了山洞，眼前一片光明。", "target_word": "光明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "明亮有光，让人觉得有希望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae461367-2454-4efb-ad9b-fb4db9b634ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柔软", "is_correct": false, "explanation": "语义：柔软形容质地，不能用来形容前途。"}, {"text": "光明", "is_correct": true, "explanation": "正确：光明指明亮，也比喻有希望，符合“前途很……”的句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：锋利多形容刀刃，不说“前途很锋利”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：沙哑形容声音，与前途无关。"}], "explanations": {"柔软": "语义：柔软形容质地，不能用来形容前途。", "光明": "正确：光明指明亮，也比喻有希望，符合“前途很……”的句意。", "锋利": "搭配：锋利多形容刀刃，不说“前途很锋利”。", "沙哑": "语义：沙哑形容声音，与前途无关。"}, "sentence_index": 0, "correct_answer": "光明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的生意一天比一天惨淡，前景光明。", "explanation": "这里的“光明”指有希望、前景好，不能用来形容一天比一天惨淡的情况，这里应该用〈暗淡〉。"}, {"text": "前面的路很光明，却黑得伸手不见五指。", "explanation": "这里的“光明”指明亮，与“黑得伸手不见五指”矛盾；这里应该用〈黑暗〉。"}, {"text": "他的身体很光明，每天都能跑十公里。", "explanation": "这里的“光明”指明亮或前途有希望，不用来形容身体状况，这里应该用〈健康〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "湿润", "is_correct": false, "explanation": "语义：湿润形容物体潮湿，与日子的好坏无关。"}, {"text": "光明", "is_correct": true, "explanation": "正确：光明作定语修饰“日子”，表示有希望，与“坏事过去了”前后相合。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：宽敞多形容空间，不说“宽敞的日子”。"}, {"text": "肥胖", "is_correct": false, "explanation": "语义：肥胖形容人或动物的体型，不能形容日子。"}], "explanations": {"湿润": "语义：湿润形容物体潮湿，与日子的好坏无关。", "光明": "正确：光明作定语修饰“日子”，表示有希望，与“坏事过去了”前后相合。", "宽敞": "搭配：宽敞多形容空间，不说“宽敞的日子”。", "肥胖": "语义：肥胖形容人或动物的体型，不能形容日子。"}, "sentence_index": 6, "correct_answer": "光明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题讲得很光明，大家一听就懂。", "explanation": "这里应该用〈清楚〉。光明指明亮或前途有希望，不用来形容讲解是否清楚。"}, {"text": "他的前途很光明，可惜早已没有任何希望了。", "explanation": "这里的“光明”指有希望，与“早已没有任何希望”矛盾；这里应该用〈渺茫〉。"}, {"text": "这盘菜的味道很光明，大家都爱吃。", "explanation": "这里应该用〈鲜美〉。光明指明亮或前途有希望，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的发展前景很光明地，大家都看好它。", "corrected_sentence": "这家公司的发展前景很光明，大家都看好它。", "error_description": "“光明”作谓语时后面不加“地”，应说“很光明”，不能说“很光明地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的前途变很光明。", "corrected_sentence": "他的前途变得很光明。", "error_description": "“变”后接形容词作结果时要用补语“得”，应说“变得很光明”，不能说“变很光明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "节日", "is_correct": true, "explanation": "“平日”指不是节日的平常日子，“节日”与之相对，构成反义。"}, {"text": "早晨", "is_correct": false, "explanation": "无关：早晨指一天的开始时段，与“平日”没有反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "无关：书桌是家具，与“平日”没有反义关系。"}, {"text": "湖泊", "is_correct": false, "explanation": "无关：湖泊是自然事物，与“平日”没有反义关系。"}], "correct_answer": "节日", "explanations": {"节日": "“平日”指不是节日的平常日子，“节日”与之相对，构成反义。", "早晨": "无关：早晨指一天的开始时段，与“平日”没有反义关系。", "书桌": "无关：书桌是家具，与“平日”没有反义关系。", "湖泊": "无关：湖泊是自然事物，与“平日”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "节日", "is_correct": true, "explanation": "“平日”指不是节日的平常日子，“节日”与之相对，构成反义。"}, {"text": "黄昏", "is_correct": false, "explanation": "无关：黄昏指傍晚的时段，与“平日”没有反义关系。"}, {"text": "冰箱", "is_correct": false, "explanation": "无关：冰箱是家电，与“平日”没有反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "无关：森林是自然事物，与“平日”没有反义关系。"}], "correct_answer": "节日", "explanations": {"节日": "“平日”指不是节日的平常日子，“节日”与之相对，构成反义。", "黄昏": "无关：黄昏指傍晚的时段，与“平日”没有反义关系。", "冰箱": "无关：冰箱是家电，与“平日”没有反义关系。", "森林": "无关：森林是自然事物，与“平日”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "平日是不是节日的平常日子。", "primary_collocate": null, "pronunciation": "píng rì", "ipa": "pʰiŋ˧˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "平日里我喜欢跑步，节日就在家休息。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街平日很冷清，春节时特别热闹。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日他坐公交车上班，周日开车出门。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日我在公司吃饭，节日才回家吃。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶平日一个人住，春节孩子们都回来。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆平日八点开门，周末九点开门。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日的菜很简单，节日的菜才丰盛。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我平日不看电视，只在周末看一会儿。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日学生都在上课，校园里很安静。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日路上车不多，假期里路上很堵。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "平日：不是节日的平常日子，日常生活的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平日", "is_correct": true, "explanation": "平日指不是节日的平常日子，与后句“节日就在家休息”相对，符合句意。"}, {"text": "节假日", "is_correct": false, "explanation": "语义：节假日与后句的“节日”重叠，前后都是休息日，句意矛盾。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节本身就是节日，与后句“节日就在家休息”重复，句意矛盾。"}, {"text": "元旦", "is_correct": false, "explanation": "搭配：“元旦”是特定的一天，不能与泛指平常时间的“平日里”搭配。"}], "explanations": {"平日": "平日指不是节日的平常日子，与后句“节日就在家休息”相对，符合句意。", "节假日": "语义：节假日与后句的“节日”重叠，前后都是休息日，句意矛盾。", "春节": "语义：春节本身就是节日，与后句“节日就在家休息”重复，句意矛盾。", "元旦": "搭配：“元旦”是特定的一天，不能与泛指平常时间的“平日里”搭配。"}, "sentence_index": 0, "correct_answer": "平日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天过节，也是平日，大家都在家休息。", "explanation": "这里应该用〈节日〉。“过节”说明今天是节日，与“平日”指非节假日的意思相反。"}, {"text": "中秋节当天是平日，学校放假三天。", "explanation": "这里应该用〈假日〉。“平日”指非节假日，中秋节放假，是假日，不能称为平日。"}, {"text": "国庆节是平日，大家都出去旅游。", "explanation": "这里应该用〈节日〉。国庆节是节日，“平日”指不是节日的平常日子，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平日", "is_correct": true, "explanation": "平日指非节日的平常日子，与后句“节日的菜才丰盛”相对，符合句意。"}, {"text": "年夜饭", "is_correct": false, "explanation": "语义：年夜饭是节日才吃的饭，后句“节日的菜才丰盛”已说明节日的菜，此处再说年夜饭的菜很简单，句意矛盾。"}, {"text": "国庆节", "is_correct": false, "explanation": "语义：国庆节是节日，与后句“节日的菜才丰盛”重复且矛盾。"}, {"text": "中秋", "is_correct": false, "explanation": "语义：中秋是节日，“中秋的菜很简单”与后句“节日的菜才丰盛”矛盾。"}], "explanations": {"平日": "平日指非节日的平常日子，与后句“节日的菜才丰盛”相对，符合句意。", "年夜饭": "语义：年夜饭是节日才吃的饭，后句“节日的菜才丰盛”已说明节日的菜，此处再说年夜饭的菜很简单，句意矛盾。", "国庆节": "语义：国庆节是节日，与后句“节日的菜才丰盛”重复且矛盾。", "中秋": "语义：中秋是节日，“中秋的菜很简单”与后句“节日的菜才丰盛”矛盾。"}, "sentence_index": 6, "correct_answer": "平日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书平日很厚，我一个星期读不完。", "explanation": "这里应该用〈一般〉。“平日”是时间名词，不能用来描述书的厚薄；“一般”可表示通常或普通。"}, {"text": "今天是平日，学校和单位都放假。", "explanation": "这里应该用〈假日〉。“平日”指非节假日，“放假”所指的是节假日，二者互相矛盾。"}, {"text": "春节那天是平日，大家都去上班。", "explanation": "这里应该用〈节日〉。春节是法定节日，不能称为“平日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是很平日的早上，路上车很多。", "corrected_sentence": "这是平日的早上，路上车很多。", "error_description": "错误：“平日”是时间名词，不能受程度副词“很”修饰。正确说法是“这是平日的早上，路上车很多。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "平日的节日里，学生们都在教室，周末才去操场。", "corrected_sentence": "平日里学生们都在教室，周末才去操场。", "error_description": "错误：“平日”指非节假日，不能修饰“节日”，“平日的节日”前后矛盾。正确说法是“平日里学生们都在教室，周末才去操场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
