INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "平常的日子，非节假日。", "primary_collocate": null, "pronunciation": "píng rì", "ipa": "pʰiŋ˧˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "平日我很忙，周末才有时间休息。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店平日人少，节假日人很多。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日的下午，图书馆里几乎没有人，周末才热闹起来。", "target_word": "平日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平日的早上，地铁里总是挤满了人。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我平日穿得很简单，节日才穿新衣服。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园平日很安静，周末来玩的人多。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日妈妈上班，只有周末能在家做饭。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平日里孩子要上学，没有时间出去玩。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店的价格平日便宜，节假日会贵很多。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他平日不喝酒，春节才和家人喝一点。", "target_word": "平日", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "平日：非节假日的普通日子，与周末、节日相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平日", "is_correct": true, "explanation": "平日指非节假日的平常日子，与后句的“周末”相对，符合句意。"}, {"text": "星期天", "is_correct": false, "explanation": "语义：星期天属于周末，与后句“周末才有时间休息”自相矛盾。"}, {"text": "节假日", "is_correct": false, "explanation": "语义：节假日是放假休息的日子，与“周末才有时间休息”的前提冲突。"}, {"text": "星期日", "is_correct": false, "explanation": "语义：星期日属于周末，与后句“周末才有时间休息”自相矛盾。"}], "explanations": {"平日": "平日指非节假日的平常日子，与后句的“周末”相对，符合句意。", "星期天": "语义：星期天属于周末，与后句“周末才有时间休息”自相矛盾。", "节假日": "语义：节假日是放假休息的日子，与“周末才有时间休息”的前提冲突。", "星期日": "语义：星期日属于周末，与后句“周末才有时间休息”自相矛盾。"}, "sentence_index": 0, "correct_answer": "平日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天是除夕，也是平日，大家都在包饺子。", "explanation": "这里应该用〈节日〉。除夕是节日，与“平日”指非节假日的意思相反。"}, {"text": "端午节是平日，学校放假一天。", "explanation": "这里应该用〈节日〉。端午节放假，是节日，“平日”指非节假日，不能这样说。"}, {"text": "春节期间的平日，大家都在家团聚。", "explanation": "这里应该用〈节假日〉或〈假期〉。“平日”专指非节假日，春节期间整段时间都是节假日，不能称为平日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平日", "is_correct": true, "explanation": "平日指非节假日的日子，与“只有周末能在家”相呼应，符合句意。"}, {"text": "星期六", "is_correct": false, "explanation": "语义：星期六属于周末，与“只有周末能在家做饭”的前提矛盾。"}, {"text": "周末", "is_correct": false, "explanation": "语义：后句已用“周末”限定能在家的时间，此处再用“周末妈妈上班”自相矛盾。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“春节”是一年一次的特定节日，不能与“只有周末”这种每周规律搭配。"}], "explanations": {"平日": "平日指非节假日的日子，与“只有周末能在家”相呼应，符合句意。", "星期六": "语义：星期六属于周末，与“只有周末能在家做饭”的前提矛盾。", "周末": "语义：后句已用“周末”限定能在家的时间，此处再用“周末妈妈上班”自相矛盾。", "春节": "搭配：“春节”是一年一次的特定节日，不能与“只有周末”这种每周规律搭配。"}, "sentence_index": 6, "correct_answer": "平日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书平日很厚，读起来很费劲。", "explanation": "这里应该用〈一般〉。“平日”是时间名词，不能用来描述书的厚薄；“一般”可表示通常或普通。"}, {"text": "今天是平日，所以大家都放假。", "explanation": "这里应该用〈假日〉。“平日”指非节假日，而“放假”所指的正是节假日，二者意思相反。"}, {"text": "我们在平日过节，热闹得很。", "explanation": "这里应该用〈节日〉。“过节”要在节日里进行，而“平日”指非节假日，二者搭配矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天很平日，大家都在上班。", "corrected_sentence": "今天是平日，大家都在上班。", "error_description": "错误：“平日”是时间名词，不能受程度副词“很”修饰。正确说法是“今天是平日，大家都在上班。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很平日里大家都在上班，周末才放松一下。", "corrected_sentence": "平日里大家都在上班，周末才放松一下。", "error_description": "错误：“平日”是时间名词，不能受程度副词“很”修饰，“很平日里”不成话。正确说法是“平日里大家都在上班，周末才放松一下。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
