INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "列是把一样一样的东西，一个接一个写出来。", "primary_collocate": null, "pronunciation": "liè", "ipa": "li̯e˥˩", "syllable_count": 1, "sentences": [{"text": "请你把要买的东西列在纸上。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先列了一张购物清单。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们列出三个理由。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，他列好了今天要做的事。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把每天的开销都列在本子上。", "target_word": "列", "complexity_tier": "T3", "furigana": "tā bǎ měi tiān de kāi xiāo dōu liè zài běn zi shàng", "sentence_source": "generated"}, {"text": "请把你的问题一个一个列下来。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想列一张单子，不要忘了东西。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本子上列过很多想去的地方。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先列提纲，再写文章。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在列春节要买的东西。", "target_word": "列", "complexity_tier": "T3", "furigana": "mā ma zhèng zài liè chūn jié yào mǎi de dōng xi", "sentence_source": "generated"}], "morphological_forms": [{"form": "列了", "label": "完成体"}, {"form": "列过", "label": "经历体"}, {"form": "列着", "label": "持续体"}, {"form": "列表", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把事项逐条写出来：列清单、列计划、列提纲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91287, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：列（liè）指把事项一样一样写出来或排出来。"}, {"text": "谢", "is_correct": false, "explanation": "xiè 与 liè 声母不同（x / l），意思是感谢。"}, {"text": "立", "is_correct": false, "explanation": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是站立。"}, {"text": "料", "is_correct": false, "explanation": "liào 与 liè 韵母不同（ao / ie），意思是材料。"}, {"text": "咧", "is_correct": false, "explanation": "liē（第一声）与 liè（第四声）声调不同，意思是咧嘴。"}], "explanations": {"列": "正确：列（liè）指把事项一样一样写出来或排出来。", "谢": "xiè 与 liè 声母不同（x / l），意思是感谢。", "立": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是站立。", "料": "liào 与 liè 韵母不同（ao / ie），意思是材料。", "咧": "liē（第一声）与 liè（第四声）声调不同，意思是咧嘴。"}, "sentence_index": null, "correct_answer": "列"}, "level_3": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：“列在纸上”指把东西写在纸上，符合句意。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指用钱换取东西，不能说“买在纸上”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽进肚子，纸上的东西不能“吃”。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”要接话语作宾语，不能带“在纸上”这样的处所补语。"}], "explanations": {"列": "正确：“列在纸上”指把东西写在纸上，符合句意。", "买": "语义：“买”指用钱换取东西，不能说“买在纸上”。", "吃": "语义：“吃”指把食物咽进肚子，纸上的东西不能“吃”。", "说": "配价：“说”要接话语作宾语，不能带“在纸上”这样的处所补语。"}, "sentence_index": 0, "correct_answer": "列"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天列了一封长信给朋友。", "explanation": "这里应该用〈写〉。列是把事项一条条写出来，写信要用“写”，不用“列”。"}, {"text": "他在纸上列了一幅风景画。", "explanation": "这里应该用〈画〉。列用于一条条写出事项，画图要用“画”，不能用“列”。"}, {"text": "他在朋友面前列了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。讲笑话要用“讲”，列只用于把事项一条条写出来，不能用于说笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91287, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：列（liè）指把事项一样一样写出来或排出来。"}, {"text": "界", "is_correct": false, "explanation": "jiè 与 liè 声母不同（j / l），意思是界限。"}, {"text": "切", "is_correct": false, "explanation": "qiè 与 liè 声母不同（q / l），意思是切开。"}, {"text": "略", "is_correct": false, "explanation": "lüè 与 liè 韵母不同（üe / ie），意思是省略。"}, {"text": "利", "is_correct": false, "explanation": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是利益。"}], "explanations": {"列": "正确：列（liè）指把事项一样一样写出来或排出来。", "界": "jiè 与 liè 声母不同（j / l），意思是界限。", "切": "qiè 与 liè 声母不同（q / l），意思是切开。", "略": "lüè 与 liè 韵母不同（üe / ie），意思是省略。", "利": "lì（第四声）与 liè 韵母不同（i / ie），声调相同，意思是利益。"}, "sentence_index": null, "correct_answer": "列"}, "level_3": {"options": [{"text": "列", "is_correct": true, "explanation": "正确：“列一张单子”指把事项写成清单，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“一张单子”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，不能用于单子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出声音演唱，不能用于单子。"}], "explanations": {"列": "正确：“列一张单子”指把事项写成清单，符合句意。", "跳": "配价：“跳”是不及物动词，不能带“一张单子”作宾语。", "吃": "语义：“吃”指把食物咽下去，不能用于单子。", "唱": "语义：“唱”指发出声音演唱，不能用于单子。"}, "sentence_index": 6, "correct_answer": "列"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈去超市列了一些春节的礼物。", "explanation": "这里应该用〈买〉。列是把事项写成清单，不是买东西的动作，“买礼物”要用“买”。"}, {"text": "他在商店列了一件新衬衫。", "explanation": "这里应该用〈挑〉。在商店选衣服要用“挑”，列是写出事项的动作，不能用于选购。"}, {"text": "我出门时列了钥匙。", "explanation": "这里应该用〈带〉。出门时随身拿着钥匙要用“带”，列是写出事项，不能用于携带物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天列着一张清单。", "corrected_sentence": "我昨天列了一张清单。", "error_description": "错误在“着”。“着”表示动作持续或状态存在，而“昨天”指已经完成的动作，应该用“了”，即“我昨天列了一张清单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把要带的东西一个一个列出去。", "corrected_sentence": "我把要带的东西一个一个列出来。", "error_description": "错误在补语“出去”。“列出”后面要接“来”，表示把事项逐一写出来；“出去”表示向外离开，不能用在这里，应为“列出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
