INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91288, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排列；陈列。", "primary_collocate": null, "pronunciation": "liè", "ipa": "li̯e˥˩", "syllable_count": 1, "sentences": [{"text": "书店里的新书整齐地列在架子上。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里列着很多古代的东西。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的橱窗里列着各式各样的手表。", "target_word": "列", "complexity_tier": "T3", "furigana": "shāng diàn de chú chuāng lǐ liè zhe gè shì gè yàng de shǒu biǎo", "sentence_source": "generated"}, {"text": "同学们在操场上列成了两排。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门口列着两排花盆。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把椅子按顺序列在墙边。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柜台里列着各种各样的蛋糕。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货架上列着各种饮料。", "target_word": "列", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街道两旁列着一排路灯。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书按大小顺序列好了。", "target_word": "列", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "列了", "label": "完成体"}, {"form": "列着", "label": "持续体"}, {"form": "列队", "label": "复合词"}, {"form": "列表", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把东西按次序排好、摆出来：列在架子上、列成一排、橱窗里列着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
